class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer
  import Workspace._

  // toIntとか+7とかするならvalにしろ
  final private[this] val MOD = 1000000007

  def solve(): Unit = {
    import java.util
    val n = ni()
    val cnt = Array.ofDim[Int](n + 1)
    REP(n) { _ =>
      cnt(ni()) += 1
    }
    sort(cnt)
    reverse(cnt)
    val lst = cnt.indexWhere(_ == 0)
    val C = if (lst == -1) cnt else util.Arrays.copyOf(cnt, lst)
    val cum = cumSum(C)

    val MAX = isDebug(5, 3e5.toInt)
    val overs = Array.fill[Int](MAX + 1)(-1)
    REP(C.length) { i =>
      overs(C(i) - 1) = i
    }
    REP_r(overs.length - 1) { i =>
      if (overs(i) == -1) overs(i) = overs(i + 1)
    }
    debug(overs)

    def findGroupSize(k: Int): Int = {
      def f(g: Int) = {
        val overCnt = if (overs(g) == -1) 0 else cum(overs(g) + 1) - (overs(g) + 1) * g
        g.toLong * k <= cum.last - overCnt
      }
      findMax(f, 0, n)
    }

    debug(C)
    debug(cum)

    REP(n, 1) { k =>
      val ans = findGroupSize(k)
      out.println(ans)
    }
  }
