void solve() {
	ll N;
	cin>>N;
	vector<ll> a(N);
	rep(i,N)cin>>a[i];

	ll size=(ll)3e5+1;

	vector<ll> v(size,0);
	rep(i,N)v[a[i]]++;

	auto F = [](ll x,ll y){return x+y;}; //0LL
	SegmentTree<ll,decltype(F)> seg(size, F, 0LL);
	SegmentTree<ll,decltype(F)> segcount(size, F, 0LL);
	rep(i,size){
		if(v[i]){
			seg.update(v[i],seg[v[i]]+1);
			segcount.update(v[i],segcount[v[i]]+v[i]);
		}
	}
	debug(seg);
	debug(segcount);

	vector<ll> ans(N+1);
	repeq(q,N){
		ll maisu=N/q;
		ll anst=maisu;
		ll t=seg.query(maisu+1,N);
		if(t){
			ll s=segcount.query(t+1,N);
			ll nokori=N-(s-maisu*t);
			anst=nokori/q;
		}
		ans[q]=anst;
	}
	repeq(i,N)p(ans[i]);
