    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> A(N + 1);
    for (int i = 0; i < N; i++) {
        int x;
        cin >> x;
        ++A[x];
    }

    vector<int> C;
    for (int i = 1; i <= N; i++) {
        if (A[i])
            C.push_back(A[i]);
    }
    sort(C.begin(), C.end());

    vector<pair<int,int>> group;
    for (auto x : C) {
        if (group.empty() || group.back().first != x)
            group.emplace_back(x, 1);
        else
            ++group.back().second;          
    }
    sort(group.begin(), group.end());

    cout << N << '\n';
    for (int K = 2; K <= N; K++) {
        int ans = 0;

        int start = 0;
        int leftN = 0;
        vector<pair<int, int>> Q;

        for (int i = 0; i < int(group.size()) || leftN >= K; ) {
            while (start < int(Q.size()) && !Q[start].first)
                start++;
            for (; i < int(group.size()) && leftN < K; i++) {
                Q.push_back(group[i]);
                leftN += group[i].second;
            }
            if (leftN < K)
                break;

            int x = Q[start].first;
            int size = 0;
            for (int j = start; size < K; j++) {
                int t = min(Q[j].second, K - size); 
                size += t;

                if (Q[j].second == t) {
                    Q[j].first -= x;
                } else if (Q[j].first == x) {
                    Q[j].second -= t;
                    leftN -= t;
                } else {
                    int val = Q[j].first;
                    int cnt = Q[j].second;
                    Q[j].first = val - x;
                    Q[j].second = t;
                    Q.emplace(Q.begin() + j + 1, val, cnt - t);
                }
                if (!Q[j].first)
                    leftN -= Q[j].second;
            }
            ans += x;
        }
        cout << ans << '\n';
    }

    return 0;
}

