int compare(const void *a, const void *b)
{
    return *(int*)a - *(int*)b;
}

int recv(int *a, int size, int k, map<int, int> &m)
{
    int ans = 0;
    bool mapflag = false;
    while (1) {
        if (size < k) {
            return ans;
        } else if (size == k) {
            return ans + 1;
        } else if (size < k * 2) {
            return ans + 1;
        } else if (m.size() > 0) {
            auto i = m.begin();
            int h = 0;
            for ( ; i != m.end() && h < k; ++i) {
                if (i->second > 0) {
                    mapflag = true;
                    i->second--;
                    h++;
                }
            }
            if (!mapflag) {
                m.clear();
            } else {
                int n;
                for (n = k - h; n > 0; n--) {
                    if (size > 0) {
                        size--;
                    } else {
                        return ans;
                    }
                }
            }
        } else if (m.size() == 0) {
            return ans + size / k;
        }
    }
} 

