struct binaryindextree
{
    int sum[N];
    void update(int j,int x)
    {
        if(j==0)
            return ;
        for(;j<N;j+=j&(-j))
            sum[j]+=x;
    }
    int query(int j)
    {
        int x=0;
        for(;j>0;j-=(j)&(-j))
            x+=sum[j];
        return x;
    }
};
int cnt[N];
void solve()
