ll solve(ll t) {	//t 一次的数量
	ll ans = 0, i;
	t = m - t + 1;//从t到m取牌
	ans = d[t - 1];
	ll left = a[t], right = a[m] + ans;
	while (left < right) {
		ll mid = left + right+1 >> 1;//mid 最大次数
		ll* tt = lower_bound(a + t, a + m + 1, mid);
		ll x = tt - a;//坐标值
		ll y = x - t;//不够个数
		ll z = d[x - 1] - d[t - 1];//已有数量
		z = mid * y - z;//缺口
		if (z > ans)right = mid - 1;
		else left = mid;
	}
	return left;
}
