bool eat(int K, std::priority_queue<std::pair<int, int>> &q) {
  int rest = K;
  std::vector<std::pair<int, int>> eaten;
  while(! q.empty() && rest > 0) {
    auto p = q.top(); q.pop();
    if(p.first > 0) {
      --rest;
      eaten.push_back(std::make_pair(p.first - 1, p.second));
    }
  }
  if(rest == 0) {
    for(auto p : eaten) {
      q.push(p);
    }
    return true;
  } else {
    return false;
  }
}

