    ++cnt[A];
  }

  std::priority_queue<std::pair<int, int>> q0;
  rep(i, N) {
    q0.push(std::make_pair(cnt[i], i));
  }

  for(int K = 1; K <= N; ++K) {
    std::priority_queue<std::pair<int, int>> q(q0);
