{
  int n ;
  cin >> n ;
  int ans ;
  vector<int> vec(n,0) ;

  REP(i,n){
    int a ;
    cin >> a ;
    vec.at(a-1)++ ;
  }

  sort(ALL(vec)) ;
  reverse(ALL(vec)) ;

  FOR(i,1,n+1){
