constexpr bool bget(ll m, ll keta) {
    #ifdef _DEBUG
        assert(keta<=62);//オーバーフロー 1^62までしか扱えない
    #endif
    return (m >> keta) & 1; }
ll bget(ll m, ll keta, ll sinsuu) {    m /= (ll) pow(sinsuu, keta);    return m % sinsuu;}
constexpr ll bit(ll n) {
    #ifdef _DEBUG
        assert(n<=62);//オーバーフロー 1^62までしか扱えない
    #endif
    return (1LL << (n)); }
