    }
    for (int k = 1; k <= n; ++k) {
        int lo = 0, hi = n / k;
        int ans = lo;
        while (lo <= hi) {
            // can perform mid operation for current k?
            int mid = lo + hi >> 1;
            int p = lower_bound(c + 1, c + n + 1, mid) - (c + 1);
            int mink = n - p;
            if (p > 1) mink += pref[p - 1];
            if (mink >= k) {
                ans = mid;
                lo = mid + 1;
            }
            else 
                hi = mid - 1;
        }
        cout << ans << "\n";
    }
}

