  vector<int> a(n + 1), b(n + 1);
  for (int i = 0, x; i < n; ++i) {
    in >> x;
    a[x]++;
  }
  for (int i = 1; i <= n; ++i) {
    b[a[i]]++;
  }
  int sum2 = 0, sum1 = 0;
  for (int i = 1; i <= n; ++i) {
    sum2 += b[i];
  }
  vector<int> f(n + 1);
  for (int i = 1; i <= n; ++i) {
    sum1 += i * b[i];
    sum2 -= b[i];
    f[i] = (sum1 + i * sum2) / i;
  }
  f[0] = n;
  for (int i = 1; i <= n; ++i) {
    int l = upper_bound(f.begin(), f.end(), i, greater<>()) - f.begin() - 1;
    l = max(0, l);
    out << l << '\n';
  }
}

