template <typename T>
class starry_sky_tree {
    const static T inf = numeric_limits<T>::max() / 2;
public:
    starry_sky_tree(int n_)
        : n(expand(n_)), data(n * 2, 0), lazy(n * 2, 0)
    {}

    void add(int l, int r, T val) {
        l += n;
        r += n;
        int const left = l, right = r;
        while(l != r) {
            if(l & 1) {
                lazy[l] += val;
                data[l++] += val;
            }
            if(r & 1) {
                lazy[--r] += val;
                data[r] += val;
            }
            l /= 2;
            r /= 2;
        }
        l = left, r = right - 1;
        while(l /= 2, r /= 2) {
            data[l] = std::min(data[l * 2], data[l * 2 + 1]) + lazy[l];
            data[r] = std::min(data[r * 2], data[r * 2 + 1]) + lazy[r];
        }
    }

    T min(int l, int r) const {
        if(l == r) return inf;
        l += n;
        r += n;
        T res1 = inf, res2 = inf;
        while(l != r) {
            if(l & 1) {
                res1 = std::min(res1, data[l++]);
            }
            if(r & 1) {
                res2 = std::min(res2, data[--r]);
            }
            l /= 2;
            r /= 2;
            res1 += lazy[l - 1];
            res2 += lazy[r];
        }
        --l;
        while(l /= 2, r /= 2) {
            res1 += lazy[l];
            res2 += lazy[r];
        }
        return std::min(std::min(res1, res2), inf);
    }

private:
    int expand(int n) const {
        assert(n != 0);
        return n == 1 ? n : expand((n + 1) / 2) * 2;
    }

private:
    int const n;
    std::vector<T> data, lazy;
};

int main() {
    int n; cin >> n;
    int sz = 0;
    auto seg = [&] () {
        map<int, int> tmp;
        for(int i = 0; i < n; ++i) {
            int a; cin >> a;
            tmp[a] += 1;
        }
        vector<int> cnt;
        for(auto const& p : tmp) {
            cnt.push_back(p.second);
        }
        sz = cnt.size();
        sort(cnt.begin(), cnt.end(), greater<>{});
        starry_sky_tree<int> res(cnt.size());
        for(int i = 0; i < (int)cnt.size(); ++i) {
            res.add(i, i + 1, cnt[i]);
        }
        return res;
    }();

    vector<int> ans(n);
    for(int t = 1; t <= sz; ++t) {
        vector<pii> hist;
        while(seg.min(t - 1, t) > 0) {
            const int min_v = seg.min(t - 1, t);
            auto find_rpos = [&] (int val) {
                int lb = -1, ub = sz;
                while(ub - lb > 1) {
                    const int mid = (ub + lb) >> 1;
                    if(seg.min(mid, mid + 1) >= val) {
                        lb = mid;
                    } else {
                        ub = mid;
                    }
                }
                return ub;
            };
            const int rpos1 = find_rpos(min_v + 1);
            const int rpos2 = find_rpos(min_v);
            const int rest = t - rpos1;
            if(rpos1 != 0) {
                hist.emplace_back(0, rpos1);
                seg.add(0, rpos1, -1);
            }
            hist.emplace_back(rpos2 - rest, rpos2);
            seg.add(rpos2 - rest, rpos2, -1);
            ans[t - 1] += 1;
            //if(sz == 3) {
            //    cout << t << " " << rpos1 << " " << rpos2 << endl;
            //    cout << "array: ";
            //    for(int i = 0; i < sz; ++i) {
            //        cout << seg.min(i, i + 1) << " \n"[i + 1 == sz];
            //    }
            //}
        }
        for(auto const& p : hist) { // restore
            seg.add(p.first, p.second, 1);
        }
    }

    for(auto const& v : ans) {
        cout << v << endl;
    }
}

