vector<int> to_put;
int brute(int k, vector<int>& occs, vector<int>& remain) {
    priority_queue<int> pq(occs.begin(), occs.end());
    int ans = 0;
    while(pq.size() >= k) {
        for(int i = 0; i < k; i++) {
            to_put.push_back(pq.top());
            pq.pop();
        }
        int mini = *min_element(to_put.begin(), to_put.end());
        for(int x : to_put) {
            if(x - mini > 0) {
                pq.push(x - mini);
            }
        }
        to_put.clear();
        ans += mini;
    }
    while(not pq.empty()) {
        remain.push_back(pq.top());
        pq.pop();
    }
    return ans;
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    map<int, int> counter;
    for(int i = 0; i < n; i++) {
        int a;
        cin >> a;
        counter[a]++;
    }
    int sqrtn = int(sqrt(n)), lt = 0;
    vector<int> many_occ;
    for(auto& p : counter) {
        if(p.second <= sqrtn) {
            lt++;
        } else {
            many_occ.push_back(p.second);
        }
    }
    vector<int> a, remain;
    for(int k = 1; k <= n; k++) {
        if(k <= sqrtn) {        
            for(auto& p : counter) {
                a.push_back(p.second);
            }
            cout << brute(k, a, remain) << endl;
            a.clear();
            remain.clear();
        } else {
            int x = brute(k, many_occ, remain);
            cout << x + (lt + remain.size()) / k << endl;
            remain.clear();
        }
    }
    return 0;
}

