void solve() {
	ll N;
	cin>>N;
	vector<ll> a(N);
	rep(i,N)cin>>a[i];

	//ll size=(ll)3e5+1;
	ll size=8;

	vector<ll> v(size,0);
	rep(i,N)v[a[i]]++;

	auto F = [](ll x,ll y){return x+y;}; //0LL
	SegmentTree<ll,decltype(F)> seg(size, F, 0LL);
	SegmentTree<ll,decltype(F)> segcount(size, F, 0LL);
	rep(i,size){
		if(v[i]){
			seg.update(v[i],seg[v[i]]+1);
			segcount.update(v[i],segcount[v[i]]+v[i]);
		}
	}
	debug(seg);
	debug(segcount);

	vector<ll> ans(N+1);
	repeq(q,N){
		//初期は left->OK / right->NG になっています
		ll left = 0;
		ll right = N+1;
		//1ペアq枚、valペア作ることができるか?
		auto isOK = [&](ll val) -> bool {	
			ll t=seg.query(val+1,N+1);
			ll s=segcount.query(val+1,N+1);
			ll x=N-(s-t*val);
			return x>=q*val;
		};
		while((ll)abs(right - left) > 1) {
			ll mid = left + (right - left) / 2;
			if(isOK(mid)) left = mid;
			else right = mid;
		}
		ans[q]=left;
	}
	repeq(i,N)p(ans[i]);
}

signed main() {
	solve();	
	return 0;
}

