bool judge(int x,int k){
	int l=1,r=n,ans;
	while(l<=r){
		int mid=(l+r)/2;
		if(c[mid]<k&&(c[mid+1]>=k||mid==n)){
		    ans=mid;
		    break;
		}
		else if(c[mid]<k) l=mid+1;
		else r=mid-1;
	}
	if((n-ans)*x+q[ans]>=k*x) return true;
	return false;
}

