#include <bits/stdc++.h>
using namespace std;
const int MX = 3e5+1;
typedef long long ll;
int lsb(int i) {return i&(-i);}
struct BIT {
    vector<ll> bit, arr;
    int n;
    BIT() {};
    BIT(int _n) { bit.resize(_n+1);arr.resize(_n+1); n=_n;};
    void assign(int i, ll v) {
    	ll diff = v-arr[i];
    	arr[i] = v;
        while(i <= n) {
            bit[i] += diff;
            i += lsb(i);
        }
    };
    ll query(int i) {
        ll ret = 0;
        while(i) {
            ret += bit[i];
            i -= lsb(i);
        }
        return ret;
    };
    ll query_until(ll lb) {
    	int i = lower_bound(arr.begin()+1, arr.end(), lb, greater<int>()) - arr.begin();
    	i--;
    	//printf("lb=%d: query_until i=%d. queried by bit would be %d, subtract %d. ans is %d\n", lb, i, query(i), i*lb, query(i)-i*lb);
    	return query(i)-i*lb;
    }
    void decrement() {
    	int i = upper_bound(arr.begin()+1, arr.end(), arr[1], greater<int>()) - arr.begin();
    	assign(i-1, arr[1]-1);
    	//printf("after decrement, array is:");
		//print();
    }
    void print() {
    	for(int j=1; j<=n; j++) {
    		printf("%d ", arr[j]);
    	}
    	printf("\n");
    }
};
vector<int> qry[MX];
ll ans[MX];
int main() {
	ios::sync_with_stdio(0);cin.tie(0);
	map<int,int> mp;
	int n;
	cin >> n;
	BIT bit(n);
	for(int i=0; i<n; i++) {
		int t;
		cin >> t;
		mp[t]++;
	}
	vector<int> a;
	for(auto pr: mp)
		a.push_back(pr.second);
	sort(a.begin(), a.end(), greater<int>());
	for(int i=0; i<a.size(); i++) {
		bit.assign(i+1, a[i]);
	}
	//bit.print();
	for(int i=1; i<=n; i++) {
		qry[n%i].push_back(i);
	}
	for(int i=0; i<=n; i++) {
		if(i) bit.decrement();
		for(int q: qry[i]) {
			//printf("at processing query %d\n", q);
			int qu = bit.query_until(n/q);
			//printf("orig is %d. subtract query_until gives %d\n", n/q, n/q - qu);
			ans[q] = max(0, n/q - qu);
		}
	}
	for(int i=1; i<=n; i++) {
		cout << ans[i] << '\n';
	}
}

