struct Scanner {
    FILE* fp = nullptr;
    char line[1<<15];
    size_t st = 0, ed = 0;
    void reread() {
        memmove(line, line + st, ed - st);
        ed -= st;
        st = 0;            
        ed += fread(line + ed, 1, (1<<15) - ed, fp);
    }
    void succ() {
        while (true) {
            if (st == ed) reread();
            while (st != ed && isspace(line[st])) st++;
            if (st != ed) break;
        }
        if (ed - st <= 50) reread();
    }
    template <class T, enable_if_t<is_integral<T>::value, int> = 0>
    bool read_single(T& ref) {
        succ();
        bool neg = false;
        if (line[st] == '-') {
            neg = true;
            st++;
        }
        ref = T(0);
        while (isdigit(line[st])) {
            ref = 10 * ref + (line[st++] - '0');
        }
        if (neg) ref = -ref;
        return true;
    }
    Scanner(FILE* _fp) : fp(_fp) {}
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(20);
    Scanner sc(stdin);
    int n;
    sc.read_single(n);
//    cin >> n;
    V<int> freq(n);
    for (int i = 0; i < n; i++) {
        int a;
        sc.read_single(a); a--;
//        cin >> a; a--;
        freq[a]++;
    }
    sort(freq.begin(), freq.end());
    V<int> fsm(n + 1);
    for (int i = 0; i < n; i++) {
        fsm[i + 1] = fsm[i] + freq[i];
    }


    for (int k = 1; k <= n; k++) {
        int lw = 0, up = n + 1;
        while (up - lw > 1) {
            int md = (lw + up) / 2;
            int idx = lower_bound(freq.begin(), freq.end(), md) - freq.begin();
            int u = fsm[idx] + (n - idx) * md;
            if (u >= ll(md) * k) lw = md;
            else up = md;
        }
        cout << lw << "\n";
    }

    dbg(freq);


    return 0;
}

