//P = (同じ数が出てきた回数、　その数)

Int calc(deque<P> M, Int K, Int N){
  Int cnt = 0;
  if(K == 1) return N;

  while(1){
    vector<P> tmp;
    Int mn = INF;
    {
      Int sum = 0;
      while(sum < K){
        if(M.empty()) return cnt;
        auto t = M.front(); M.pop_front();
        sum += t.second;
        Min(mn, t.first);
        tmp.push_back(t);
      }
    }
    {
      Int sum = 0;
      for(Int i=0;i<(Int)tmp.size();i++){
        auto p = tmp[i];
        sum += p.second;
        if(i < (Int)tmp.size() - 1){
          p.first -= mn;
          if(p.first) M.push_back(p);
        }
        else{
          Int a = sum - K; //余剰分
          Int b = p.second - a; //減るやつ
          if(a) M.push_back(P(p.first, a));
          p.first -= mn;
          if(b && p.first) M.push_back(P(p.first, b));

        }
      }
      cnt += mn;
    }
  }
}

