int bs(int t){
	int l=-1,r=300004;
	while (r>l+1){
		int mid=(l+r)/2;
		int st=lower_bound(num+1,num+1+m,mid)-num;
		int did=n+1-st;
		int wants=t-did;
		if (1ll*d[st-1]>=1ll*wants*mid) l=mid;
		else r=mid;
	}
	return l;
}
