int main() {
	int N;
	scanf("%d\n", &N);

	std::map<int, int> cardMap;
	for (int i = 0; i < N; i++) {
		int n;
		scanf("%d", &n);

		auto it = cardMap.find(n);
		if (it != cardMap.end()) {
			//存在する
			it->second++;
		}
		else {
			//存在しない
			cardMap.emplace(n, 1);
		}
	}

	std::vector<std::pair<int, int>> cards(cardMap.begin(), cardMap.end());
	std::sort(cards.begin(), cards.end(), [](const auto& p1, const auto& p2) {return p1.second > p2.second; });
	//cards[0]が最も枚数が多い


	for (int K = 1; K <= N; K++) {
		std::vector<std::pair<int, int>> cardsTemp(cards);
		int count = 0;
		bool isEnd = false;
		while (!isEnd) {
			// K枚消費
			for (int i = 0; i < K; i++) {

				// 残ってる番号を探索
				bool found = false;
				for (auto& pair : cardsTemp) {
					if (pair.second <= 0) continue;

					found = true;
					pair.second--;
					break;
				}

				if (!found) {
					isEnd = true;
					break;
				}
			}
			if(!isEnd)count++;
		}

		printf("%d\n", count);
	}

	return 0;
}

