//**************   Cycle in Directed Graph *****************

bool findLoop(ll v,bool visited[]) 
{
  if(visited[v]==1)
    return 1;
  if(visited[v]==2)
    return 0;
  visited[v]=1;
  for(auto it:adj[v])
  {
    if(findLoop(it,visited))
      return 1;
  }
  visited[v]=2;
  return 0;
}

bool checkLoop(ll start ,ll end,bool visited[])     
{
  //  1  based  indexing 
  for(ll i=start;i<end;i++)    // for(i=1;i<=n;i++)
  {
    if(!visited[i] && findLoop(i,visited))
      return 1;
  }
  return 0;
}

