Int solve(int k){
    vector<P> small = cntcntv;
    vector<P> big;
    Int kind = 0;
    Int ans = 0;
    while(true){
        if(!big.empty() && big.back().first <= ans){
            kind -= big.back().second;
            big.pop_back();
        }
        while(!small.empty() && kind + small.back().second <= k){
            P tmp = small.back();small.pop_back();
            kind += tmp.second;
            big.push_back(tmp);
        }
        if(kind == k){
            ans++;
            continue;
        }
        if(small.empty())break;
        P tmp = small.back();small.pop_back();
        if(kind + tmp.second < k)break;
        ans++;
        P tmp2 = P(tmp.first-1, k - kind);
        tmp.second -= (k-kind);
        if(!small.empty() && small.back().first == tmp2.first){
            small.back().second += tmp2.second;
        }
        else{
            if(tmp2.first > 0)
                small.push_back(tmp2);
        }
        if(tmp.second != 0){
            small.push_back(tmp);
        }
    }
    return ans;
}

