int fn(int X,vector<int> & D,vector<int> &kD)
{
  if(X == 0) return I64_MAX;
  return (kD[X] + X*(D[D.size()-1] - D[X]))/X;
}

void solve()
{
  int N;
  cin>>N;
  vector<int> vec(N+1,0);
  for (int i = 0; i < N; i++)
  {
    int A;
    cin>>A;
    vec[A]++;
  }

  vector<int> D(N+1,0);
  for (int i = 0; i < N+1; i++)
  {
    D[vec[i]]++;
  }

  vector<int> kD(N+1,0);
  for (int i = 0; i <= N; i++)
  {
    kD[i] = i *D[i];
  }

  for (int i = 0; i <= N; i++)
  {
    D[i+1] += D[i];
    kD[i+1] += kD[i];
  }
  vector<int> X_1(N+1,0);
  for (int i = 1; i < N+1; i++)
  {
    X_1[i] = fn(i,D,kD);
  }

  for (int k = 1; k <= N; k++)
  {
    int X = N;
    int ANS;
    while(k > X_1[X] )X--;
    ANS = max((int)0,X);

    cout<<ANS<<endl;
  }

  return;
}

