int  comp(int *C, int elements, int K){
  int tmp=0;
  int el_org, i, j;

  //printf("element %d K %d\n",elements,K);

  while(elements >= K){
    el_org = elements;
    for(j=0;j<=elements/K;j++){
      tmp += C[j*K+K-1];
      for(i=0;i<K;i++){
	C[j*K+i] -= C[j*K+K-1];
	if(C[j*K+i]==0) elements--;
      }
    }
    sort(C,C+el_org,greater<>());    
    el_org = elements;
  }

  return tmp; 
}


