template<class Type>
Type solve(Type res = Type()){
    map<int,int> AtoCnt;
    int N; cin >> N;
    for(int i = 0; i < N;i++){
        int A; cin >> A;
        AtoCnt[A]++;
    }
    map<int,int> CntNum;
    for(auto p:AtoCnt){
        CntNum[p.second]++;
    }
    vector<pii> C;
    for(auto p:CntNum) C.push_back(p);
    sort(C.rbegin(),C.rend()); C.push_back(pii(0,0));
    int n = (int)C.size();

    // cout << C << endl;
    for(int K = 1; K <= N; K++){
        int ans = 0;
        priority_queue<pii> pq;
        int y = 0;
        for(int i = 1; i < n;i++){
            int dx = C[i-1].first - C[i].first;
            y += C[i-1].second;

            if(y < K){
                pq.push(pii(y,dx));
            }else{
                ans += y/K * dx;

                int L = (y*dx) - (y/K*K * dx);
                // cout << y << " " << dx << " " << K << endl;
                while(L && pq.size()){
                    pii p = pq.top(); pq.pop();

                    int ness = K - p.first;
                    int get = min(L/ness,p.second);
                    // cout << p << endl;
                    // cout << L << " " << ness << " " << get << endl;
                    p.second -= get;
                    ans += get;
                    L = L - ness*get;
                    if(p.second == 0) continue;

                    pq.push(pii(p.first+L,1));
                    if(p.second-1) pq.push(pii(p.first,p.second-1));
                }

                if(L){
                    pq.push(pii(L,1));
                }
            }
        }
        cout << ans << endl;
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    solve(0);
    // cout << fixed << setprecision(15) << solve<ll>() << endl;
    return 0;
}

