				if (chkmin(ans, (n - sum[j]) / (k - j)) == 1)
				{
					left = i + 1;
				}
				else
				{
					right = j - 1;
				}
			}
			else
			{
				if (chkmin(ans, (n - sum[j]) / (k - j)) == 1)
				{
					left = i + 1;
				}
				else
				{
					right = j - 1;
				}

			}
			}
			printf("%d\n", ans);
		}
		return 0;
	}

