        int left = 0; int right = n+1;
        while (right - left > 1) {
            int mid = (right + left) / 2;
            int l = -1; int r = q;
            while (r - l > 1) {
                int mi = (r + l) / 2;
                if (w[mi] > mid) l = mi;
                else r = mi;
            }
            long long val = (long long) (q-r) * mid - (c[q] - c[r]);
            if (remain >= val) left = mid;
            else right = mid; 
        }
        cout << left << "\n";
    }
    return 0;
}

