void solve(const V<ll> &cntlist, const V<ll> &acum, ll csize, ll k)
{
    ll bottom = csize - k;

    debug_printf("---------- k=%lld\n", k);

    if (bottom < 0LL) {
        cout << 0 << endl;
        return;
    }

    ll resource = acum[bottom];
    ll left = bottom;
    ll right = csize - 1LL;
    ll now = (left + right) / 2LL;
    ll found = -1LL;

    for ( ; left <= right; now = (left + right) / 2LL) {
        ll sum = acum[now+2] - acum[bottom];
        ll sq = (now + 2 - bottom) * cntlist[now+1];
        ll capa = sq - sum;
        debug_printf("now+2=%lld  bottom=%lld sum=%lld sq=%lld "
                     "capa=%lld resource=%lld\n",
                     now+2, bottom, sum, sq, capa, resource);
        if (resource < capa) {
            found = now;
            right = now - 1LL;
        }
        else {
            left = now + 1LL;
        }
    }

    debug_printf("k=%lld found=%lld\n", k, found);
    assert(found >= 0LL);

    debug_printf("---- ans %lld %lld\n", acum[found+1], found - bottom + 1LL);
    cout << acum[found+1] / (found - bottom + 1LL) << endl;
}

