    for (int i = n - 1; i >= 0; i--) {
      discard.at(i) += discard.at(i + 1);
    }
  }

  for (int k = 1; k <= n; k++) {
    int l = 0, r = n / k + 1;
    while (r - l > 1) {
      int mid = (l + r) / 2;
      if (k * mid <= n - discard.at(mid)) l = mid;
      else r = mid;
    }
    cout << l << '\n';
  }
}

