void solve() {
    int n;
    cin >> n;
    hashmap<int, int> cnt;
    vector<pii> arr;
    for (auto e : readvector<int>(n)) {
        cnt[e];
        arr.push_back({cnt[e]++, e});
    }
    vector<pii> order(cnt.begin(), cnt.end());
    sort(order.begin(), order.end(), [](pii A, pii B) { return A.y > B.y; });
    hashmap<int, int> pos;
    for (int i = 0; i < order.size(); i++) {
        pos[order[i].x] = i;
    }
    for (auto &e : arr) {
        e.y = pos[e.y];
    }
    sort(arr.begin(), arr.end());
    // for (auto e : arr) cout << e << endl;
    for (int k = 1; k <= n; k++) {
        pii prev = {0, -1e9};
        int steps = 0;
        for (int i = k - 1; i < n; i += k) {
            pii next = arr[i];
            // cout << prev << " ; " << next << endl;
            if ((next.x == prev.x && prev.y < next.y) ||
                (next.x == prev.x + 1 && next.y <= prev.y)) {
                ++steps;
            } else {
                break;
            }
            prev = next;
        }
        cout << steps << "\n";
    }
}

