struct UF {
  int n;
  vector< int > par;
  UF(int n) : n(n), par(n, -1) {}
  int find(int x) { return par[x] < 0 ? x : par[x] = find(par[x]); }
  int size(int x) { return -par[find(x)]; }
  bool same(int a, int b) { return find(a) == find(b); }
  void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if(a == b) return;
    if(par[a] < par[b]) swap(a, b);
    par[b] += par[a];
    par[a] = b;
  }
  void clear() { par.assign(n, -1); }
};

void solve(){
  using namespace mymylib;
  using namespace stdplus::iosplus;
  iosFast();
  int n; cin >> n;
  V<int> a(n); cin >> a;
  V<int> b(n); //map<int,int> c;
  FOR(i,0,n) b[a[i]-1]++;
  //for(auto x: b) if(x>0) c[x]++;
  //cout << b << '\n' << c << '\n' << c.size() << '\n';
  auto cal = [&](int k){
    int ans = 0;
    std::priority_queue<
      int,                // 要素の型はint
      std::vector<int>,   // 内部コンテナはstd::vector (デフォルトのまま)
      std::greater<int>   // 昇順 (デフォルトはstd::less<T>)
    > que;
    FOR(i,0,k) que.push(0);
    FOR(i,0,n+1){
      auto e = que.top();
      que.pop();
      e += b[i];
      que.push(e);
    }
    return que.top();
  };
  FOR(i,1,n+1){
    cout << cal(i) << '\n';
  }
}

