    rep(i, N) {
        tmap[A[i]]++;
    }

    vint V;
    for(pair<int, int> x: tmap) {
        V.PB(x.se);
    }
    sort(ALL(V));
    vint sum(V.size());

    rep(i, V.size()) {
        if (i) sum[i] = sum[i-1];
        sum[i] += V[i];
    }

    rep(t, 1, N+1) {
        int l = 0;
        int r = INF;

        while(r-l > 1) {
            ll mid = (r + l) / 2;
            int id = upper_bound(ALL(V), mid) - V.begin();

            ll tsum = 0;
            if (id) {
                tsum += sum[id-1];
            }
            tsum += mid * (V.size() - id);

            if (tsum >= mid * t) {
                l = mid;
            }
            else {
                r = mid;
            }
        }

        cout << l << endl;
    }

}


