long long arr[300015],pre[300015],idx[300015],ans[300015];

bool ok(long long n,long long x,long long val,long long tail)
{
    if(x>=n)return true;
    long long y;
    if(x==0)y=0;else y=pre[x-1];
    if((n-x)*val<=(pre[n-1]-y)+tail)return true;
    return false;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    memset(arr,0,sizeof(arr));
    long long n,m,i,j,x,lo,hi,mid,tail;
    cin>>n;
    for(i=0;i<n;i++){cin>>x;arr[x]++;}
    sort(arr,arr+n);reverse(arr,arr+n);
    for(i=300000;i>=arr[0];i--)idx[i]=0;
    j=1;
    for(i=arr[0]-1;i>0;i--){
        idx[i] = min(j,n-1);
        while(j<n-1 && i == arr[j])j++;
    }
    //for(i=arr[0];i>0;i--)cout<<idx[i]<<endl;
    pre[0] = arr[0];
    for(i=1;i<n;i++)pre[i]=pre[i-1]+arr[i];
    for(i=0;i<n;i++){
        tail = pre[n-1]-pre[i];
        lo = 1;hi = n;ans[i]=0;
        while(lo<=hi){
            mid=(lo+hi)/2;
            x = idx[mid];
            if(ok(i+1,x,mid,tail)){ans[i] = mid;lo=mid+1;}
            else hi=mid-1;
        }
    }
    for(i=0;i<m;i++)cout<<ans[i]<<endl;
	return 0;
}

