typedef long long li;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li n;
    cin >> n;
    map<li, li> counts;
    for (int i = 0; i < n; ++i) {
        li x;
        cin >> x;
        counts[x]++;
    }

    priority_queue<li> q;
    for (auto& t : counts) {
        q.push(t.second);
    }

    li ans = n, total = n;
    for (int k = 1; k <= n; ++k) {
        const li kind = q.size();
        if (kind < k) {
            cout << 0 << endl;
            continue;
        }
        while (ans > 0) {
            while (total > ans * k) {
                const li t = q.top();
                if (t <= ans) {
                    break;
                }
                total--;
                q.pop();
                if (t - 1 > 0) {
                    q.push(t - 1);
                }
            }
            if (q.top() <= ans && ans * k <= total) {
                break;
            } else {
                ans--;
            }
        }
        cout << ans << endl;
    }
    return 0;
}

