vector<pii> runlength(vector<int> v) {
  vector<pii> ret;
  int cnt = 1;
  int n = sz(v);
  rep3(i, 1, n) {
    if (v[i] == v[i - 1]) {
      cnt++;
    } else {
      ret.eb(v[i - 1], cnt);
      cnt = 1;
    }
  }
  ret.eb(v[n - 1], cnt);
  return ret;
}

