// binary search.
int_fast64_t bin(const std::function<bool(int_fast64_t)> &f,
                 int_fast64_t ok, int_fast64_t ng)
{
    while(std::abs(ok - ng) > 1)
    {
        int_fast64_t mid = (ok + ng) / 2;
        (f(mid) ? ok : ng) = mid;
    }
    return ok;
}
