i64 bin(i64 k, i64 l, i64 r) {
    if (l == r) {
        return l;
    }
    if (l + 1 == r) {
        if (f(k, r)) {
            return r;
        }
        else {
            return l;
        }
    }

    i64 t = (l + r) / 2;
    if (f(k, t)) {
        return bin(k, t, r);
    }
    else {
        return bin(k, l, t);
    }
}

