	for(int i = 0; i < n; i++) {
		int x;
		std::cin >> x;
		a[x-1]++;
	}
	std::sort(a.rbegin(), a.rend());
	while(a.back() == 0) a.pop_back();
	std::reverse(a.begin(), a.end());
	int pt = (int) a.size();
	int sum = n;
	int used = 0;
	for(int i = 1; i <= n; i++) {
		// a[pt-1] > n / i
		used++;
		while(pt > 0 && (long long) a[pt-1] * used > sum) {
			sum -= a[--pt];
			used--;
		}
		//std::cout << "at " << i << " got sum " << sum << ", using " << used << '\n';
		std::cout << (used == 0 ? 0 : sum / used) << '\n';
	}
