signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	V<int> base;
	{
		std::map<int, int> map;
		std::map<int, int> mp;
		REP(i, n) ++mp[a[i]];
		for (auto& p : mp) ++map[p.second];
		base.resize(map.rbegin()->first + 1, 0);
		for (auto& p : map) base[p.first] += p.second;
	}

	V<int> ans(n, 0);
	std::deque<PAIR> Y;
	auto push = [&](int a, int b) {
		int f = -1;
		if (!Y.empty()) f = Y.back().first;
		if (f == 0) return;
		if (f == a) {
			if ((Y.back().second += b) == 0) Y.pop_back();
		}
		else {
			Y.emplace_back(a, b);
		}
	};
	ans[0] = n;
	FOR(k, 2, n + 1) {
		auto X(base);
		int ma = base.size();
		Y.clear();
		while (true) {
			int now = 0;
			RFOR(i, 1, ma) {
				if (X[i] == 0) continue;
				if (now + X[i] >= k) {
					int t = k - now;
					push(i, -t);
					push(i - 1, t);
					now += t;
					break;
				}
				push(i, -X[i]);
				push(i - 1, X[i]);
				now += X[i];
			}
			if (now < k) break;
			while (!Y.empty()) {
				PAIR p = Y.front(); Y.pop_front();
				X[p.first] += p.second;
			}
			while (ma >= 1 && X[ma - 1] == 0) --ma;
			++ans[k - 1];
		}
		if (ans[k - 1] == 0) break;
	}
	REP(i, n) {
		OUT(ans[i])BR;
	}

	return 0;
}

