int n;
vector<int> cnt;
vector<int> sumcnt;

int solve(int k) {
	int l = 0, r = 300001;
	while (r - l > 1) {
		int m = (l + r) / 2;
		int overmind = lower_bound(cnt.begin(), cnt.end(), m) - cnt.begin();
		int overmnum = n - overmind;
		if (overmnum >= k) {
			l = m;
			continue;
		}
		int restind = overmind - (k - overmnum);
		int rest = sumcnt[overmind] - sumcnt[restind];
		int need = m * (k - overmnum) - rest;
		if (sumcnt[restind] >= need) {
			l = m;
		} else {
			r = m;
		}
	}
	return l;
}

