template <typename Iterator>
inline bool next_combination(const Iterator first, Iterator k, const Iterator last)
{
   /* Credits: Thomas Draper */
   if ((first == last) || (first == k) || (last == k))
      return false;
   Iterator itr1 = first;
   Iterator itr2 = last;
   ++itr1;
   if (last == itr1)
      return false;
   itr1 = last;
   --itr1;
   itr1 = k;
   --itr2;
   while (first != itr1)
   {
      if (*--itr1 < *itr2)
      {
         Iterator j = k;
         while (!(*itr1 < *j)) ++j;
         iter_swap(itr1,j);
         ++itr1;
         ++j;
         itr2 = k;
         rotate(itr1,j,last);
         while (last != j)
         {
            ++j;
            ++itr2;
         }
         rotate(k,itr2,last);
         return true;
      }
   }
   rotate(first,k,last);
   return false;
}

vector<int> va;
int maxcount;

void solve(int k, vector<int> vi, int count) {
    //cerr << "count: " << count <<  ", remain: ";
    //vecprint(vi);
    vector<int> vj(vi);

    if(k > vi.size()) {
        if(count > maxcount) maxcount = count;
        return;
    }

    do {
        bool flg2 = false;
        REP(j, k) {
            REP(l, k) {
                if(l <= j) continue;
                //cerr << va[vj[j]] << ", " << va[vj[l]] << endl;
                if(va[vj[j]] == va[vj[l]]) {
                    flg2 = true;
                    break;
                }
            }
            if(flg2) break;
        }
        if(flg2) continue;
        vector<int> vk;
        FOR(i, k, vj.size()) vk.push_back(vj[i]);
        solve(k, vk, count+1);
    } while(next_combination(vj.begin(), vj.begin()+k, vj.end()));
    if(count > maxcount) maxcount = count;
}

int main(void) {
    int n;
