        if(i == 1) {
            cout << n << endl;
            continue;
        }
        vector<int> vi(n);
        iota(vi.begin(), vi.end(), 0);
        maxcount = 0;
        solve(i, vi, 0);
        cout << maxcount << endl;
    }
}

