            for (int i = 0; i < k; ++i){
                pop_heap(c.begin(), c.end());
                v[i] = c.back();
                c.pop_back();
            }
            int diff = 1;
            if (v.back() > c.back()){
                diff = v.back() - c.back();
            }
            for (int i = 0; i < k; ++i){
                v[i] -= diff;
                if (v[i] > 0){
                    c.push_back(v[i]);
                    push_heap(c.begin(), c.end());
                }
            }

        }

    }
    return count;
}

