    cout << fixed << setprecision(20);
    Scanner sc(stdin);
    int n;
    sc.read_single(n);
//    cin >> n;
    V<int> freq(n);
    for (int i = 0; i < n; i++) {
        int a;
        sc.read_single(a); a--;
//        cin >> a; a--;
        freq[a]++;
    }
    sort(freq.begin(), freq.end());
    V<int> fsm(n + 1);
    for (int i = 0; i < n; i++) {
        fsm[i + 1] = fsm[i] + freq[i];
    }


    for (int k = 1; k <= n; k++) {
        int lw = 0, up = n + 1;
        while (up - lw > 1) {
            int md = (lw + up) / 2;
            int idx = lower_bound(freq.begin(), freq.end(), md) - freq.begin();
            int u = fsm[idx] + (n - idx) * md;
            if (u >= ll(md) * k) lw = md;
            else up = md;
        }
        cout << lw << "\n";
    }

    dbg(freq);


