int getNumberOfLarger(int u) {
    if (b[0] < u) return 0;

    int dau = 0, cuoi = SZ(b)-1;
    while (dau <= cuoi) {
        int mid = (dau + cuoi) >> 1;
        if (b[mid] >= u) dau = mid+1;
        else cuoi = mid-1;
    }
    return cuoi+1;
}

