        int N = n;
        int Min = 1000000000;
        if (cnt) {
            N = n - s[cnt-1];
            Min = b[cnt-1];
        }

        while (cnt < SZ(b) && b[cnt] > N / numOfGroup) {
            Min = min(Min, b[cnt]);
            N -= b[cnt];
            cnt++;
            numOfGroup--;
        }

        if (numOfGroup) numInEach = N / numOfGroup;
        else numInEach = 1000000000;

        cout << min(Min, numInEach) << "\n";
    }
    return 0;
}

