using namespace std;

long N;
map<long, long> mp;
vector<long> vec(300010);

map<long, long> answer_mp;

void foo (long k) {
  if (k == 1) {
    answer_mp[k] = N;
    return;
  }
  if (k > mp.size()) {
    answer_mp[k] = 0;
    return;
  }
  auto ub = answer_mp.upper_bound(k);
  auto bb = answer_mp.upper_bound(k);
  bb--;
  if (bb != answer_mp.end() and ub != answer_mp.end() and  bb->second == ub-> second) {
    answer_mp[k] = bb->second;
    return;
  }
  priority_queue<long> pq;
  for (auto it = mp.begin(); it != mp.end(); it++) {
    pq.push(it->second);
  }
  long ans = 0;
  while (true) {
    if (pq.size() < k) break;
    rep (i, k) {
      vec[i] = pq.top();
      pq.pop();
    }
    rep (i, k) {
      if (vec[i] > 1) pq.push(vec[i] - 1);
    }
    ans++;
  }
  answer_mp[k] = ans;
  return;
}

void bar(long from, long to) {
  long mid = (from + to) / 2;
  if (mid == from) return;
  foo(mid);
  bar(from, mid);
  bar(mid, to);
}

void solve() {
  cin >> N;
  rep (i, N) {
    long a;
    cin >> a;
    mp[a]++;
  }
  foo(1);
  foo(N);
  bar(1, N);
  for (long i = 1; i <= N; i++) cout << answer_mp[i] << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

