			int now = 0;
			std::map<int, int> Y;
			for (auto it = X.rbegin(); it != X.rend(); ++it) {
				if (now + it->second >= k) {
					int t = k - now;
					Y[it->first] += t;
					now += t;
					break;
				}
				Y[it->first] += it->second;
				now += it->second;
			}
			if (now < k) break;
			for (auto& p : Y) {
				if ((X[p.first] -= p.second) == 0) X.erase(p.first);
				if (p.first == 1) continue;
				X[p.first - 1] += p.second;
			}
			++ans[k - 1];
		}
	}
	REP(i, n) {
		OUT(ans[i])BR;
	}

	return 0;
}

