const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, k, sz;
mll cnt;
vl ans, dup, s;

bool judge(ll val){
    // dup[lb - 1] < val <= dup[lb]
    ll lb = lower_bound(all(dup), val) - dup.begin();
    // dup[sz - k], dup[sz - k + 1], ..., dup[sz - 1] >= val
    // -> not number to add
    if (sz - k >= lb) return true;

    ll num = val * (lb - (sz - k)) - (s[lb] - s[sz - k]);
    return num <= s[sz - k];
}

void solve(){
    ans = vl(n);
    rep(i, n){
        ll a; in1(a);
        cnt[a]++;
    }

    items(kv, cnt)
        dup.pb(kv.e2);
    sort(all(dup));
    sz = dup.size();

    s = vl(sz + 1, 0);
    rep(i, sz) s[i + 1] = s[i] + dup[i];

    rep(i, n){
        k = i + 1;
        if (k > sz) {ans[i] = 0; continue;}

        ll left = 0, right = n;
        while(right > left){
            // when seeking upper bound
            ll mid = (right + left + 1) / 2;
            if (judge(mid)) left = mid;
            else right = mid - 1;
        }
        ans[i] = right;
    }

    rep(i, n) prl(ans[i]);
}

int main(void){
    in1(n);
    // assert(k <= 100000);
    solve();
    return 0;
}

