set<pii,greater<pii>> st;

void ins(int val,int ct)
{
    //cout<<val<<"..."<<ct<<endl;
    if(ct==0 || val==0)
        return;
    //cout<<val<<"###"<<ct<<endl;
    auto it=st.lower_bound({val,0});
    if(it==st.end() || it->f!=val)
        st.insert({val,ct});
    else
    {
        st.insert({val,ct+it->s});
        st.erase(it);
    }
}

int func(int k)
{
    int ct,ans=0,ans2=0,nxt;
    auto it=st.begin();
    while(true)
    {
        ct=0;
        v2.clear();
        ans2=1e9;
        nxt=-1;
        while(!st.empty() && ct<k)
        {
            it=st.begin();
            ans2=min(ans2,(it->f));
            if((ct+it->s)>k)
            {
                v2.pb({it->f,k-ct});
                ins(it->f,it->s-(k-ct));
                ct=k;
            }
            else
            {
                ct=ct+it->s;
                v2.pb(*it);
                st.erase(it);
            }
            //cout<<ct<<endl;
        }
        //cout<<ct<<endl;
        if(ct<k)
            break;
        if(!st.empty())
        {
            nxt=(*st.begin()).f;
            for(int i=0;i<v2.size();++i)
            {
                // cout<<v2[i].f<<"__"<<nxt<<" "<<v2[i].s<<endl;
                ans2=min(ans2,(v2[i].f-(nxt-1))*v2[i].s);
                //cout<<ans2<<endl;
            }
        }
        //cout<<ans2<<endl;
        ans=ans+ans2;
        for(int i=0;i<v2.size();++i)
        {
            //cout<<v2[i].f<<".."<<ans2<<" "<<v2[i].s<<endl;
            // cout<<v2[i].f-ans2/v2[i].s+1<<":::"<<ans2%v2[i].s<<endl;
            // cout<<v2[i].f-ans2/v2[i].s<<";;;"<<(ans2-ans2%v2[i].s)<<endl;
            ins(v2[i].f-(ans2/v2[i].s+1),ans2%v2[i].s);
            ins(v2[i].f-ans2/v2[i].s,ans2-(ans2%v2[i].s));
        }
    }
    return ans;
}

