	for(int i=1,limi=sqrt(n),l,r;i<=n;){
		int ans=calc(i);
		if(i>limi){
			l=i,r=n;
			while(l<=r){
				int mid=l+r>>1;
				if(calc(mid)==ans) l=mid+1;
				else r=mid-1;
			}
		}
		else r=i;
		for(;i<=r;++i)
			printf("%d\n",ans);
	}
	return 0;
}

