signed main(){
    ios_base::sync_with_stdio(false);cin.tie(NULL);

    int n;cin >> n;
    unordered_map<int, int> cnt;
    int in;
    FOR(i, n){
        cin >> in;
        cnt[in]++;
    }
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    int xx = 0;
    vector<int> store[n];
    for(pii temp: cnt)pq.push(mp(temp.second, xx)), store[xx++].push_back(temp.second);
    stack<int> s;
    FORD1(i, n){
        if(pq.size() < i){
            s.push(0);
            continue;
        }
        while(pq.size() > i){
            pii tem = pq.top();
            pq.pop();
            sort(store[tem.second].begin(), store[tem.second].end());
            reverse(store[tem.second].begin(), store[tem.second].end());
            for(int temp: store[tem.second]){
                pii ref = pq.top();
                ref.first += temp;
                store[ref.second].push_back(temp);
                pq.pop();
                pq.push(ref);
            }
        }
        s.push(pq.top().first);
    }
    while(!s.empty()){cout << s.top() <<endl; s.pop();}

}

