ll cnt[300005];
bool cmp1(ll a, ll b)
{
    return a >= b;
}
bool vis[300005];
int main() {
    int n;
    cin >> n;
    vector<ll> nn;
    for (int i = 0; i < n; i++) {
        ll a;
        cin >> a;
        cnt[a]++;
        if (!vis[a]) {
            vis[a] = 1;
            nn.push_back(a);
        }
    }
    for (int i = 0; i < nn.size(); i++) {
        nn[i] = cnt[nn[i]];
    }
    sort(nn.begin(), nn.end(), cmp1);
    vector<ll> pre;
    pre.push_back(nn[0]);
    for (int i = 1; i < nn.size(); i++) {
        pre.push_back(pre.back() + nn[i]);
    }
    cout << n << '\n';
    for (ll i = 2; i <= n; i++) {
        ll l = 0, r = 1LL*n / i;
        while (l < r) {
            ll m = 1+l + r >> 1;
            ll p = lower_bound(nn.begin(),nn.end(), m,cmp1) - nn.begin();
            ll sum = pre.back();
            if (p)sum -= pre[p - 1];
            if (p >= i) {
                if (l == m)break;
                l = m;
            }
            else if (sum >= 1LL * m * (i - p)) {
                if (l == m)break;
                l = m;
            }
            else if (r == m)break;
            else r = m;
        }
        cout << l << '\n';
    }
    return 0;
}

