		while (true) {
			std::sort(cardsTemp.begin(), cardsTemp.end(), [](const auto& p1, const auto& p2) {return p1.second > p2.second; });
			int consume = K;// K枚消費すべし

			for (auto& pair : cardsTemp) {
				// 枚数が多いものから順に
				if (pair.second <= 0) continue;

				pair.second--;
