    number_count.push_back(1);
    for (size_t i = 1; i < N; ++i) {
      if (temp == An[i]) {
        ++number_count[number_count.size() - 1];
      } else {
        number_count.push_back(1);
        temp = An[i];
      }
    }
  }

  std::sort(number_count.begin(), number_count.end());

  // K = 1
  std::cout << An.size() << std::endl;

  for (int K = 2; K <= N; ++K) {
    int count = 0;
    auto copy_nc = number_count;
    auto boss = copy_nc.end() - 1;
    auto mover = copy_nc.end() - 2;
    auto flg = false;

    while (true) {
      if (mover < copy_nc.begin()) {
        if (flg && boss >= copy_nc.begin() && *boss > 0) {
          ++count;
        }
        break;
      }

      if (*boss == *mover) {
        count += (*mover) * 2;
        boss = mover - 1;
        mover = mover - 2;
        flg = true;
      } else if (*boss > *mover) {
        count += (*mover) * 2;
        *boss -= *mover;
        --mover;
        flg = false;
      } else {
        count += (*boss) * 2;
        *mover -= *boss;
        boss = mover;
        --mover;
        flg = true;
      }
    }

    std::cout << count / K << std::endl;
  }
  return 0;
}

