#define fst(t) std::get<0>(t)
#define snd(t) std::get<1>(t)
#define thd(t) std::get<2>(t)
#define unless(p) if(!(p))
#define until(p) while(!(p))

using ll = std::int64_t;
using P = std::tuple<int,int>;
using T = std::tuple<int,int,int>;

int N;
int C[300100], D[300100];
std::vector<P> E;

int sim(int k){
    int cur = 0;
    std::stack<T> front;
    std::stack<P> back;
    int total = 0;

    auto supply = [&](){
                      if(back.empty() && cur < E.size()){
                          back.emplace(E[cur]);
                          cur += 1;
                      }
                  };

    auto fill = [&](){
                    while(total < k){
                        supply();

                        if(back.empty()){return;}

                        int a, n;
                        std::tie(a, n) = back.top();
                        back.pop();

                        int m;

                        if(total + n <= k){
                            m = n;
                            total += n;
                        }else{
                            m = k - total;
                            back.emplace(a, n - (k - total));
                            total = k;
                        }

                        if(front.empty()){
                            front.emplace(a, m, 0);
                        }else{
                            int b, l;
                            std::tie(b, std::ignore, l) = front.top();

                            if(b - l == a){
                                snd(front.top()) += m;
                            }else{
                                front.emplace(a, m, 0);
                            }
                        }
                    }
                };

    fill();

    int res = 0;

    while(total == k){
        res += 1;

        int a, n, d;
        std::tie(a, n, d) = front.top();
        front.pop();

        if(a - d - 1 == 0){
            total -= n;
            fill();
        }else{
            supply();

            if(back.empty()){
                front.emplace(a, n, d + 1);
            }else{
                int b, m;
                std::tie(b, m) = back.top();

                if(a - d - 1 >= b){
                    front.emplace(a, n, d + 1);
                }else{
                    total -= n;

                    unless(front.empty()){
                        thd(front.top()) += d + 1;
                    }

                    back.pop();

                    if(back.empty()){
                        back.emplace(a - d - 1, n);
                    }else{
                        int c;
                        std::tie(c, std::ignore) = back.top();

                        if(c == a - d - 1){
                            snd(back.top()) += n;
                        }else{
                            back.emplace(a - d - 1, n);
                        }
                    }

                    back.emplace(b, m);

                    fill();
                }
            }
        }
    }

    return res;
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N;

    for(int i=0;i<N;++i){
        int A;
        std::cin >> A;

        C[A] += 1;
    }

    for(int i=1;i<=N;++i){
        D[C[i]] += 1;
    }

    for(int i=N;i>=1;--i){
        if(D[i] > 0){
            E.emplace_back(i, D[i]);
        }
    }

    for(int k=1;k<=N;++k){
        std::cout << sim(k) << std::endl;
    }
}

