using namespace std;
using ULL = unsigned long long;
using UL = unsigned;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	void Solve() {
		UL N; cin >> N;
		vector<UL> A(N);
		rep(i, N) {
			UL a; cin >> a; a--;
			A[a]++;
		}
		sort(A.rbegin(), A.rend());
		vector<UL> tall(N + 1);
		rep(i, N) tall[A[i]] = i + 1;
		rep(i, N) tall[N - i - 1] = max(tall[N - i - 1], tall[N - i]);
		vector<UL> SA(N + 1); rep(i, N) SA[i + 1] = SA[i] + A[i];
		vector<UL> ans(N);
		rep(i, N) {
			UL k = N - i;
			UL l = 0, r = N + 1;
			//cout << "k = " << k << endl;
			while (l + 1 < r) {
				UL m = (l + r) / 2;
				bool ok = false;
				UL pile = tall[m];
				UL j = SA[k];
				if (pile >= k) ok = true;
				else {
					j = SA[pile] + m * (k - pile);
					if (j <= N) ok = true;
				}
				(ok ? l : r) = m;
				//cout << "m = " << m << " : j = " << j << endl;
			}
			ans[k - 1] = l;
		}
		rep(i, N) cout << ans[i] << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
Problem::Problem() {
	cout << fixed << setprecision(10);
}

