			if(v[i] <= hako){
				cnt += sum[v.size()] - sum[i];
				break;
			}
			cnt += hako;
		}
		cnt /= hako;
		while(cnt > prev) ans[prev++] = hako;
	}
	for(int i : ans) cout << i << endl;

	return 0;
}

