const LL INF = 1e9 + 7;
const int N = 2e5 + 10;
int ans[N];
map<int, int> mc;
void solve(int key)
{
	if (ans[key] != -1) return;
	map<int, int> pq = mc;
	int& res = ans[key] = 0;
	while (!pq.empty())
	{
		int sum = 0;
		vector<pair<int, int>> vp;
		while (!pq.empty() && sum < key)
		{
			sum += pq.rbegin()->second;
			vp.push_back(*pq.rbegin());
			pq.erase(vp.back().first);
		}
		if (sum < key) break;
		if (vp.size() == 1)
		{
			int a, b;
			tie(a, b) = vp.back();
			res += b / key;
			if (a > 1 && b >= key)
				pq[a - 1] += b / key * key;
			if (a > 1 && b % key)
				pq[a] += b % key;
			continue;
		}
		res++;
		int cur = key;
		for (auto& p : vp)
		{
			int a, b;
			tie(a, b) = p;
			int o = min(cur, b);
			b -= o;
			cur -= o;
			if (a > 1) pq[a - 1] += o;
			if (b > 0) pq[a] += b;
		}
	}
	if (res == 0)
	{
		for (int i = key + 1; i < N; i++)
		{
			if (ans[key] == 0) break;
			ans[key] = 0;
		}
	}
}
