	for (int i = 1; i <= n; i++)
	{
		int x;
		cin >> x;
		mm[x]++;
	}
	for (auto& p : mm)
	{
		mc[p.second]++;
	}
	MEM(ans, -1);
	ans[1] = n;
	for (int i = 2; i <= n; i++)
		solve(i);
	for (int i = 1; i <= n; i++) printf("%d\n", ans[i]);
	return 0;
}

