template <class T> struct CumulativeSumG{
	ll s=0, e=-1;  vector<T> cum;
	CumulativeSumG(){};
	CumulativeSumG(vector<T> &v): e(v.size()-1), cum(e+2) { ini(v); }
	CumulativeSumG(vector<T> &v, ll S, ll E): s(S), e(E), cum(e-s+2){ ini(v); }
	void Init(vector<T> &v){ e=v.size()-1; cum.resize(e+2); ini(v); }
	void Init(vector<T> &v, ll S, ll E){ s=S; e=E; cum.resize(e-s+2); ini(v); }
	void Add(T x) { e++; cum.push_back(cum.back() + x); }
	T operator () (ll begin, ll end){ return cum[end+1-s] - cum[begin-s]; }
	void ini(vector<T> &v) { REPS(i, s, e) cum[i+1-s] = cum[i-s] + v[i]; }
};
using CumulativeSum = CumulativeSumG<ll>;


void solve()
{
	ll N;  cin >> N;
	vector<ll> A = cinv<ll>(N);
	vll h(N+1);
	EACH(e, A) h[e]++;

	map<ll, ll> k;
	EACH(e, h) k[e]++;

	ll NN = sz(k);
	vll hh(NN);
	vll kk(NN);
	vll ww(NN);
	ll count=0;
	EACH(e, k){
		hh[count] = e.first;
		kk[count] = e.second;
		ww[count] = hh[count]*kk[count];
		count++;
	}

	CumulativeSum wcum(ww);
	vll kkcum(NN+1);
	dep(i, NN-1, 0){
		kkcum[i] = kkcum[i+1] + kk[i];
	}

	vll maxK(N+2);
	rep(S, 1, N){
		ll m = upper_bound(ALL(hh), S) - hh.begin();
		ll M = kkcum[m];
		ll C = wcum(0, m-1);
		ll total = C+M*S;
		maxK[S] = total/S;
	}

	vll ans(N);
	dep(S, N, 1){
		ll preK = maxK[S+1];
		ll curK = maxK[S];
		rep(i, preK+1, curK){
			ans[i-1]=S;
		}
	}
	coutv(ans, '\n');
}

