class FDistinctNumbers {
public:

    priority_queue<int> que_orig;

    bool check(int i, int cnt) {
      auto que = que_orig;
      int ans = 0;
      while(que.size() >= i) {
        ans++;
        vector<int> vec;
        rep(j, i) {
          vec.push_back(que.top()); que.pop();
        }
        for(auto& e: vec) {
          if (e>1) {
            que.push(e-1);
          }
        }
        if (ans >= cnt) {
          return true;
        }
      }
      return false;
    }

    int count(int i) {
      auto que = que_orig;
      int ans = 0;
      while(que.size() >= i) {
        ans++;
        vector<int> vec;
        rep(j, i) {
          vec.push_back(que.top()); que.pop();
        }
        for(auto& e: vec) {
          if (e>1) {
            que.push(e-1);
          }
        }
      }
      return ans;
    }

    void solve(istream& cin, ostream& cout) {
      SPEED;
      int n; cin >> n;
      vector<int> cnt(n);
      rep(i, n) {
        int a; cin >> a;
        a--;
        cnt[a]++;
      }

      rep(i, n) {
        if (cnt[i] > 0) que_orig.push(cnt[i]);
      }

      vector<int> ans(n+1);

      int p = 0;
      int now = 0;
      for(int i=1; i*i<=n; i++) {
        p = i;
        ans[i] = count(i);
        now = ans[i];
      }

      debug(p, now);

      for(int i=1; i<=now; i++) {
        int ok = p;
        int ng = n+1;
        while(ok+1 < ng) {
          int med = (ok+ng)/2;
          if (check(med, i)) {
            ok = med;
          } else {
            ng = med;
          }
        }
        debug(i, ok);
        ans[ok] = i;
      }

      int ret = 0;
      for(int i=n; i>=1; i--) {
        chmax(ret, ans[i]);
        ans[i] = ret;
      }
      for(int i=1; i<=n; i++) {
        cout << ans[i] << '\n';
      }

    }
};

