using namespace std;

int  comp(int *C, int elements, int K){
  int tmp=0;
  int el_org, i;

  //printf("element %d K %d\n",elements,K);

  while(elements >= K){
    el_org = elements; 
    tmp += C[K-1];
    for(i=0;i<K;i++){
      C[i] -= C[K-1];
      if(C[i]==0) elements--;
    }
    sort(C,C+el_org,greater<>());
    el_org = elements;
  }

  return tmp; 
}


