#include <bits/stdc++.h>
using namespace std;
#define int long long
#define pi pair<int,int>
#define ff first
#define ss second
#define boost ios::sync_with_stdio(false);cin.tie(nullptr)
#define endl "\n"

const int N = 303;
int dp[N][N];
vector < pi > g[N];
int n, m, l;

void bfs(int sr) {
	int visit[n + 1] = {0};
	multiset < array < int ,3> > q;
	dp[sr][sr] = 0;
	q.insert({l, 0, sr});
	while(!q.empty()) {
		array < int , 3 > x = *q.begin();
		q.erase(x);
		int u = x[2], cnt = x[1], cur = x[0];
		if(visit[u])
			continue;
		visit[u] = 1;
		//cout << u <<' ' << cnt << ' ' << cur << endl;
		for(auto v : g[u]) {
			if(v.ss > l or visit[v.ff])
				continue;
			int add = cnt, petrol = cur;
			if(petrol < v.ss) {
				add++;
				petrol = l;
			}
			if(dp[sr][v.ff] >= add) {
				dp[sr][v.ff] = add;
				q.insert({petrol - v.ss ,add, v.ff });
			}
		}	
	}
}

