int main() {
    // 計数する
    int N; cin >> N;
    vector<long long> C(N, 0);
    for (int i = 0; i < N; ++i) {
        int a; cin >> a; --a;
        C[a]++;
    }

    // 各 K に対して
    for (long long K = 1; K <= N; ++K) {
        // 二分探索
        long long low = 1, high = N+1;
        while (high - low > 1) {
            long long x = (low + high) / 2;
            long long S = 0;
            for (int i = 0; i < N; ++i) S += min(C[i], x);
            if (S >= K * x) low = x;
            else high = x;
        }
        cout << low << endl;
    }
}

