	if (maxEat >= key * index) {
		return true;
	}
	else {
		return false;
	}
}

// 汎用的な二分探索のテンプレ
int binary_search(int key) { //k(同時に食べる枚数) = keyとしたとき、食べることができる回数を返す
	int ng = N + 1; //「index = 0」が条件を満たすこともあるので、初期値は -1
	int ok = -1; // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

	// ok と ng のどちらが大きいかわからないことを考慮
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		if (isOK(mid, key)) ok = mid;
		else ng = mid;
	}
	return ok;
}

