#define ROF(i, x, y) for(int i = x; i >= y; i--)
#define sf scanf

struct Node{
    int ff, ss;
    bool operator<(const Node &a)const{
        if(ff != a.ff) return ff<a.ff;
        return ss<a.ss;
    }
};
set<Node> Q;

inline void insertToSet(int val, int cnt){
    if(Q.empty() or ((*Q.begin()).ff > val)) Q.insert({val, cnt});//, debug("inserting", val, cnt);
    else {
        auto now = (*Q.begin());
        Q.erase(Q.begin());
        Q.insert({val, now.ss + cnt});
        // debug("inserting", val, now.ss + cnt);
    }
}

inline void addToSet(int add){
    // debug("adding", add);
    while(add){
        auto now = (*Q.begin());
        Q.erase(Q.begin());
        // debug("now", add, now.ff, now.ss);
        if(now.ss <= add){
            insertToSet(now.ff+1, now.ss);
            add -= now.ss;
        }
        else{
            insertToSet(now.ff + 1, add);
            insertToSet(now.ff, now.ss - add);
            add = 0;
        }
    }
}

