int N, A[MAX];
ll s[MAX];

ll sub(int k) {
    ll ok = 0, ng = MAX;
    while (ng - ok > 1) {
        ll mid = (ng + ok) / 2;
        if (s[mid]/mid >= k) ok = mid;
        else ng = mid;
    }
    return ok;
}

vi solve() {
    map<ll, ll> m;
    REP (i, N) m[A[i]]++;
    vi cnt;
    for (auto iter = m.begin(); iter != m.end(); iter++) {
