    numberOfDifferentCards = cards.size();
}

int countHowMany(int k){
    if (k == 1){
        return numberOfCards;
    }else if(k > numberOfDifferentCards){
        return 0;
    }
    vector<int> c(cards.begin(), cards.end());
    int count = 0;
    vector<int> v(k);
    while (c.size() >= k){
        if(c.size() == k){
            count += *min_element(c.cbegin(), c.cend());
            //c.clear();
            break;
        }else{
            count++;
            for (int i = 0; i < k; ++i){
                pop_heap(c.begin(), c.end());
                v[i] = c.back();
                c.pop_back();
            }
            int diff = 1;
            if (v.back() > c.front()){
                diff = v.back() - c.front();
            }
            for (int i = 0; i < k; ++i){
                v[i] -= diff;
                if (v[i] > 0){
                    c.push_back(v[i]);
                    push_heap(c.begin(), c.end());
                }
            }

        }

    }
    return count;
}

