		int ans=n,i=n;
	 	for(int k=1; k<=n; k++) {
			while(1) {
				while(i>0 && f[i-1]>ans) --i;
				if(ans*(n-i)+s[i]>=k*ans) break;
				ans--;
			}		
			cout << ans << '\n';
	 	} 		
 	};
