//初手2分探索
//x回食べることができるか
//Ei = min(x, Ci) 
//Eiの総和 >= k * x

void solve() {
	int n; cin >> n;
    vector<int> d(n + 1, 0);
	vector<int> s(n + 1, 0);
    rep(i, n) {
		int a; cin >> a;
		d[a] ++;
		s[a] += a;
	}
	rep(i, n) {
		d[i + 1] = d[i] + d[i + 1];
		s[i + 1] = s[i] + s[i + 1];
	}

	for(int k = 1; k <= n; ++k) {
		int ng = n + 1, ok = 0;
		while(ng - ok > 1) {
			int mid = (ng + ok) / 2;
			if(mid * (n - d[mid]) + s[mid] <= k * mid) ok = mid;
			else ng = mid;
		}
		cout << ok << endl;
	}

}

