int main(void){
	scanf("%d",&n);
	for(int e=0;e<n;e++) scanf("%d",&arr[e]);
	sort(arr,arr+n);
	int tmp = 1;
	for(int e=1;e<n;e++){
		if(arr[e]!=arr[e-1]){
			v.push_back(tmp);
			tmp = 1;
		}else tmp++;
	}
	v.push_back(tmp);
	for(int e=0;e<v.size();e++) vis[v[e]]++;
