		}
		int ans = 0;
		priority_queue<pair<int,int> > q = ex;
		while(true){
			vector<pair<int,int> > v2;
			int tot = p;
			while(!q.empty()){
				pair<int,int> now = q.top();q.pop();
				if(now.second>=tot){
					if(now.first!=1) v2.push_back(make_pair(now.first-1,tot));
					if(now.second>tot) v2.push_back(make_pair(now.first,now.second-tot));
					tot = 0;
					break;
				}else{
					if(now.first!=1) v2.push_back(make_pair(now.first-1,now.second));
					tot -= now.second;
				}
			}
			if(tot) break;
			ans++;
			for(int e=0;e<v2.size();e++){
				 q.push(make_pair(v2[e].first,v2[e].second));
			}
		}
		printf("%d\n",ans);
	}
	return 0;
}

