    template <int128_t mod> class Mod_Int {
        public:
        int128_t val;

        void calc() {
            if (val < 0) { val += ((iabs(val) + mod) / mod) * mod; }
            val %= mod;
        }
        Mod_Int(const int128_t _val = 0) { val = _val; calc(); }
        int128_t INT() { return val; } // 使用は非想定
        int128_t MOD() { return mod; } // 使用は非想定
        Mod_Int operator-() const { return Mod_Int(-val); }
        Mod_Int operator+(const Mod_Int &r) const { return Mod_Int(val + r.val); }
        Mod_Int operator-(const Mod_Int &r) const { return Mod_Int(val - r.val); }
        Mod_Int operator*(const Mod_Int &r) const { return Mod_Int(val * r.val); }
        //Mod_Int operator/(const Mod_Int &r) const { return ; } // ユークリッド互除法を使うべきだが保留。
        Mod_Int& operator+=(const Mod_Int &r) { val += r.val; calc(); return *this; }
        Mod_Int& operator-=(const Mod_Int &r) { val -= r.val; calc(); return *this; }
        Mod_Int& operator*=(const Mod_Int &r) { val *= r.val; calc(); return *this; }
        Mod_Int& operator++() { return (*this) += 1; }
        Mod_Int& operator--() { return (*this) -= 1; }
        Mod_Int operator++(int) { Mod_Int tmp = *this; ++*this; return tmp; }
        Mod_Int operator--(int) { Mod_Int tmp = *this; --*this; return tmp; }
        bool operator==(const Mod_Int &r) const { return val == r.val; }
        bool operator!=(const Mod_Int &r) const { return val != r.val; }

        friend std::istream &operator>>(std::istream& input, Mod_Int& r) { 
            int128_t tmp; input >> tmp;
            r = Mod_Int(tmp);
            return input;
        }
        friend std::ostream &operator<<(std::ostream& output, const Mod_Int& r) { 
            output << r.val;
            return output;
        }
    };

    struct Closed_Section {
        bool valid;
        int128_t begin;
        int128_t end;
        Closed_Section(bool _valid, int128_t _begin, int128_t _end) {
            valid = _valid; begin = _begin; end = _end;
        }
        Closed_Section() {
            valid = false, begin = 0; end = -1; //配列を定義するためにデフォルトコンストラクタが必要。
        }
        int128_t size() { return valid ? end - begin + 1 : 0; }
        void dump() { std::cout << "valid:" << valid << " begin:" << begin << " end:" << end << std::endl; }
    };

    Closed_Section common_section(Closed_Section& s1, Closed_Section& s2) {
        if (!s1.valid) { return s1; }
        if (!s2.valid) { return s2; }
        if (s1.end < s2.begin) { return Closed_Section(false, 0, -1); }
        if (s2.end < s1.begin) { return Closed_Section(false, 0, -1); }
        return Closed_Section(true, imax(s1.begin, s2.begin), imin(s1.end, s2.end));
    }

    //template<class Fn> Closed_Section binary_search(int128_t L, int128_t R, Fn func) {
    Closed_Section binary_search(const int128_t L, const int128_t R, std::function<bool(int128_t)> func) {
        const bool res_L = func(L);
        const bool res_R = func(R);
        if (res_L && res_R) {
            return Closed_Section(true, L, R);
        } else if (!res_L && !res_R) {
            return Closed_Section(false, 0, -1);
        } else {
            int128_t lb = L;
            int128_t ub = R;
            while (lb + 1 < ub) {
                int128_t mid = (lb + ub) / 2;
                if (res_L == func(mid)) {
                    lb = mid;
                } else {
                    ub = mid;
                }
            }
            return res_L ? Closed_Section(true, L, lb) : Closed_Section(true, ub, R);
        }
    }

    Closed_Section binary_search(const Closed_Section& cs, std::function<bool(int128_t)> func) {
        return cs.valid ? binary_search(cs.begin, cs.end, func) : cs;
    }

