template< typename F >
struct FixPoint : F {
  FixPoint(F &&f) : F(forward< F >(f)) {}

  template< typename... Args >
  decltype(auto) operator()(Args &&... args) const {
    return F::operator()(*this, forward< Args >(args)...);
  }
};

template< typename F >
inline decltype(auto) MFP(F &&f) {
  return FixPoint< F >{forward< F >(f)};
}

int main() {
  int N;
  cin >> N;
  vector< int > A(N);
  cin >> A;

  map< int, int > mp;
  for(auto &a : A) mp[a]++;
  map< int, int > uku;
  for(auto &a : mp) uku[a.second]++;


  // p.first 残り
  // p.second 個数
  auto beet = [&](int sz) {
    priority_queue< pair< int, int > > que;
    for(auto &p : uku) que.emplace(p);
    int ret = 0;

    while(que.size()) {
      vector< pair< int, int > > nxt;
      int add = 0;
      while(que.size() && add < sz) {
        auto p = que.top();
        que.pop();
        add += p.second;
        nxt.emplace_back(p);
      }
      if(add > sz) {
        que.emplace(nxt.back().first, add - sz);
        nxt.back().second -= add - sz;
      }
      if(add < sz) {
        break;
      }
      int tap = inf;
      for(auto &p : nxt) {
        chmin(tap, p.second);
      }
      ret++;
      for(auto &p : nxt) {
        if(p.second - tap > 0) {
          que.emplace(p.first, p.second - tap);
        }
        p.first--;
        if(p.first > 0) {
          que.emplace(p.first, tap);
        }
      }
    }
    return ret;
  };


  vector< int > ans(N + 1);
  ans[1] = beet(1);
  ans[N] = beet(N);
  auto rec = MFP([&](auto rec, int l, int r) -> void {
    while(l < r && ans[l] == ans[r]) ans[++l] = ans[r];
    if(r - l <= 1) return;
    int mid = (l + r) >> 1;
    ans[mid] = beet(mid);
    rec(l, mid);
    rec(mid, r);
  });
  rec(1, N);
  for(int i = 1; i <= N; i++) cout << ans[i] << "\n";
}

