int
main()
{
  int N;
  cin >> N;
  vector<int> A(N);
  for (int n = 0; n < N; n++)
  {
    cin >> A[n];
  }
  sort(A.begin(), A.end());
  vector<int> C;
  int top = 0;
  while (top < N)
  {
    int val = A[top];
    int bot = top + 1;
    for (; bot < N && A[bot] == val; ++bot)
    {
    }
    C.push_back(bot - top);
    top = bot;
  }
  sort(C.begin(), C.end(), std::greater<int>());
  int c_size = C.size();
  vector<int> LEN(c_size);
  C[c_size - 1] = 1;
  for (int i = c_size - 2; 0 <= i; i--)
  {
    LEN[i] = (C[i] == C[i + 1] ? LEN[i + 1] + 1 : 1);
  }

  cout << N << endl;
  for (int K = 2; K <= N; K++)
  {
    int remain = N;
    int k = K;
    int count = N / K;
    for (int c = 0; c < c_size;)
    {
      if (C[c] <= count)
      {
        break;
      }
      if (c_size - c < k)
      {
        count = 0;
        break;
      }

      int d = min(k, LEN[c]);
      remain -= C[c] * d;
      k -= d;
      if (k <= 0)
      {
        break;
      }
      count = min(count, remain / k);
      if (count <= 1)
      {
        break;
      }
      c += d;
    }
    cout << count << endl;
  }
  return 0;
}

