vector<int> vec;

const int N = 300030;
int A[N];
int P[N];
int n;

int qu(int o) {
  int lo=0, hi=n;
  while (lo<hi) {
    int mid = (lo+hi+1)/2;

    if (mid != 0 && vec[mid-1] < o) {
      hi = mid-1;
    }
    else {
      lo = mid;
    }
  }

  int ans = lo+(P[n]-P[lo])/o;
  //cerr << " o = " << o << " :: " << ans << " ,, " << lo << " + (" << P[n] << "-" << P[lo] << ")/" << o << endl;
  return ans;
}

int solve(int k) {
  int lo = 0, hi = n;
  while (lo < hi) {
    int o = (lo+hi+1)/2;

    int va = n;
    if (o != 0) {
      va = qu(o);
    }

    if (va < k) {
      hi = o-1;
    } else {
      lo = o;
    }
  }
  return lo;
}

