    ++A[x];
  }
  for (int i=1; i<=n; ++i) {
    vec.push_back(A[i]);
  }
  sort(vec.rbegin(), vec.rend());
  for (int i=1; i<=n; ++i) {
    P[i] = P[i-1]+vec[i-1];
  }

  for (int i=1; i<=n; ++i) {
    cout << solve(i) << "\n";
  }


  return 0;
}

