ll N;
ll A[300005];
ll B[300005];
vector<ll> v;

ll solve(ll n) {
    if (v.size() < n)
        return 0;
    //! 多くてもm回以内に収まる
    ll a = 0;
    ll b = 0;
    ll c = 0;
    {
        ll m = 0;
        ll t = 0;
        while (m < v.size()) {
            a += v[m];
            if (t % 2 == 0)
                m += n * 2 - 1;
            else
                m++;
            t++;
        }
    }
    {
        ll m = n - 1;
        ll t = 0;
        while (m < v.size()) {
            b += v[m];
            if (t % 2 == 0)
                m++;
            else
                m += n * 2 - 1;
            t++;
        }
    }
    {
        ll m = v.size() % n;
        if ((v.size() / n) % 2 == 1)
            m = n - (v.size() % n) - 1;
        ll s = m;
        ll t = 0;
        while (m < v.size()) {
            c += v[m];
            if (t % 2 == 0)
                m += (n - 1 - s) * 2 + 1;
            else
                m += s * 2 + 1;
            t++;
        }
    }

    return std::min(a, std::min(b, c));
}

