//P = (同じ数が出てきた回数、　その数)
Int calc(priority_queue<P> M, Int K, Int N){
  //prArr(M);
  Int cnt = 0;
  if(K == 1) return N;

  while(1){
    vector<P> tmp;
    {
      Int sum = 0;
      while(sum < K){
        if(M.empty()) return cnt;
        auto t = M.top(); M.pop();
        if(t.first == 0) continue;
        sum += t.second;
        tmp.push_back(t);
      }
    }

    Int sum = 0;
    for(auto p:tmp){
      if(sum + p.second <= K){
        if(p.first - 1 > 0) {
          M.push(P(p.first - 1, p.second));
          //M[p.first - 1] += p.second;
        }
      }
      else{
        if(p.first - 1 > 0) M.push(P(p.first - 1, K - sum));
        M.push(P(p.first, p.second - (K - sum)));
      }
      sum += p.second;
    }
    cnt++;
  }
}

