int main() {
    ll n;
    cin >> n;
    vl a(n);
    map<ll, int> cnt;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        cnt[a[i]]++;
    }
    priority_queue<int> pqorig;
    for (auto &p : cnt) {
        pqorig.push(p.second);
    }
    for (int i = 1; i <= n; ++i) {
        vector<int> temp;
        int ok     = 0;
        int ng     = n + 1;
        auto check = [&](int mid) {
            priority_queue<int> pq = pqorig;
            for (int j = 0; j < mid; ++j) {
                if (pq.size() < i)
                    return false;
                for (int k = 0; k < i; ++k) {
                    if (pq.empty())
                        return false;
                    int t = pq.top();
                    pq.pop();
                    temp.push_back(t);
                }
                ll mini = temp.back();
                j += mini - 1;
                for (auto &t : temp) {
                    t -= mini;
                    if (t > 0)
                        pq.push(t);
                }
                temp.clear();
            }
            return true;
        };
        while (ok + 1 != ng) {
            int mid = (ok + ng) / 2;
            if (check(mid))
                ok = mid;
            else
                ng = mid;
        }
        cout << ok << "\n";
    }
    return 0;
