using namespace std;
typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
typedef vector<int> vi;
typedef vector<ll> vl;

int main() {
	int N;
	cin >> N;
	vi A(N);
	vi atmp(nmax_def);
	rep(i, N) {
		cin >> A[i];
		atmp[A[i]]++;
	}
	sort(atmp.begin(), atmp.end(), greater<int>());
	vi a;
	int M = 0;
	rep(i, nmax_def) {
		if (atmp[i] == 0)
			continue;
		a.push_back(atmp[i]);
		M++;
	}
	vi ans(N + 1);
	int plain_min = M - 1; // 平面(上段)の左端
	int plain_minus1_min = M - 1;// 平面上の段差の位置(下段の左端)
	int plain_height = a[M - 1] + 1; // 平面の高さ
	while (1) { // 盛り土の左端をしゃくとり
		if (plain_min == 0)
			break;
		if (a[plain_min - 1] != plain_height - 1) // 最初は下段扱い
			break;
		plain_min--;
	}
	plain_minus1_min = plain_min;
	for (int K = N; K > 1; K--) {
		if (M < K) {
			ans[K] = 0; // 盛り土なし
			continue;
		}
		// ans[K] = 右端の高さ
		ans[K] = plain_height;
		if (plain_minus1_min < M) // 右端まで詰まってない
			ans[K]--;
		int dirt_amount = ans[K]; // 使える盛り土の量 = 右端の高さ
		while (1) {
			int minus1_len = K - plain_minus1_min; //	下段の長さ
			if (minus1_len > dirt_amount) { // 下段を埋めることができない
				plain_minus1_min += dirt_amount;
				dirt_amount = 0;
			}
			else { // 最下段の盛り土完了
				dirt_amount -= minus1_len;
				plain_height++;
				while (1) { // 盛り土の左端をしゃくとり
					if (plain_min == 0)
						break;
					if (a[plain_min - 1] != plain_height)
						break;
					plain_min--;
				}
				plain_minus1_min = plain_min; // 平面が均一なので(下段の左端)==(平面の左端)
			}
			if (dirt_amount == 0)
				break;
		}
	}
	ans[1] = N;
	rep(K, N) {
		cout << ans[K + 1] << endl;
	}
	return 0;
}

