int sum(vector<int> groups, int size) {
	int s = 0;
	int i = 0;
	for (auto const& v : groups) {
		if (v >= size) {
			break;
		}

		s += v;
		i++;
	}

	s += (groups.size() - i) * size;

	return s;
}

