    for (int i = 0; i < N; ++i)
        cardsCounter[fetch<int>()]++;

    std::priority_queue<std::pair<int, int>> pq;

    for (auto it = cardsCounter.begin(); it != cardsCounter.end(); ++it)
        pq.push({it->second, it->first});

    // K = 1
    std::cout << N << std::endl;

    // K > 1
    for (int i = 2; i <= N; ++i)
    {
        std::priority_queue<std::pair<int, int>> pq2 = pq;
        int counter = 0;

        while (pq2.size() >= i)
        {
            vector<std::pair<int, int>> tmp(i);

            for (int j = 0; j < i; ++j)
            {
                tmp[j] = pq2.top();
                pq2.pop();
            }

            int minValue = tmp.back().first;
            counter += minValue;

            for (int j = 0; j < i - 1; ++j)
            {
                if (tmp[j].first - minValue > 0)
                    pq2.push({tmp[j].first - minValue, tmp[j].second});
            }
        }

        std::cout << counter << std::endl;
    }

    return 0;
}

