ll N;
vl C, SC;

bool check(ll x, ll k){
    ll res = 0;
    auto idx = lower_bound(ALL(C), x) - C.begin();
    res = SC[idx] + (N-idx)*x;
    return res >= x*k;
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N; vl A(N); rep(i, N) {cin >> A[i]; A[i]--;};
    C = vl(N, 0);
    rep(i, N) C[A[i]]++;
    sort(ALL(C));
    SC = vl(N+1, 0);
    rep(i, N) SC[i+1] += C[i] + SC[i];

    FOR(k, 1, N+1){
        ll ok = 0, ng = N/k + 1;
        while(abs(ok-ng) > 1){
            ll mid = (ok+ng)/2;
            if(check(mid, k)) ok = mid;
            else ng = mid;
        }
        cout << ok << endstr;
    }

    return 0;
}

