using ll = long long;

const ll mod = 1e9+7;
const int maxn = 1e6 + 5;




int f[maxn];

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);

    int n;
    cin>>n;

    for (int i=0; i<n; i++) {
	int x;
	cin>>x;
	f[x]++;
    }
    vector<ll> v; // frequencies of elems
    for (int i=0; i<maxn; i++) {
	if (f[i]) {
	    v.push_back(f[i]);
	}
    }

    sort(v.rbegin(), v.rend());
    int len = v.size();

    vector<ll> remaining(n+1, 0); // remaining[i]: remaining # of elems if we remove the top i most frequent elements.
    for (int i=len-1; i>=0; i--) {
	remaining[i] = v[i] + remaining[i+1];
    }


    auto get = [&](int m, int k) {
	return 1.0 * remaining[m] / (k-m);
    };

    for (int k=1; k<=n; k++) {
	ll res = n / k;
	int lo = 1;
	int hi = k;
	while (hi-lo>1) {
	    int mid = (lo+hi)/2;
	    assert(k>mid);
	    double resp = get(mid-1, k);
	    double resc = get(mid, k);
	    if (resp < resc) {
		hi = mid;
	    } else {
		lo = mid;
	    }
	}
	for (int m=hi-5; m<=hi+5; m++) {
	    if (k>m && m>=0) {
		res = min(res, (ll)get(m, k));
	    }
	}
	cout<<res<<"\n";
    }

    return 0;
}

