int judge(int q,int k)
{
	int l=1,r=n,mid,ans;
	while(l<=r)
	{
		mid=(l+r)/2;
		if(b[mid]<q&&(mid==n||b[mid+1]>=q))
		{
			ans=mid;
			break;
		}
		else if(b[mid]<q) l=mid+1;
		else r=mid-1;
	}
	if((n-ans)*q+c[ans]>=k*q) return 1;
	else return 0;
}
