  map<int,int> cntcnt;
  for(auto p : cnt) cntcnt[p.SS]++;

  vector<PLL> ys;
  for(auto p : cntcnt) ys.PB(p);

  for(int k=1;k<=N;++k){
    int lb = 0, ub = N / k + 1;
    while(ub - lb > 1){
      LL m = (lb + ub) / 2;
      LL num = 0;
      for(auto p : ys){
        num += min(p.FF, m) * p.SS;
      }

      (num >= m * k ? lb : ub) = m;
    }

    cout << lb << endl;
  }

  return 0;
}

