vector<pair<char, Int>> merge_cont_char(const string &s) {
  vector<pair<char, Int>> ret;
  if (s.empty())
    return ret;
  ret.push_back(make_pair(s[0], 0));
  FOR(c, s) {
    if (ret.back().first == c)
      ret.back().second++;
    else
      ret.push_back(make_pair(c, 1));
  }
  return ret;
}

class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class Solver {
public:
  Int N;
  vi A;
  Solver() {}
  void input() {
    cin >> N;
    A = vi(N);
    FOR(a, A)cin >> a;
  }
  void solve() {
    sort(A);
    map<Int, Int> sameCount;
    FOR(a, A)sameCount[a]++;
    vector<Int> V;
    while(!sameCount.empty()){
      Int cnt = 0;
      vector<Int> Q;
      FOR(it, sameCount){
        cnt++;
        it.second--;
        if(it.second == 0)Q.push_back(it.first);
      }
      FOR(q, Q)sameCount.erase(q);
      V.push_back(cnt);
