    stack< pair< int, int > > que;
    for(auto &p : uku) que.emplace(p);
    int ret = 0;

    while(que.size()) {
      vector< pair< int, int > > nxt;
      int add = 0;
      while(que.size() && add < sz) {
        auto p = que.top();
        que.pop();
        add += p.second;
        if(nxt.size() && nxt.back().first == p.first) {
          nxt.back().second += p.second;
        } else {
          nxt.emplace_back(p);
        }
      }
      auto v = nxt.back();
      v.second = 0;
      if(add > sz) {
        v.second = add - sz;
        nxt.back().second -= add - sz;
      }
      if(add < sz) {
        break;
      }
      ret++;
      for(auto &p : nxt) {
        p.first--;
        if(v.first < p.first && v.second) {
          que.emplace(v);
          v.second = 0;
        }
        if(p.first > 0) {
          que.emplace(p.first, p.second);
        }
      }
      if(v.second) {
        que.emplace(v);
      }
