char buf[3000000];
char *p = buf;
int ri() {
	int r = 0, s = 0;
	for (;;) {
		if (*p == '-') {
			s = 1;
			break;
		}
		if (*p <= '9' && *p >= '0') {
			r = *p - '0';
			break;
		}
		p++;
	}
	p++;
	for (;;) {
		if (*p < '0' || *p > '9') break;
		r = r * 10 + *p - '0';
		p++;
	}
	p++;
	if (s) r = -r;
	return r;
}


int main() {
	fread(buf, 1, 3000000, stdin);
	int n = ri();
	int cnt[n + 1];
	memset(cnt, 0, sizeof(cnt));
	for (int i = 0; i < n; i++) cnt[ri()]++;
	std::vector<int> a;
	for (int i = 0; i <= n; i++) if (cnt[i]) a.push_back(cnt[i]);
	std::sort(a.begin(), a.end(), std::greater<>());
	for (int i = (int) a.size() - 1; i; i--) a[i - 1] += a[i];

	int m = a.size();
	std::vector<int> change[m + 1];
	change[1].push_back(0);
	int min = 1000000000;
	for (int i = 1; i <= m; i++) {
		for (auto j : change[i]) {
			int cur = a[j] / (i - j);
			min = std::min(min, cur);
			if (cur) {
				int next = a[j] / cur + 1 + j;
				if (next <= m) change[next].push_back(j);
			}
		}
		printf("%d\n", min);
		if (i < m) change[i + 1].push_back(i);
	}
	for (int i = m; i < n; i++) puts("0");

	return 0;
}

