bool f(i64 k, i64 t) {
    i64 i = lower_bound(c + 1, c + m + 1, -t) - c;
    i64 s = ps[i - 1] - t * (i - 1);
    return s <= n - (k * t);
}

i64 bin(i64 k, i64 l, i64 r) {
    if (l == r) {
        return l;
    }
    if (l + 1 == r) {
        if (f(k, r)) {
            return r;
        }
        else {
            return l;
        }
    }

    i64 t = (l + r) / 2;
    if (f(k, t)) {
        return bin(k, t, r);
    }
    else {
        return bin(k, l, t);
    }
}

