vector<ll> v;

ll solve(ll n) {
    if (v.size() < n)
        return 0;

    ll ret = INF;
    REP(i, n) {
        ll m = i;
        ll s = 0;
        ll t = 0;
        while (m < v.size()) {
            s += v[m];
            if (t % 2 == 0)
                m += (n - 1 - i) * 2 + 1;
            else
                m += i * 2 + 1;
            t++;
        }
        ret = std::min(ret, s);
    }
    return ret;
}

