struct Node{
    int ff, ss;
    bool operator<(const Node &a)const{
        return ff>a.ff;
    }
};
priority_queue<Node> Q;

inline void insertToSet(int val, int cnt){
    if(Q.empty() or (Q.top().ff > val)) Q.push({val, cnt});//, debug("inserting", val, cnt);
    else {
        auto now = Q.top();
        Q.pop();
        Q.push({val, now.ss + cnt});
        // debug("inserting", val, now.ss + cnt);
    }
}

inline void addToSet(int add){
    // debug("adding", add);
    while(add){
        auto now = Q.top();
        Q.pop();
        // debug("now", add, now.ff, now.ss);
        if(now.ss <= add){
            if(Q.empty()) insertToSet(now.ff + 1, now.ss), add -= now.ss;
            else{
                auto nxt = Q.top();
                int canRaiseUpto = min(nxt.ff, now.ff + add / now.ss);
                insertToSet(canRaiseUpto, now.ss);
                add -= (canRaiseUpto - now.ff)*now.ss;
            }
        }
        else{
            insertToSet(now.ff + 1, add);
            insertToSet(now.ff, now.ss - add);
            add = 0;
        }
    }
}

