  vector<ll> sum1(n+2, 0), sum2(n+2, 0);
  repc(i, n) {
    sum1[i+1] = sum1[i] + i * mp[i];
    sum2[i+1] = sum2[i] + mp[i];
  }
  vector<ll> ans(n+1, 0);
  REPC(i, 1, n) {
    ll res = 0;
    res = sum1[i+1] + (sum2[n+1] - sum2[i+1]) * i;
    res /= ll(i);
    chmax(ans[res], ll(i));
  }
  REPCM(i, n-1, 1) chmax(ans[i], ans[i+1]);
  REPC(i, 1, n) cout << ans[i] << '\n';
}
int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);
  answer();
  return 0;
}

