	scanf_vec(arr);

	vector<int> cnts(n);
	for (int x : arr)
		cnts[x - 1]++;
	sort(all(cnts), std::greater<>());
	while (cnts.back() == 0) cnts.pop_back();
	sort(all(cnts));

	vector<long long> terms;
	vector<long long> rems;

	for (int& x : cnts)
		x--;

	for (int i = 0; i < cnts.size(); i++)
	{
		long long x = cnts[i], len = cnts.size() - i;
		if (i > 0) x -= cnts[i - 1];
		if (x > 0)
		{
			terms.push_back(x * len);
			rems.push_back(len);
		}
	}
	terms.push_back(0);
	rems.push_back(0);

	vector<long long> partial(rems.size());
	partial[0] = terms[0];
	for (int i = 1; i < rems.size(); i++)
		partial[i] = partial[i - 1] + terms[i];

	reverse(all(partial));
	reverse(all(rems));
	reverse(all(terms));

	for (int k = 1; k <= n; k++)
	{
		auto it = lower_bound(all(rems), k);
		int pos;
		long long ans = 0;
		long long used_ones = 0;
		if (it == rems.end())
			pos = (int)rems.size()-1;
		else
		{
			pos = it - rems.begin();
			ans = partial[pos] / k;
			long long rem = partial[pos] % k;

			if (rem > 0 && rem > (cnts.size() - rems[pos]))
				pos = -1;
			else if (rem > 0)
			{
				ans++;
				used_ones = rem;
			}

			pos--;
		}

		while (pos > 0)
		{
			long long  total_ones = cnts.size() - rems[pos];
			long long rem_ones = total_ones - used_ones;
			long long curr_len = rems[pos];

			int ava_cnt = terms[pos] / curr_len;
			int one_cnt = rem_ones / (k - curr_len);

			ans += min(ava_cnt, one_cnt);
			used_ones += min(ava_cnt, one_cnt) * (curr_len % k);

			if (ava_cnt > one_cnt)
				break;
			pos--;
		}

		ans += (cnts.size() - used_ones) / k;

		cout << ans << "\n";
	}

	return 0;
}

