vector<int> line;
map<int, int> m;
int sum;

void setnum(int n){
	if(n>line.size())return;
	int d = n/100;
	static vector<map<int, int>> ms(3001);
	static vector<int> sums(3001, -1);
	if(sums[d]==-1){
		if(d){
			setnum(n-100);
			ms[d]=ms[d-1];
			sums[d]=sums[d-1];
			for(int i=d*100-99;i<d*100;++i){
				++ms[d][line[i]];
				sums[d]-=line[i];
			}
		}else{
			sums[d]=0;
			foreach(i, line)sums[d]+=i;
		}

	}
	m=ms[d];
	sum=sums[d];
	for(int i=d*100;i<n;++i){
		++m[line[i]];
		sum-=line[i];
	}
}

int func(int n){
	if(line.size()<n)return 0;
	setnum(n);
	while(sum){
		if(m.size()==1)
			return sum/(m.begin()->second)+m.begin()->first;
		pii d = *m.begin();
		m.erase(d.first);
		int add = m.begin()->first - d.first;
		add = min(sum/d.second, add);
		m[d.first+add]+=d.second;
		sum -= add * d.second;
	}
	return m.begin()->first;
}


