	checked.insert(1);
	checked.insert(n);
	int place = 1;
	while(place<n){
		if(ans[place]==-1)ans[place]=func(place);
		int d = *checked.upper_bound(place);
		int count = 0;
		while(d-place>1&&ans[d]!=ans[place]){
			++count;
			int mid = (d+place)/2;
