int n, a[MAXN], f[MAXN];
vector<int> b, s;

int getNumberOfLarger(int u) {
    if (b[0] < u) return 0;

    int dau = 0, cuoi = SZ(b)-1;
    while (dau <= cuoi) {
        int mid = (dau + cuoi) >> 1;
        if (b[mid] >= u) dau = mid+1;
        else cuoi = mid-1;
    }
    return cuoi+1;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(nullptr);
    cin >> n;
    FOR(i,1,n) cin >> a[i];
    FOR(i,1,n) f[a[i]]++;
    FOR(i,1,n)
        if (f[i]) b.emplace_back(f[i]);
    sort(ALL(b));
    reverse(ALL(b));

    FOR(i,0,SZ(b)-1) 
        if (i == 0) s.emplace_back(b[i]);
        else s.emplace_back(s[SZ(s)-1] + b[i]);

    FOR(k,1,n) {
        if (k > SZ(b)) {
            cout << 0 << "\n";
            continue;
        }
        int numOfGroup = k;
        int numInEach = n / k;

        int cnt = getNumberOfLarger(numInEach);

        numOfGroup -= cnt;
        if (numOfGroup <= 0) {
            cout << numInEach << "\n";
            continue;
        }
        int N = n;
        int Min = 1000000000;
        if (cnt) {
            N = n - s[cnt-1];
            Min = b[cnt-1];
        }

        while (cnt <= SZ(b) && b[cnt] > N / 2) {
            Min = min(Min, b[cnt]);
            N -= b[cnt];
            cnt++;
            numOfGroup--;
        }

        if (numOfGroup) numInEach = N / numOfGroup;
        else numInEach = 1000000000;

        cout << min(Min, numInEach) << "\n";
    }
    return 0;
}

