int c[300010],q[300010];

bool judge(int x,int k){
	int l=1,r=n,ans=-1;
	while(l<=r){
		int mid=(l+r)/2;
		if(c[mid]<k&&c[mid+1]>=k){
		    ans=mid;
		    break;
		}
		else if(c[mid]<k) l=mid+1;
		else r=mid-1;
	}
	if(ans!=-1){
		if((n-ans)*x+q[ans]>=k*x) return true;
	}
	return false;
}

int main(){
	scanf("%d",&n);
	for(int i=1; i<=n; i++){
		int a;
		scanf("%d",&a);
		c[a]++;
	}
	sort(c+1,c+n+1);
	for(int i=1; i<=n; i++){
		q[i]=q[i-1]+c[i];
	}	    
	int x=n;
	for(int k=1; k<=n; k++){
		while(x>0&&!judge(x,k)){
			x--;
		}
		printf("%d\n",x);
	}
	return 0;
}

