int main() {
    // 貪欲法では間に合わないので使い回す、
    // segtree、累積和を使えばsegtreeいらない
    int N;
    cin >> N;
    vector<int> A(N);
    map<int, int> mp;
    rep(i, N) {
        cin >> A[i];
        mp[A[i]]++;
    }
    vector<ll> B;
    for (auto a : mp) {
        B.push_back(a.second);
    }
    sort(B.begin(), B.end());
    vector<ll> Bcum = B;
    ll length = sz(B);
    for (int i = 1; i < length; i++) {
        Bcum[i] += Bcum[i-1];
    }
    for (int i = 1; i <= N; i++) {
        // 最大の回数
        ll time = N / i;
        ll ind = (upper_bound(B.begin(), B.end(), time) - B.begin()); // time以下の一番右のindex+1
        ll ans = Bcum[ind-1];
        ans += time * (length - ind);
        ans /= i;
        cout << ans << '\n';
    }
    return 0;
}

