template<typename Monoid,typename Operator>
struct LazySegmentTree{
    private:
    typedef function<Monoid(Monoid,Monoid)> F;
    typedef function<Monoid(Monoid,Operator)> G;
    typedef function<Operator(Operator,Operator)> H;
    typedef function<Operator(Operator,int)> P;
    int n;
    F f;
    G g;
    H h;
    P p;
    Monoid id1;
    Operator id0;
    vector<Monoid> dat;
    vector<Operator> laz;
    public:
    LazySegmentTree(int n_,F f,G g,H h,Monoid id1,Operator id0,
                    P p=[](Operator a,int b){return a;}){
        this->f=f;
        this->g=g;
        this->h=h;
        this->id1=id1;
        this->id0=id0;
        init(n_);
    }
    void init(int n_){
        n=1;
        while(n<n_){
            n*=2;
        }
        dat.resize(2*n-1,id1);
        laz.resize(2*n-1,id0);
    }
    void build(int n_,vector<Monoid> v){
        rep(i,n_){
            dat[i+n-1]=v[i];
        }
        for (int i=n-2;i>=0;i--){
            dat[i]=f(dat[2*i+1],dat[2*i+2]);
        }
    }
    inline void eval(int len,int k){
        if (laz[k]==id0){
            return;
        }
        if (2*k+1<2*n-1){
            laz[2*k+1]=h(laz[2*k+1],laz[k]);
            laz[2*k+2]=h(laz[2*k+2],laz[k]);
        }
        dat[k]=g(dat[k],p(laz[k],len));
        laz[k]=id0;
    }
    Monoid update(int a,int b,Operator x,int k,int l,int r){
        eval(r-l,k);
        if (r<=a||b<=l){
            return dat[k];
        }
        if (a<=l&&r<=b){
            laz[k]=h(laz[k],x);
            return g(dat[k],p(laz[k],r-l));
        }
        return dat[k]=f(update(a,b,x,2*k+1,l,(l+r)/2),
                        update(a,b,x,2*k+2,(l+r)/2,r));
    }
    Monoid update(int a,int b,Operator x){
        return update(a,b,x,0,0,n);
    }
    Monoid query(int a,int b,int k,int l,int r){
        eval(r-l,k);
        if (r<=a||b<=l){
            return id1;
        }
        if (a<=l&&r<=b){
            return dat[k];
        }
        Monoid vl=query(a,b,2*k+1,l,(l+r)/2);
        Monoid vr=query(a,b,2*k+2,(l+r)/2,r);
        return f(vl,vr);
    }
    Monoid query(int a,int b){
        return query(a,b,0,0,n);
    }
};

int main(){
    int N;
    vector<int> A(N),B(N);
    rep(i,N){
        cin >> A[i];
        B[i]=A[i];
    }
    sort(B.begin(),B.end());
    B.erase(unique(B.begin(),B.end()),B.end());
    int s=B.size();
    rep(i,N){
        A[i]=lower_bound(B.begin(),B.end(),A[i])-B.begin();
    }
    vector<int> count(s);
    rep(i,N){
        count[A[i]]++;
    }
    rep(i,N){
        LazySegmentTree<int,int> seg(s,[](int a,int b){return min(a,b);},
                        [](int a,int b){return a-b;},[](int a,int b){return a+b;},
                        INF,0);
        int ans=0;
        seg.build(s,count);
        rep2(j,i-1,N){
            int x=seg.query(0,j+1);
            ans+=x;
            seg.update(0,j+1,x);
        }
        cout << ans << endl;
    }
}

