    bit.n = 300000;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        b[a[i]]++;
    }
    vector<int> c;
    for (int i = 0; i < 300000; i++) {
        if(b[i]>0){
            bit.add(b[i],1);
            c.pb(b[i]);
        }
    }
    sort(ALL(c));
    for (int k = 1; k <= n; k++) {
        int l=0,r=n/k+1;
        while(abs(r-l)>1){
            int m = (r + l) / 2;
            int t = m * k;
            int sum = bit.sum(300000) - bit.sum(k);
            sum += upper_bound(ALL(c),k) - c.begin();
            if(sum >= t) l = m;
            else r = m;
        }
        cout << l << endl;
    }
    return 0;
}

