signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	std::map<int, int> map;
	{
		std::map<int, int> mp;
		REP(i, n) ++mp[a[i]];
		for (auto& p : mp) ++map[p.second];
	}

	V<int> ans(n, 0);
	std::queue<PAIR> Y;
	FOR(k, 1, n + 1) {
		auto X(map);
		while (!Y.empty()) Y.pop();
		while (true) {
			int now = 0;
			for (auto it = X.rbegin(); it != X.rend(); ++it) {
				if (now + it->second >= k) {
					int t = k - now;
					Y.emplace(it->first, t);
					now += t;
					break;
				}
				Y.emplace(*it);
				now += it->second;
			}
			if (now < k) break;
			while (!Y.empty()) {
				PAIR p = Y.front(); Y.pop();
				if ((X[p.first] -= p.second) == 0) X.erase(p.first);
				if (p.first == 1) continue;
				X[p.first - 1] += p.second;
			}
			++ans[k - 1];
		}
		if (ans[k - 1] == 0) break;
	}
	REP(i, n) {
		OUT(ans[i])BR;
	}

	return 0;
}

