		if(qu[i] != last){
			++m;
			w[m] = qu.size()-i, h[m] = qu[i]-last;
		}
		last = qu[i];
	}
	// 
	reverse(w+1, w+1+m);
	reverse(h+1, h+1+m);
	for(int i = 1;i <= m;++i)pref[i] = pref[i-1] + w[i] * h[i];
	for(int i = n;i >= 1;--i){
		int j = lower_bound(w+1,w+m+1, i) - w;
		res[i] = (n - pref[j-1]) / i;
		int la = n - res[i] * i - pref[j-1], lw = w[m]-i;
		for(--j;j > 0 and la > 0;--j){
			if(i-w[j] >= lw)break;
			int ad = min(h[j], la / (i-w[j]));
			if(!ad)break;
			res[i] += ad;
			la -= ad * (i-w[j]);
		}
	}
	for(int i = 1;i <= n;++i)cout << res[i] << '\n';
}

