typedef long long int ll;

int main() {
  int n; cin >> n;
  vector<ll> as(n);
  vector<ll> num_cnt(n + 1, 0);
  for (int i = 0; i < n; i++) { 
    cin >> as[i];
    num_cnt[as[i]]++;
  }
  sort(num_cnt.begin(), num_cnt.end());
  vector<ll> dup_sum(n + 1, -1);
  dup_sum[0] = 0;
  int num_cnt_idx = 0;
  for (int i = 1; i < n + 1; i++) {
    dup_sum[i] = dup_sum[i-1];
    while(num_cnt_idx < n + 1) {
      if (num_cnt[num_cnt_idx] > i) {
        break;
      }
      dup_sum[i] += num_cnt[num_cnt_idx];
      num_cnt_idx++;
    }
  }
  vector<int> ans(n+1, 0);
  for (int i = 1; i < n + 1; i++) {
    int num = dup_sum[i];
    // cout << i << " dup cnt:" << dup_sum[i] << endl;
    num += (num_cnt.end() - upper_bound(num_cnt.begin(), num_cnt.end(), i));
    int k = num / i;
    ans[k] = max(ans[k], i);
  }
  for (int i = n - 1; i > 0; i--) {
    ans[i] = max(ans[i], ans[i+1]);
  }

  for (int i = 1; i < n+1; i++) {
    cout << ans[i] << endl;
  }

  return 0;
}

