	std::sort(cnt.begin(), cnt.end());


	for (int K = 1; K <= N; K++) {
		std::vector <int> cp = cnt;

		int ans = 0;
		int endpos = cp.size()-1;
		while (1) {
			int minuspos = endpos - K + 1;
			if (minuspos < 0) break;
			else {
				if (cp[minuspos] <= 0) break;
				ans += cp[minuspos];
				for (int i = endpos; i >= minuspos; i--) {
					cp[i] -= cp[minuspos];
				}
			}
			std::sort(cp.begin(), cp.end());
		}
		std::cout << ans << std::endl;
	}

	return 0;
}

