int get_ans(vector<int> & counts, int k, int l, int r)
{
	int n = counts.size();

	while (r - l != 1)
	{
		int m = l + r >> 1;

		int tmp = 0;
		for (int i = 0; i != n; ++i)
			tmp += min(counts[i], m);

		if (k * m <= tmp)
			l = m;
		else
			r = m;
	}

	return l;
}

void solve(vector<int> & counts, vector<int> & ans, int l, int r)
{
	if (l == r)
		return;

	if (ans[l] == ans[r])
	{
		for (int i = l; i <= r; ++i)
			ans[i] = ans[l];
		return;
	}

	int m = l + r >> 1;

	ans[m] = get_ans(counts, m + 1, ans[r], ans[l] + 1);
	ans[m + 1] = get_ans(counts, m + 2, ans[r], ans[m] + 1);

	solve(counts, ans, l, m);
	solve(counts, ans, m + 1, r);
}

int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int n;
	cin >> n;

	vector<int> arr(n);
	for (int i = 0; i != n; ++i)
		cin >> arr[i];
	sort(arr.begin(), arr.end());

	vector<int> counts;
	int cnt = 1;
	for (int i = 1; i != n; ++i)
	{
		if (arr[i] != arr[i - 1])
		{
			counts.push_back(cnt);
			cnt = 1;
		}
		else
			cnt++;
	}
	counts.push_back(cnt);

	vector<int> ans(n, -1);

	ans[0] = get_ans(counts, 1, 0, n + 1);
	ans[n - 1] = get_ans(counts, n, 0, n + 1);

	solve(counts, ans, 0, n - 1);

	for (int x : ans)
		cout << x << '\n';

	return 0;
}

