  auto calc = [&](const int ans) -> ll {
    if (memo[ans] != -1) return memo[ans];
    ll res = 0;
    for (auto p : F) {
      res += min(p.first, ans) * p.second;
    }
    return memo[ans] = res;
  };

  for (int K = 1; K <= N; K++) {
