    int lo = 0;
    while (hi - lo > 1) {
      int mid = (hi + lo) / 2;
      bool possible = (mid * (ll)K <= calc(mid));
      if (possible) { lo = mid; } else { hi = mid; }
    }
    int ans = lo;
    printf("%d\n", ans);
  }
  return 0;
}

