using young_diagram = std::vector<int>;

young_diagram conjugate(young_diagram lambda) {
    young_diagram lambda_conjugate(lambda[0]);
    int m = lambda.size();
    int j = 0;
    for (int i = m; i > 0; --i) {
        int d = lambda[i - 1] - (i < m ? lambda[i] : 0);
        int stop = j + d;
        for (; j < stop; ++j) {
            lambda_conjugate[j] = i;
        }
    }
    return lambda_conjugate;
}

