	for (auto i : a) m[i]++;

	priority_queue<pair<int, int>, vector<pair<int, int>>,
				   greater<pair<int, int>>>
		q;
	for (auto p : m) q.emplace(p.second, -p.first);

	vector<int> ans;
	int minus = 0;
	while (not q.empty()) {
		int num, lim;
		tie(num, lim) = q.top();
		lim *= -1;
		q.pop();

		ans.emplace_back(num);
		minus += num;

		while (num) {
			auto p = q.top();
			q.pop();
			int space = lim - num;
			if(space == 0) continue;
			int in = min(num, space);
			num -= in;
			q.emplace(p.first + in, -lim);
		}
	}

	reverse(all(ans));
	while(ans.size() < n) ans.emplace_back(0);
	for(auto i : ans) cout << i << endl;

}

