#define MAXN	300001
int CardCounter[MAXN];
struct sCard
{
	int kind;
	int ONum; // Original Number
};
sCard Card[MAXN];

int compare(const void *a, const void *b)
{
	sCard *num1 = (sCard *)a;
	sCard *num2 = (sCard *)b;

	if (num1->ONum > num2->ONum)
		return -1;

	if (num1->ONum < num2->ONum)
		return 1;

	if (num1->ONum == num2->ONum)
	{
		if (num1->kind > num2->kind)
			return -1;

		if (num1->kind < num2->kind)
			return 1;
	}


	return 0;
}


void Sort(int N, sCard *Card)
{
	qsort(Card, N, sizeof(sCard), compare);
}




