int sol(unordered_map<int,int> input_map,int K){
    int ans=0,t;
    while(true){
        t=0;
        for(auto it=input_map.begin();it!=input_map.end();++it){
            if(it->second != 0){
                if(t>=K) break;
                t++;
                it->second--;
            }
        }
        if(t<K) break;
        else ans++;
    }
    return ans;
}

int main(){
    unordered_map<int,int> input_map;
    int n,t;
    cin>>n;
    for(int i=0;i<n;++i){
        cin>>t;
        input_map[t]++;
    }

    for(int K=1;K<=n;++K){
        cout<<sol(input_map,K)<<endl;
    }
    return 0;
}

