struct binaryindextree
{
    int sum[N];
    void update(int j,int x)
    {
        if(j==0)
            return ;
        for(;j<N;j+=j&(-j))
            sum[j]+=x;
    }
    int query(int j)
    {
        int x=0;
        for(;j>0;j-=(j)&(-j))
            x+=sum[j];
        return x;
    }
};
int cnt[N];
void solve()
{
    int n,i,a,k;
    in(n);
    rep(i,n)
        in(a),cnt[a]++;
    vi v;
    rep(i,N)
        if(cnt[i]>0)v.pb(cnt[i]);
    binaryindextree cnt,total;
    for(auto a : v)
        cnt.update(a,1),total.update(a,a);
    int sum,new_sum;
    int m=sz(v);
    fone(k,n)
    {
        if(k>m)
            out(0);
        else
        {
            sum=(n/k);
            while(1)
            {
                new_sum=total.query(sum)+(m-cnt.query(sum))*sum;
                new_sum/=k;
                if(new_sum==sum)
                    break;
                sum=new_sum;
            }
            out(sum);
        }
    }
}
