    int N; cin >> N;
    vector<long long> C(N, 0);
    vector<long long> D(N+1, 0);
    vector<long long> S(N+2, 0);
    for (int i = 0; i < N; ++i) {
        int a; cin >> a; --a;
        C[a]++;
        D[C[a]]++;
    }
    for (int i = 0; i < N+1; ++i) S[i+1] = S[i] + D[i];

    // 各 K に対して
    for (long long K = 1; K <= N; ++K) {
        // 二分探索
        long long low = 0, high = N+1;
        while (high - low > 1) {
            long long x = (low + high) / 2;
            if (S[x+1] >= K * x) low = x;
            else high = x;
        }
        cout << low << endl;
    }
}

