  for (int i = 1; i <= n; ++i)
  {
    int sum = 0;
    auto copy = map;
    while (copy.size() >= i)
    {
      int count = 0, previous = 2147483647;
      vector<int> record(i);
      for (auto &pair : copy)
      {
        // cout << pair.first << ' ' << pair.second << endl;
        record[count++] = pair.first;
        previous = min(previous, pair.second);
        if (count >= i)
          break;
      }
      sum += previous;
      for (auto x : record)
      {
        copy[x] -= previous;
        if (copy[x] <= 0)
          copy.erase(x);
      }
    }
    cout << sum << endl;
  }

