int func(vector<int> line, int n){
	priority_queue<int> pq;
	foreach(i, line)pq.push(i);
	int res = 0;
	while(true){
		vector<int> na;
		rep(i, n){
			if(pq.empty())return res;
			int d = pq.top()-1;
			pq.pop();
			if(d)
				na.push_back(d);
		}
		++res;
		foreach(i, na)pq.push(i);
	}
	return res;
}


int main(){
	int n;
	cin >> n;
	map<int, int> m;
	rep(i, n){
		int d;
		cin >> d;
		++m[d];
	}
	vector<int> line;
	foreach(i, m){
		line.push_back(i.second);
	}
	int na = 1;
	while(na<n){
		int nans = func(line, na);
		int ln = na;
		int hn = n;
		while(ln<hn){
			int mid=(ln+hn)/2;
			if(func(line, mid)==nans){
				ln = mid+1;
			}else{
				hn = mid;
			}
		}
		while(na<ln){
			cout << nans << endl;
			++na;
		}
	}
	if(na==n)cout << func(line, n) << endl;
	return 0;
}

