  auto beet = [&](int sz) {
    priority_queue< int > que;
    for(auto &p : mp) que.emplace(p.second);
    int ret = 0;
    while(que.size() >= sz) {
      ++ret;
      vector< int > nxt(sz);
      for(int i = 0; i < sz; i++) {
        int p = que.top();
        --p;
        nxt[i] = p;
        que.pop();
      }
      for(int i = 0; i < sz; i++) {
        if(nxt[i] > 0) {
          que.emplace(nxt[i]);
        }
      }
    }
