    sort(As.begin(), As.end());
    int c = 1;
    int prev = As[0];
    int p = 0;

    for(int i = 1; i < N; i++) {
        if(prev == As[i]) {
            c++;
        } else {
            kazu[p] = c;
            p++;
            c = 1;
            prev = As[i];
        }
    }
    kazu[p] = c;

    priority_queue< P, vector<P>, Order> q;
    for(int i = 0; i < N; i++) {
        if (kazu[i] == -1) {
            break;
        } else {
            P hoge; hoge.first = kazu[i]; hoge.second = {kazu[i]};
