        ans[i] = q.top().first;
        vector<int> temp = q.top().second;
        q.pop();
        for(int a: temp) {
            P hoge = q.top();
            q.pop();
            hoge.first += a;
            hoge.second.push_back(a);
            q.push(hoge);
        }
    }

    ans[0] = N;
