    REP(i,1,n+1){
        if(cnt[i])pq.push(cnt[i]);
    }
    while (sz(pq) >= k) {
        ans++;
        VI v;
        REP(i,0,k){
            v.PB(pq.top()-1);
            pq.pop();
        }
        REP(i,0,k)if(v[i])pq.push(v[i]);
    }
    return ans;
}


void solve(int l,int r,int ql,int qr){
    if(l>r or ql>qr)return;
    if(l==r){
        REP(i,ql,qr+1)ans[i] = l;
    }else{
        int mid = (ql+qr)/2;
        ans[mid] = solve(mid);
        solve(ans[mid],r,ql,mid-1);
        solve(l,ans[mid],mid+1,qr);
    }
}
