namespace Problem {
using namespace std;

class Solver {
 public:
  int n;
  multiset<int> S;
  Solver(LL n) : n(n){};

  void solve() {
    map<int, int> cnt;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
      //a[i] = i % ((int)sqrt(n));
    }
    for (int i = 0; i < n; ++i) {
      cnt[a[i]]++;
    }
    vector<int> inv(n);
    for (auto p : cnt) {
      for (int i = 0; i < p.second; ++i) {
        inv[i]++;
      }
    }
    for (auto i : inv) {
      if (i == 0) break;
      S.insert(i);
    }
    S.insert(0);
    vector<LL> ans(n + 1);
    ans[0] = n;
    LL k = 1;
    for (; k * k <= n * 1; ++k) {
      ans[k] = calc(k);
      if (ans[k] * ans[k] < n / 1) {
        k++;
        break;
      }
    }
    DBG(S)
    DBG(k)
    int l_mid = ans[k - 1];
    int bound_prev = k - 1;
    for (int l = l_mid; l >= 0; --l) {
      int bound = calc_bound(l, bound_prev);
      for (int i = bound_prev + 1; i <= bound; ++i) {
        ans[i] = l;
      }
      bound_prev = bound;
    }
    for (int i = 1; i <= n; ++i) {
      cout << ans[i] << endl;
    }
  }
  int calc_bound(int l, int bound_prev) {
    DBG(l, bound_prev)
    int ub = n + 1;
    int lb = bound_prev;
    while (ub - lb > 1) {
      int mid = (ub + lb) / 2;
      if (calc(mid) >= l)
        lb = mid;
      else
        ub = mid;
    }
    return lb;
  }
  int calc(int k) {
    multiset<int> T = S;
    int ret = 0;
    while (1) {
      auto it = T.lower_bound(k);
      if (it == T.end()) break;
      int now = *it;
      int pre = *prev(it);
      ret++;
      int tmp = now - k + pre;
      T.erase(it);
      T.erase(T.lower_bound(pre));
      T.insert(tmp);
      T.insert(0);
    }
    return ret;
  }
};

