ll _sum(ll t) {
  ll ng = -1, ok = N;
  while(ng+1 < ok) {
    ll m = (ok+ng)/2;
    if (a[m] >= t){
      ok = m;
    } else {
      ng = m;
    }
  }
  ll pos = ok;
  if (pos == 0) {
    return t*N;
  }
  // printf("%d + %dx%d\n",psum[pos-1],t,(N-pos));
  return psum[pos-1] + t*(N-pos);
}

ll solve(ll k) {
  ll ok = 0, ng = 300010;
