    ll m = (ok+ng)/2;
    if (_sum(m) >= m*k) {
      ok = m;
      // printf("ok=%d\n", m);
    } else {
      ng = m;
      // printf("ng=%d sum=%d m*k=%d\n", m, _sum(m), m*k);
    }
  }
  return ok;
}

