using ll = std::int64_t;
using P = std::tuple<int,int>;

int N, A;
std::map<int, int> numCards;
std::vector<int> heaps;
int heapSize;
int BIT[300100];
std::stack<P> history;

void add(int k, int v){
    while(k <= heapSize){
        BIT[k] += v;
        k += k & -k;
    }
}

void add2(int k, int v){
    history.emplace(k, v);
    add(k, v);
}

int prefixSum(int k){ // [0, k]
    int sum = 0;

    while(k > 0){
        sum += BIT[k];
        k -= k & -k;
    }

    return sum;
}

int leftmostBit(int x){
    int n = 0;

    for(int i=16;i>0;i/=2){
        if(x >> i){
            x >>= i;
            n += i;
        }
    }

    return 1 << n;
}

int simulate(int k){
    int res = 0;
    int kv = heaps[k];

    while(kv > 0){
        res += 1;

        // for(int i=1;i<=heapSize;++i){
        //     printf("%d ", heaps[i] + prefixSum(i));
        // }
        // puts("");

        int lb = 0;

        {
            int x = kv;

            for(int i=leftmostBit(heapSize);i>0;i/=2){
                if(lb + i <= heapSize && heaps[lb + i] + BIT[lb + i] > x){
                    x -= BIT[lb + i];
                    lb += i;
                }
            }

            lb += 1;
        }

        int ub = 0;

        {
            int x = kv;

            for(int i=leftmostBit(heapSize);i>0;i/=2){
                if(ub + i <= heapSize && heaps[ub + i] + BIT[ub + i] >= x){
                    x -= BIT[ub + i];
                    ub += i;
                }
            }

            ub += 1;
        }

        // printf("lb, ub: %d, %d\n", lb, ub);

        int m = ub - (k - (lb - 1));

        add2(1, -1);
        add2(lb, +1);
        add2(m, -1);
        add2(ub, +1);

        if(m <= k){
            kv -= 1;
        }
    }

    until(history.empty()){
        int i, v;
        std::tie(i, v) = history.top();
        history.pop();

        add(i, -v);
    }

    return res;
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    scanf("%d", &N);

    for(int i=0;i<N;++i){
        scanf("%d", &A);

        numCards[A] += 1;
    }

    for(auto &p : numCards){
        heaps.emplace_back(p.second);
    }

    heapSize = heaps.size();

    heaps.emplace_back(std::numeric_limits<int>::max());

    std::sort(heaps.rbegin(), heaps.rend());

    for(int k=1;k<=N;++k){
        printf("%d\n", simulate(k));
    }
}

