int main(){
  int N;
  cin >> N;
  vector<int> B(N);
  for(int i = 0; i < N; ++i){
    int a;
    cin >> a;
    --a;
    ++B[a];
  }
  sort(B.begin(), B.end());
  for(auto b : B) cerr << b << " ";
  cerr << endl;
  priority_queue<int> pq;
  for(int i = 0; i < N; ++i)
    pq.push(-B[i]);
  vector<int> ans(N);
  for(int i = N-1; i >= 0; --i){
    ans[i] = -pq.top();
    // cerr << i << " " << -pq.top() << endl;
    if(!i) break;
    int t = -pq.top();
    pq.pop();
    while(t){
      int k = pq.top();
      pq.pop();
      --k, --t;
      pq.push(k);
    }
  }
  for(int i = 0; i < N; ++i)
    cout << ans[i] << endl;
}

