                        if (vsize[1^op] > 1 && v[1^op][vsize[1^op] - 1].first == v[1^op][vsize[1^op] - 2].first)
                        {
                            v[1^op][vsize[1^op] - 2].second += v[1^op][vsize[1^op] - 1].second;
                            vsize[1^op]--;
                        }
                        v[1^op][vsize[1^op]] = {v[op][i].first - 1, k - si}, vsize[1^op]++;
                    }
                    else
                    {
                        v[1^op][vsize[1^op]] = {v[op][i].first - 1, v[op][i].second}, vsize[1^op]++;
                    }
                    for (int j = i + 1; j < vsize[op]; j++)
                    {
                        v[1^op][vsize[1^op]] = v[op][j], vsize[1^op]++;
                        if (vsize[1^op] > 1 && v[1^op][vsize[1^op] - 1].first == v[1^op][vsize[1^op] - 2].first)
                        {
                            v[1^op][vsize[1^op] - 2].second += v[1^op][vsize[1^op] - 1].second;
                            vsize[1^op]--;
                        }
                    }
                    if (vsize[1^op] && v[1^op][vsize[1^op] - 1].first == 0) vsize[1^op]--;
                    //v = g;
                    res++;
                    break;
                }
            }
            if (c < k)
            {
                break;
            }
        }
        cout << res << " ";
    }
}

