  for (auto i = 0; i < N; ++i)
  {
    cin >> A[i];
    --A[i];
  }
  vector<ll> H(N);
  for (auto i = 0; i < N; ++i)
  {
    H[A[i]]++;
  }
  vector<ll> C(N + 1);
  for (auto i = 0; i < N; ++i)
  {
    C[H[i]]++;
  }
  vector<ll> S(N + 1);
  S[0] = 0;
  for (auto x = 0LL; x < N; ++x)
  {
    S[x + 1] = S[x] + (x + 1) * C[x + 1];
  }
  vector<ll> T(N + 1);
  T[0] = accumulate(C.begin() + 1, C.end(), 0LL);
  for (auto x = 0LL; x < N; ++x)
  {
    T[x + 1] = T[x] - C[x + 1];
  }
  auto f = [&](ll x) {
    return (S[x] + x * T[x]) / x;
  };
  vector<ll> F(N + 1);
  for (auto i = 1; i <= N; ++i)
  {
    F[i] = f(i);
  }
  for (auto k = 1; k <= N; ++k)
  {
    ll ok{0}, ng{N + 1};
    while (abs(ok - ng) > 1)
    {
      ll t{(ok + ng) / 2};
      if (F[t] >= k)
      {
        ok = t;
      }
      else
      {
        ng = t;
      }
    }
    cout << ok << endl;
  }
