bool check(const vector<int>& h, int k, int x) {
    int sum = 0;
    for (int count: h) {
        sum += min(x, count);
    }
    return (x * k <= sum); 
} 


int solve(const vector<int>& h, int k) 
{
    int minX = 0;
    int maxX = (h[0] * h.size()) / k;

    while (minX < maxX) {
        int x = (minX + maxX + 1) / 2;
        if (check(h, k, x)) {
            // cout << k << ", " << x << " => OK" << endl;
            minX = x;
        } else {
            // cout << k << ", " << x << " => NG" << endl;
            maxX = x-1;
        }
    }

    return minX;
}

