int main()
{
  ll N;
  cin >> N;
  vector<ll> A(N);
  for (auto i{0}; i < N; ++i)
  {
    cin >> A[i];
    --A[i];
  }
  vector<ll> H(N, 0);
  for (auto a : A)
  {
    H[a]++;
  }
  vector<ll> C(N + 1, 0);
  for (auto h : H)
  {
    C[h]++;
  }
  vector<ll> S(N + 1), T(N + 1);
  S[1] = C[1];
  T[1] = 0;
  for (auto i{2}; i <= N; ++i)
  {
    T[1] += C[i];
  }
  for (auto x{1LL}; x <= N; ++x)
  {
    S[x + 1] = S[x] + (x + 1) * C[x + 1];
    T[x + 1] = T[x] - C[x + 1];
  }
  vector<ll> f(N + 1);
  for (auto x{1LL}; x <= N; ++x)
  {
    f[x] = S[x] / x + T[x];
  }
  for (auto K{1LL}; K <= N; ++K)
  {
    ll ok{0}, ng{N + 1};
    while (abs(ok - ng) > 1)
    {
      ll t{(ok + ng) / 2};
      if (f[t] >= K)
      {
        ok = t;
      }
      else
      {
        ng = t;
      }
    }
    cout << ok << endl;
  }
}

