	FOR_LE(i, 1, n) {
		ds[vs[i]]++;
	}

	vector<int> kdk(n + 1);
	vector<int> dk(n + 2);

	FOR_LE(k, 1, n) {
		kdk[k] = kdk[k - 1] + k * ds[k];
		dk[k] = dk[k - 1] + ds[k];
	}

	vector<int> fs(n + 2);
	FOR_LE(i, 1, n) {
		fs[i] = (kdk[i] + i*(dk[n] - dk[i])) / i;
	}

	int c = n;
	FOR_LE(v, 1, n) {
		while (c != 0 && fs[c] < v) c--;
		cout << c << endl;
	}

	return 0;
}

