	std::queue<PAIR> Y;
	FOR(k, 1, n + 1) {
		auto X(map);
		while (true) {
			int now = 0;
			for (auto it = X.rbegin(); it != X.rend(); ++it) {
				if (now + it->second >= k) {
					int t = k - now;
					Y.emplace(it->first, t);
					now += t;
					break;
				}
				Y.emplace(*it);
				now += it->second;
			}
