#define MAX 300001

int cnt[MAX];

int calc(int K) {
    int ret = 0;
    for (int th = 1; th < MAX; ++th) {
        if (cnt[0] < th) {
            break;
        }

        for (int i = 0; i < MAX; i += K) {
            bool ok = true;
            for (int j = i; j < i + K; ++j) {
                if (cnt[j] < th) {
                    ok = false;
                    break;
                }
            } 

            if (ok) {
                ++ret;
            } else {
                break;
            }
        }
    }

    return ret;
}

