int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int N; cin>>N;
  map<int, int> cards;
  for (int i = 0; i < N; i++) {
    int a; cin>>a;
    cards[a]++;
  }
  map<int, int> ccmap;
  for (auto& c : cards) {
    ccmap[c.second]++;
  }
  struct Dpe {
    int d, kd;
  };
  vector<Dpe> cum(N+1);
  cum[0] = {0,0};
  for (int i = 1; i < N+1; i++) {
    cum[i] = cum[i-1];
    auto find = ccmap.find(i);
    if (find != ccmap.end()) {
      cum[i].d += find->second;
      cum[i].kd += i * find->second;
    }
  }

  auto max_len_div = [&](int div) {
    return floor(float(cum[div].kd + div*(cum[N].d - cum[div].d)) / div);
  };
  for (int k = 1; k <= N; k++) {
    int l = 1, r = N;
    int res = 0;
    while (l <= r) {
      int c = (l+r)/2;
      if (max_len_div(c) >= k) {
        l = c+1;
        res = c;
      } else {
        r = c-1;
      }
    }
    cout << res << endl;
  }

  return 0;
}

