ll max_k_tuple(vector<ll> g, int k) {
  int n = g.size();
  if (n < k) {
    return 0;
  }
  sort(g.begin(), g.end());
  vector<ll> sum(n + 1), mx(n + 1);
  for (int i = 0; i < n; i++) {
    sum[i + 1] = sum[i] + g[i];
    mx[i + 1] = max(mx[i], g[i]);
  }
  while (k > 1) {
    if (sum[n] >= mx[n] * k) {
      return sum[n] / k;
    }
    --k;
    --n;
  }
  return sum[n];
}

