    vector<ll> sum(N + 1), mx(N + 1);
    for (int i = 0; i < N; i++) {
      sum[i + 1] = sum[i] + g[i];
      mx[i + 1] = max(mx[i], g[i]);
    }
    vector<int> id(N);
    iota(id.begin(), id.end(), 1);
    sort(id.begin(), id.end(), [&](int a, int b) {
      if (sum[a] * mx[b] != sum[b] * mx[a]) {
        return sum[a] * mx[b] > sum[b] * mx[a];
      }
      return a > b;
    });
    int i = 0, res_i = 0;
    vector<ll> res(N);
    for (int k = N; k >= 1; k--) {
      while (i < N && sum[id[i]] >= k * mx[id[i]]) {
        res_i = max(res_i, id[i]);
        ++i;
      }
      if (res_i > N - k + 1) {
        res[k - 1] = sum[res_i] / (k - (N - res_i));
      } else {
        res[k - 1] = sum[N - k + 1];
      }
    }
    for (ll x : res) cout << x << endl;
  }
  return 0;
