namespace Problem {
using namespace std;

class Solver {
 public:
  int n;
  vector<int> v;
  multiset<int> S;
  Solver(LL n) : n(n), v(n){};

  void solve() {
    map<int, int> cnt;
    vector<int> a;
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    for (int i = 0; i < n; ++i) {
      cnt[a[i]]++;
    }
    vector<int> inv(n);
    for (auto p : cnt) {
      for (int i = 0; i < p.second; ++i) {
        inv[i]++;
      }
    }
    for (auto i : inv) {
      if (i == 0) break;
      S.insert(i);
    }
    S.insert(0);
    vector<int> ans(n + 1);
    LL k = 1;
    for (; k * k <= n * log2(n); ++k) {
      ans[k] = calc(k);
    }
    int l_mid = ans[k - 1];
    int bound_prev = k - 1;
    for (int l = l_mid; l >= 0; --l) {
      int bound = calc_bound(l, bound_prev);
      for (int i = bound_prev + 1; i <= bound; ++i) {
        ans[i] = l;
      }
      bound_prev = bound;
    }
    for (int i = 1; i <= n; ++i) {
      cout << ans[i] << endl;
    }
  }
  int calc_bound(int l, int bound_prev) {
    int ub = n + 1;
    int lb = bound_prev;
    while (ub - lb > 1) {
      int mid = (ub + lb) / 2;
      if (calc(mid) >= l)
        lb = mid;
      else
        ub = mid;
    }
    return lb;
  }
  int calc(int k) {
    multiset<int> T = S;
    int ret = 0;
    while (1) {
      DBG(k, ret, T)
      auto it = T.lower_bound(k);
      if (it == T.end()) break;
      int add = *it / k;
      ret += add;
      int tmp = *it - k * add + *prev(it);
      T.erase(it);
      T.erase(prev(it));
      T.insert(tmp);
      T.insert(0);
    }
    return ret;
  }
};

