int main() {
    int n;
    in(n);

    auto a = vin<int>(n);

    vector<int> cnt(n);

    for (int i = 0; i < n; i++) {
        cnt[a[i]-1]++;
    }

    vector<int> ns;

    for (int i = 0; i < n; i++) {
        if (cnt[i] > 0) {
            ns.push_back(cnt[i]);
        }
    }

    sort(ns.rbegin(), ns.rend());

    for (int i = 1; i <= n; i++) {
        if (i == 1) {
            out(n);
            continue;
        }

        if (ns.size() < i) {
            out(0);
            continue;
        }

        priority_queue<int> que;

        for (int j = 0; j < ns.size(); j++) {
            que.push(ns[j]);
        }

        int ans = 0;

        while(que.size() >= i) {
            vector<int> pop(i);

            for (int j = 0; j < i; j++) {
                pop[j] = que.top();
                que.pop();
            }

            for (int j = 0; j < i; j++) {
                int mini = *min_element(pop.begin(), pop.end());
                if (pop[j] - mini != 0) {
                    que.push(pop[j] - mini);
                }
            }

            ans++;
        }

        out(ans);
    }
}

