const int N = 300010;
vector<P> tmp(N);
vector<Int> Sum(N);

Int calc(deque<P> M, Int K, Int N){
  Int cnt = 0;
  if(K == 1) return N;

  while(1){
    int idx = 0;
    {
      Int sum = 0;
      while(sum < K){
        if(M.empty()) return cnt;
        auto t = M.front(); M.pop_front();
        if(t.first == 0) continue;
        Sum[idx] = sum;
        sum += t.second;
        tmp[idx] = t;
        idx++;
      }
    }

    while(--idx >=0 ){
      auto p = tmp[idx];
      Int sum = Sum[idx];
      if(sum + p.second <= K){
        if(p.first - 1 > 0) {
          if(M.size() && M[0].first == p.first - 1) M[0].second += p.second;
          else if(p.first - 1 > 0) M.push_front(P(p.first - 1, p.second));
        }
      }
      else{
        if(M.size() && M.front().first == p.first - 1) M[0].second += K - sum;
        else if(p.first - 1 > 0) M.push_front(P(p.first - 1, K - sum));
        M.push_front(P(p.first, p.second - (K - sum)));
      }
      sum += p.second;
    }
    cnt++;
  }
}

