vector<int> naive(int N) {
  vector<int> ans;

  for (int i=0; i<=N; i++) {
    counter[i] = 0;
    num[i] = 0;
  }

  for (int i=0; i<N; i++) {
    counter[A[i]-1]++;
  }

  for (int K=1; K<=N; K++) {
    priority_queue<pair<int,int>> pq;

    for (int i=0; i<N; i++) {
      if (counter[i])
        pq.push({counter[i], i});
    }

    int calc = 0;
    while((int)pq.size() >= K) {
      vector<pair<int,int>> vec;

      for (int i=0; i<K; i++) {
        auto p = pq.top(); pq.pop();

        p.first--;

        if (p.first)
          vec.push_back(p);
