vector<int> solve(int N) {
  vector<int> ans;

  for (int i=0; i<=N; i++) {
    counter[i] = 0;
    num[i] = 0;
  }

  for (int i=0; i<N; i++) {
    counter[A[i]-1]++;
  }

  int sum = N;
  for (int i=0; i<N; i++) {
    num[counter[i]]++;
  }

  int cc = 0;
  int t = N; //各
  for (int i=1; i<=N; i++) {
    while (t > sum / i) {
      cc += num[t];
      sum -= cc;
      t--;
    }

    ans.push_back(sum / i);
  }

  return ans;
}

