struct node {
    ll add = 0;
    ll replace = -LL_INF;
    ll val;
};

node res_operation(node l, node r) {
    return node{0, -LL_INF, min(l.val, r.val)};
}

void change_operation(node &n, ll rep, ll add) {
    if (rep != -LL_INF) {
        n.replace = rep;
        n.val = rep;
        n.add = 0;
    } else {
        if (n.replace != -LL_INF)
            n.replace += add;
        else {
            n.add += add;
        }
        n.val += add;
    }
}

vector<ll> mas(2'020'202);
vector<node> tree(2'020'202);

void propagate(ll node_index) {
    change_operation(tree[node_index * 2], tree[node_index].replace, tree[node_index].add);
    change_operation(tree[node_index * 2 + 1], tree[node_index].replace, tree[node_index].add);
    tree[node_index].replace = -LL_INF;
    tree[node_index].add = 0;
}

node build_tree(ll left, ll right, ll cur_node) {
    if (left == right) {
        tree[cur_node] = node{0, -LL_INF, mas[left]};
    } else {
        tree[cur_node] = res_operation(build_tree(left, (left + right) / 2, cur_node * 2),
                                       build_tree((left + right) / 2 + 1, right, cur_node * 2 + 1));
    }
    return tree[cur_node];
}

void change_segment(ll node_ind, ll tree_l, ll tree_r, ll ql, ll qr, ll rep, ll add) {
    if (tree_l != tree_r) {
        propagate(node_ind);
    }
    if (ql > tree_r || qr < tree_l || qr < ql)
        return;
    if (ql == tree_l && qr == tree_r) {
        change_operation(tree[node_ind], rep, add);
    } else {
        ll mid = (tree_l + tree_r) / 2;
        change_segment(2 * node_ind, tree_l, (tree_l + tree_r) / 2, ql, min(qr, mid), rep, add);
        change_segment(2 * node_ind + 1, mid + 1, tree_r, max(mid + 1, ql), qr, rep, add);
        tree[node_ind] = res_operation(tree[2 * node_ind + 1], tree[2 * node_ind]);
    }
}

node get_segment(ll node_ind, ll tree_l, ll tree_r, ll ql, ll qr) {
    if (tree_l != tree_r) {
        propagate(node_ind);
    }
    if (ql > tree_r || qr < tree_l || qr < ql)
        return node{0, -LL_INF, LL_INF};
    if (ql == tree_l && qr == tree_r) {
        return tree[node_ind];
    } else {
        ll mid = (tree_l + tree_r) / 2;
        node left = get_segment(2 * node_ind, tree_l, mid, ql, min(qr, mid));
        node right = get_segment(2 * node_ind + 1, mid + 1, tree_r, max(ql, mid + 1), qr);
        return res_operation(left, right);
    }
}

ll cur_i = 0;

ll get_left(ll n) {
    ll left = 0;
    ll right = cur_i - 1;
    ll cur_node = 1;
    while (left != right) {
        if (tree[2 * cur_node].val > n) {
            cur_node = 2 * cur_node;
            ll mid = (left + right) / 2;
            right = mid;
        }else if(tree[2 * cur_node + 1].val > n){
            cur_node = 2 * cur_node + 1;
            ll mid = (left + right)/2;
            left = mid + 1;
        }else{
            return LL_INF;
        }
    }
}

