  // for (ll i = 1; i <= N; ++i) {
  //   cout << f[i] << endl;
  // }

  // Here, the maximum X where K <= f(X) is the answer of each K.

  reverse(all(f));
  f.resize(N); // f[N] is thrown away.
  // Now, f is increasing order.
  for (int i = 1; i <= N; ++i) {
    auto it = lower_bound(all(f), i);
    if (it != f.end()) {
      int j = it - f.begin(); // index
      cout << (N - j) << endl;
    } else { // not found
      cout << 0 << endl;
    }
  }
}

