void solve(){
  ini(N);
  vi v(N); in(v);
  vi cnt(N);
  rep(i,N) cnt[v[i] - 1]++;
  sort(all(cnt) , greater<int>());

  int curans = N , rest = N , s = N;
  rep1(k,N){
    trc(k);
    //trc(cursum);
    if(k == 1) out(N);
    else {
      rest -= cnt[k - 2];
      s += curans - cnt[k - 2];
      // 今はいくつ？
      trc(curans , rest , s);
      auto it = lower_bound(all(cnt) , curans , greater<int>());
      int curidx = it - cnt.begin();
      trc(curidx);
      while(rest < s){

        trc(curans , rest , s , curidx);
        if(rest < s - (curans - cnt[curidx]) * (k-curidx)){
          s -= (curans - cnt[curidx]) * (k-curidx);
          curans = cnt[curidx];
          curidx++;
        }
        else {
          while(rest < s) {
            s -= k - curidx;
            curans--;
          }
        }
      }
      out(curans);

    }
  }
}

