int main() {
  int N;
  cin >> N;
  vector< int > A(N);
  cin >> A;


  map< int, int > mp;
  for(auto &a : A) mp[a]++;
  map< int, int > uku;
  for(auto &a : mp) uku[a.second]++;


  auto beet = [&](int sz) {
    stack< pair< int, int > > que;
    for(auto &p : uku) que.emplace(p);
    int ret = 0;


    while(que.size()) {
      vector< pair< int, int > > nxt;
      int add = 0;
      while(que.size() && add < sz) {
        auto p = que.top();
        que.pop();
        add += p.second;
        if(nxt.size() && nxt.back().first == p.first) {
          nxt.back().second += p.second;
        } else {
          nxt.emplace_back(p);
        }
      }
      auto v = nxt.front();
      v.second = add - sz;
      nxt.front().second -= add - sz;
      if(add < sz) {
        break;
      }
      ret++;
      reverse(begin(nxt), end(nxt));
      for(auto &p : nxt) {
        p.first--;
        if(p.first > 0) {
          que.emplace(p.first, p.second);
        }
      }

      if(v.second) {
        que.emplace(v);
      }
    }
    return ret;
  };


  vector< int > ans(N + 1);
  ans[1] = beet(1);
  ans[N] = beet(N);
  auto rec = MFP([&](auto rec, int l, int r) -> void {
    while(l < r && ans[l] == ans[r]) ans[++l] = ans[r];
    if(r - l <= 1) return;
    int mid = (l + r) >> 1;
    ans[mid] = beet(mid);
    rec(l, mid);
    rec(mid, r);
  });
  rec(1, N);
  for(int i = 1; i <= N; i++) cout << ans[i] << "\n";
}

