        }

        sort(all(C));

        Int sum = 0;
        int idx = 0;
        vector<Int> anss(N + 1);
        for (int k = 1; k <= N; ++k) {
            while (idx <= N && C[idx] < k) {
                sum += C[idx];
                idx++;
            }
            Int pre = sum;
            Int suf = (N - idx + 1) * k;
            Int val = pre + suf;
            Int K = val / k;
            anss[K] = k;
        }
        for (int K = N; K > 0; --K) {
            chmax(anss[K - 1], anss[K]);
        }

        for (int i = 1; i <= N; ++i) {
            cout << anss[i] << endl;
        }

    }
};


