int count(int K, vector<int> myset){
    int ans = 0;
    int kk = myset.size() - 1;
    while(true){
        vector<int> addlist;
        int i = K;
        while(i>0 && kk>0){
            if(myset[kk]>0){
                myset[kk]--;
                addlist.push_back(kk - 1);
                i--;
                ans++;
            }
            else{
                kk--;
            }
        }
        if(i!=0)
            break;
        for(int kkk : addlist) {
            myset[kkk]++;
            kk = max(kk, kkk);
        }
    }
    return ans/K;
}
