struct Node {
  int sum;
  priority_queue<int> que;

  Node(int sum = -1) {
    this->sum = sum;
  }

  bool operator>(const Node &n) const {
    return sum > n.sum;
  }
};

int main() {
  int N;
  cin >> N;

  int a;
  vector<int> A;
  map<int, int> counter;

  for (int i = 0; i < N; ++i) {
    cin >> a;
    counter[a] += 1;
    A.push_back(a);
  }

  priority_queue <Node, vector<Node>, greater<Node> > pque;

  for (auto t : counter) {
    Node node(t.second);
    node.que.push(t.second);
    pque.push(node);
  }

  int ans[N + 1];
  memset(ans, 0, sizeof(ans));
  ans[1] = N;
  int L = pque.size();

  for (int i = 0; i < L - 1; ++i) {
    int K = L - i;
    Node node = pque.top();
    pque.pop();

    // fprintf(stderr, "%d\n", node.sum);
    ans[K] = node.sum;

    priority_queue<int> que = node.que;

    while (!que.empty()) {
      int v = que.top();
      que.pop();

      Node cand = pque.top();
      pque.pop();
      cand.sum += v;
      cand.que.push(v);
      pque.push(cand);
    }
  }

  for (int i = 1; i <= N; ++i) {
    cout << ans[i] << endl;
  }

  return 0;
}

