template<class Type>
Type solve(Type res = Type()){
    int N; cin >> N;
    vector<int> A(N);
    for(auto& in:A) cin >> in;

    vector<int> C(N+1);
    for(int i = 0; i < N;i++) C[A[i]]++;
    vector<int> D(N+1);
    for(int i = 0; i <= N;i++) D[C[i]]++;

    vector<int> f(N+1);
    vector<int> cumD(D.size()+1);
    vector<int> cumkD(D.size()+1);
    for(int k = 0; k <= N;k++){
        cumD[k+1] = cumD[k] + D[k];
        cumkD[k+1] = cumkD[k] + k*D[k];
    }
    for(int X = 1; X <= N; X++){
        f[X] = (cumkD[X] + X*(cumD[N+1] - cumD[X]))/X;
    }
    vector<int> Ans(N+1);
    for(int K = 1; K <= N; K++){
        Ans[f[K]] = max(Ans[f[K]],K);
    }
    for(int K = N-1; K >= 1; K--){
        Ans[K] = max(Ans[K+1],Ans[K]);
    }
    for(int K = 1; K <= N;K++){
        cout << Ans[K] << endl;
    }
    return res;
}
