int solve(vector<int> m, int N, int K, int MAX) {
    if (K == 1) return N;

    int ans = 0;

    while (true) {
        int cnt = 0;
        vector<pair<int, int>> a;
        int MIN;
        int NOW_MAX = 0;

        int use_count = 0;
        // cerr << "MAX = " << MAX << endl;
        RREPS(i, MAX) {
            int l = m[i];
            if (l == 0) continue;

            a.pb(mp(i, l));
            cnt += l;
            MIN = i;
            NOW_MAX = max(NOW_MAX, i);

            if (cnt >= K) {
                int CCC = 1;


                use_count = i;

                ans += use_count * CCC;

                int remain = cnt - K * CCC;
                int M = SZ(a);
                RREP(j, M) {
                    int n = a[j].second - remain;
                    m[a[j].first] -= n;
                    m[a[j].first - use_count] += n;

                    remain = 0;
                }

                break;
            }
        }

        MAX = max(MIN, NOW_MAX - use_count);

        if (N - (m[0]) < K) break;
    }

    return ans;
}

