int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}

template <typename T1, typename T2>
vector<T2> accum(vector<T1>& a, T2 init) {
    int L = a.size();
    vector<T2> acc(L + 1);
    acc[0] = init;
    for (int i=0; i<L; ++i) acc[i+1] = acc[i] + a[i];
    return move(acc);
}

template <typename T>
T accumed(vector<T>& acc, int from, int to) {
    int M = acc.size() - 1;
    return acc[min(M, to)] - acc[max(0, from)];
}

void solve(int N, vi& _a) {
    map<int,int> st;
    for(int x:_a) st[x]++;

    vi a;
    for (auto& p: st){
        a.pb(p.second);
    }
    sort(ALL(a));
    vll ac=accum(a, 0LL);
    int M = a.size();

    for(int k=1; k<=N; ++k){
        int lo=0, hi=N+1;
        while (lo+1 < hi){
            int m = (lo+hi)/2;
            int ix = upper_bound(ALL(a), m) - a.begin();
            ll pre = accumed(ac, 0, ix), post = (ll)m * (M - ix), cnt = pre + post;
            if (cnt >= (ll)k*m) {
                lo = m;
            } else {
                hi = m;
            }
        }
        printf("%d\n", lo);
    }
}

