int sum(vector<int>& groups, vector<int>& sums, int times) {
	int s = 0;
	int l = groups.size();
	for (int i = 0; i < l; i++) {
		s += min(groups[i], times);
	}

	return s;
}

int findGreater(vector<int>& v, int times) {
	int len = v.size();
	int start = 0;
	int end = len - 1;
	while (start < end) {
		int m = start + (end - start) / 2;
		if (v[m] < times && v[m + 1] < times) {
			start = m + 1;
		}
		else if (v[m] >= times && v[m + 1] >= times) {
			end = m;
		}
		else {
			return m;
		}
	}

	if (end == 0) {
		return -1;
	}

	return len - 1;
}

