const int INF = 300001;

using namespace std;

int solve(vector<pair<int, int>> xs, const int k) {
    int count = 0;
    int i = 0;
    int j = 0;
    int min = INF;

    while (i + k <= ((int) xs.size())) {
        // cout << i << ", " << j << ", " << endl;
        if (xs[i+j].second > 0) {
            if (xs[i+j].second < min) {
                min = xs[i].second;
            }
            j++;
            if (j == k) {
                count += min;
                for (int m = 0; m < k; m++) {
                    xs[i+m].second -= min;
                }
                j = 0;
                min = INF;
            }
        } else {
            i++;
        }
    }

    return count;
}

