void solve() {
    int n;
    cin >> n;
    map<int, int> mp;
    rep(i, n) {
        int a;
        cin >> a;
        mp[a]++;
    }
    vector<int> A, S;
    for (auto x : mp) A.push_back(x.se);
    sort(all(A));
    S.push_back(0);
    for (int a : A) {
        int nxt = S.back() + a;
        S.push_back(nxt);
    }
    REP(i, 1, n) {
        int ok = 0, ng = n/i + 1;
        while(ng - ok > 1) {
            int mid = (ng + ok) / 2;
            int idx = lower_bound(all(A), mid) - A.begin();
            int m = S[idx] + (A.size() - idx) * mid;
            if (m >= mid * i) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        cout << ok << endl;
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
    return 0;
}

