    while (cin >> N) {
        ma.clear();
        for (int i = 0; i < N; ++i) {
            long long a;
            cin >> a;
            ma[a]++;
        }
        vector<long long> v;
        for (auto it : ma) v.push_back(it.second);

        sort(v.begin(), v.end());

        //COUT(v);

        long long sum = v[0];
        long long num = 1;
        deque<long long> d;

        for (int i = 1; i < v.size(); ++i) {
            // v[i] 以下が何個か
            long long low = 0, high = N+1;
            while (high - low > 1) {
                long long mid = (low + high) / 2;
                long long val;
                if (mid > d.size()) {
                    long long div = num - (mid - (int)d.size() - 1);
                    if (div <= 0) val = 1LL<<50;
                    else val = sum / div;
                }
                else val = d[(int)d.size() - mid];

                if (val >= v[i]) high = mid;
                else low = mid;
            }

            /*
            COUT("---------------");
            COUT(i);
            COUT(v[i]);
            COUT(low);
            COUT(d);
            */

            while (d.size() > low) d.pop_front();
            while (d.size() < low) {
                long long div = i - (int)d.size();
                d.push_front(sum / div);
            }
            sum += v[i];
            num = i+1 - low;

            //COUT(sum); COUT(num); COUT(d);
        }

        for (int i = 0; i < num; ++i) cout << sum / (i+1) << endl;
        for (int i = 0; i < d.size(); ++i) cout << d[i] << endl;
        for (int i = 0; i < N - num - (int)d.size(); ++i) cout << 0 << endl;       
