int main(){
  int N;
  cin >> N;
  map<int,int> m;
  rep(i,N){
    int a;
    cin >> a;
    m[a]++;
  }
  vector<int> ret(N+1,0);
  ret[1] = N;

  int M = m.size();
  REP(i,M+1,ret.size()) ret[i] = 0;

  queue<pair<int,int>> que;
  FOR(it,m){
    que.push(make_pair(it->first,it->second));
  }
  vector<int> w;
  while(true){
    queue<pair<int,int>> tmp;
    int cnt = 0;
    rep(i,M){
      if(que.empty()) break;
      pair<int,int> t = que.front(); que.pop();
      cnt++;
      t.second--;
      if(t.second > 0) tmp.push(t);
    }

    w.push_back(cnt);
    if(tmp.empty()) break;
    swap(que,tmp);
  }

  int j = 0;
  int stock = 0;
  for(int i=M; i>1; i--){
    while(j<w.size()){
      if(w[j] + stock >= i){
        stock -= i - w[j];
        j++;
      }else{
        break;
      }
    }
    while(stock >= i){
      stock -= i;
      j++;
    }
    stock += j;
    ret[i] = j;
  }

  REP(i,1,N+1){
    cout << ret[i] << endl;
  }

  return 0;
}

