int main(int argc, char* argv[]){
  init_io(argc, argv);

  int N;
  cin >> N;

  VI xs_(N);
  cin >> xs_;

  map<int,int> ys;
  for(auto x : xs_) ys[x]++;

  VI xs;
  for(auto p : ys) xs.PB(p.SS);

  SORT(xs);
  int M = SZ(xs);
  VL acc(M+1);
  REP(i,M) acc[i+1] = acc[i] + xs[i];

  int lb = 1, ub = M+1;
  while(ub - lb > 1){
    int k = (lb + ub) / 2;

    LL can = acc[M-k+1];
    for(int j=2;j<=k;++j){
      int ix = M-1-k+j;
      if(can >= xs[ix]){
        can = acc[ix+1] / j;
      }
    }

    if(can == acc[M] / k) lb = k;
    else ub = k;
  }

  VL ans(N, -1);
  FOR(k,1,lb+1) ans[k-1] = acc[M] / k;

  int beg = M - 1 - lb;
  FOR(k,lb+1,N+1){
    if(beg < 0) ans[k-1] = 0;
    else {
      //ans[k-1] = min(xs[beg], acc[beg+1]);
      ans[k-1] = acc[beg+1];
    }
    beg--;
  }

  for(auto x : ans) cout << x << endl;

  return 0;
}

