int main()
{
    int n;
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i) {
        int x;
        scanf("%d", &x);
        amt[x]++;
    }
    for (int i = 1; i <= n; ++i) {
        amts[amt[i]]++;
    }
    int x = 0;
    for (int i = 1; i <= n; ++i) {
        if (amts[i] != 0) {
            x += amts[i];
        }
    }
    int it = 0;
    int sz = 0;
    for (int i = 1; i <= n; ++i) {
        if (amts[i] == 0) continue;
        for (int j = 1; j <= i - sz; ++j) {
            len[++it] = x;
        }
        sz += i - sz;
        x -= amts[i];
    }
    for (int i = 0; i <= n; ++i) {
        lst[i] = it;
    }
    for (int i = it; i; --i) {
        lst[len[i]] = i;
    }
    for (int i = 1; i <= n; ++i) {
        lst[i + 1] = min(lst[i + 1], lst[i]);
    }
    for (int i = 1; i <= it; ++i) {
        sums[i] = sums[i - 1] + len[i];
    }
    for (int i = 1; i <= n; ++i) {
        printf("%d\n", sums[lst[i - 1]] / i);
    }
}

