struct data{
  Int first, second;
  data(){}
  data(Int first, Int second):first(first), second(second){};
  bool operator <(const data &a)const{
    return first < a.first;
  }
  bool operator >(const data &a)const{
    return first > a.first;
  }
};

Int calc(deque<data> M, Int K, Int N){
  using P = data;
  Int cnt = 0;
  if(K == 1) return N;

  while(1){
    vector<P> tmp;
    vector<Int> Sum;
    {
      Int sum = 0;
      while(sum < K){
        if(M.empty()) return cnt;
        auto t = M.front(); M.pop_front();
        if(t.first == 0) continue;
        Sum.push_back(sum);
        sum += t.second;
        tmp.push_back(t);
      }
    }

    for(Int i=tmp.size() - 1;i>=0;i--){
      auto p = tmp[i];
      Int sum = Sum[i];
      if(sum + p.second <= K){
        if(p.first - 1 > 0) {
          if(M.size() && M[0].first == p.first - 1) M[0].second += p.second;
          else if(p.first - 1 > 0) M.push_front(P(p.first - 1, p.second));
          //M[p.first - 1] += p.second;
        }
      }
      else{
        if(M.size() && M.front().first == p.first - 1) M[0].second += K - sum;
        else if(p.first - 1 > 0) M.push_front(P(p.first - 1, K - sum));
        M.push_front(P(p.first, p.second - (K - sum)));
      }
      sum += p.second;
    }
    cnt++;
  }
}

