i64 solve(const vi &S, i64 K) {
  i64 i = 0, j;
  vi M(K, 0);
  while(i < sz(S)) {
    REP(0, K, j) {
      if(i == sz(S))
	break;
      M[j] += S[i];
      ++i;
    }
    sort(all(M));    
  }
  return M[0];
}

int main(int argc, char *argv[]) {

  i64 N, i;
  cin >> N;
  map<i64,i64> M;
  REP(0, N, i) {
    i64 A;
    cin >> A;
    if(M.find(A) == M.end()) 
      M[A] = 1;
    else
      M[A]++;
  }

  vi S;
  S.reserve(M.size());
  for(auto m: M) {
    S.push_back(m.second);
  }
  sort(all(S), greater<i64>());

  i64 K;
  REP(1, N+1, K) {
    cout << solve(S, K) << endl;
  }

  return 0;
}

