int main() {
  int N;
  cin >> N;
  vector< int > A(N);
  cin >> A;

  map< int, int > mp;
  for(auto &a : A) mp[a]++;
  vector< int > uku;
  for(auto &p : mp) uku.emplace_back(p.second);
  sort(uku.rbegin(), uku.rend());

  auto beet = [&](int sz) {
    queue< int > in;
    int ret = 0;
    for(int i : uku) {
      in.emplace(ret + i);
      while(in.size() && in.front() <= ret) in.pop();
      if(in.size() == sz) ret += in.front() - ret;
    }
    return ret;
  };

  vector< int > ans(N + 1);
  ans[1] = beet(1);
  ans[N] = beet(N);
  auto rec = MFP([&](auto rec, int l, int r) -> void {
    while(l < r && ans[l] == ans[r]) ans[++l] = ans[r];
    if(r - l <= 1) return;
    int mid = (l + r) >> 1;
    ans[mid] = beet(mid);
    rec(l, mid);
    rec(mid, r);
  });
  rec(1, N);
  for(int i = 1; i <= N; i++) cout << ans[i] << "\n";
}

