	for (int K = 1; K <= N; K++) {
		std::vector<std::pair<int, int>> cardsTemp(cards);
		int count = 0;
		while (true) {
			int consume = K;// K枚消費すべし

			for (auto& pair : cardsTemp) {
				// 枚数が多いものから順に

				if (pair.second <= 0) continue;

				pair.second--;
				consume--;
				if(consume <= 0)break;
			}
			if (consume <= 0) count++;
			else              break;
		}

		printf("%d\n", count);
	}

	return 0;
