    int ret = 0;


    while(que.size()) {
      vector< pair< int, int > > nxt;
      int add = 0;
      while(que.size() && add < sz) {
        auto p = que.top();
        que.pop();
        add += p.second;
        if(nxt.size() && nxt.back().first == p.first) {
          nxt.back().second += p.second;
        } else {
          nxt.emplace_back(p);
        }
      }
      reverse(begin(nxt), end(nxt));
      auto v = nxt.back();
      v.second = add - sz;
      nxt.back().second -= add - sz;
      if(add < sz) {
        break;
      }
      if(v.second) {
        que.emplace(v);
      }
      ret++;
      for(auto &p : nxt) {
        p.first--;
        if(p.first > 0) {
          que.emplace(p.first, p.second);
        }
      }
    }
    return ret;
  };


  vector< int > ans(N + 1);
  ans[1] = beet(1);
  ans[N] = beet(N);
  auto rec = MFP([&](auto rec, int l, int r) -> void {
    while(l < r && ans[l] == ans[r]) ans[++l] = ans[r];
    if(r - l <= 1) return;
    int mid = (l + r) >> 1;
    ans[mid] = beet(mid);
    rec(l, mid);
    rec(mid, r);
  });
  rec(1, N);
  for(int i = 1; i <= N; i++) cout << ans[i] << "\n";
}

