const LL INF = 1e9 + 7;
const int N = 3e5 + 10;
int ans[N];
map<int, int> mc;
vector<pair<int, int>> v;
void add(vector<pair<int, int>>& vp, int a, int b)
{
	if (!vp.empty() && vp.back().first == a) vp.back().second += b;
	else vp.emplace_back(a, b);
}
void solve(int key)
{
	if (ans[key] != -1) return;
	auto pq = v;
	int& res = ans[key] = 0;
	while (!pq.empty())
	{
		int sum = 0;
		vector<pair<int, int>> vp;
		while (!pq.empty() && sum < key)
		{
			sum += pq.back().second;
			vp.push_back(pq.back());
			pq.pop_back();
		}
		if (sum < key) break;
		if (vp.size() == 1)
		{
			int a, b;
			tie(a, b) = vp.back();
			res += b / key;
			if (a > 1 && b >= key)
				add(pq, a - 1, b / key * key);
			if (b % key)
				add(pq, a, b % key);
			continue;
		}
		res++;
		int cur = key;
		for (auto& p : vp)
		{
			int a, b;
			tie(a, b) = p;
			int o = min(cur, b);
			cur -= o;
			if (b - o > 0)
			{
				if(a > 1) add(pq, a - 1, o);
				add(pq, a, b - o);
				p.second = 0;
			}
		}
		reverse(vp.begin(), vp.end());
		for (auto& p : vp)
		{
			if (p.second == 0) continue;
			if (p.first > 1) add(pq, p.first - 1, p.second);
		}
	}
	if (res == 0)
	{
		for (int i = key + 1; i < N; i++)
		{
			if (ans[i] == 0) break;
			ans[i] = 0;
		}
	}
}
