int ok(int n,int k,ll mid,ll a[],ll s,ll val, ll sum[]){

    int l = 1;
    int r = k;
    int id = 0;
    while(l<=r){
        int mid1 = (l+r)/2;
        if(a[mid1]-val >= mid){
            id = max(id,mid1);
            l = mid1+1;
