vector<int> line;

int func(int n){
	priority_queue<int> pq;
	foreach(i, line)pq.push(i);
	int res = 0;
	while(true){
		vector<int> na;
		rep(i, n){
			if(pq.empty())return res;
			int d = pq.top()-1;
			pq.pop();
			if(d)
				na.push_back(d);
		}
		++res;
		foreach(i, na)pq.push(i);
	}
	return res;
}


