        for(ll j = 0; j+k <= C.size(); j++){
            ll q = seg.query(0, j+1);
            if(q > C[j]){
                sum -= q-C[j];
                break;
            }
            sum += C[j]-q;
            seg.update(j, seg[j] + C[j]-q);
            seg.update(j+k, seg[j+k] - (C[j]-q));
