int main() {
  int N;
  cin >> N;
  vector< int > A(N);
  cin >> A;

  map< int, int > mp;
  for(auto &a : A) mp[a]++;

  auto beet = [&](int sz) {
    priority_queue< int, vector< int >, greater< int > > que;
    for(auto &p : mp) que.emplace(p.second);
    int ret = 0;
    while(que.size() >= sz) {
      ++ret;
      vector< int > nxt(sz);
      for(int i = 0; i < sz; i++) {
        int p = que.top();
        --p;
        nxt[i] = p;
        que.pop();
      }
      for(int i = 0; i < sz; i++) {
        if(nxt[i] > 0) {
          que.emplace(nxt[i]);
        }
      }
    }
    return ret;
  };

  vector< int > ans(N + 1);
  ans[1] = beet(1);
  ans[N] = beet(N);
