int solve_F() {
  uint64_t N;
  std::cin >> N;

  // 各値の個数を数える
  std::vector<uint64_t> counts(N);
  for (size_t i = 0; i < N; ++i) {
    uint64_t A;
    std::cin >> A;
    counts[A - 1]++;
  }

  // 1個以上あった値のみで昇順にソートする
  counts.erase(std::remove(counts.begin(), counts.end(), 0), counts.end());
  std::sort(counts.begin(), counts.end());

  // 1つ前との差分を計算する
  std::vector<uint64_t> deltas(counts.size());
  deltas[0] = counts[0];
  for (size_t i = 1; i < counts.size(); ++i) {
    deltas[i] = counts[i] - counts[i - 1];
  }

  const uint64_t counts_size = counts.size();
  std::vector<uint64_t> results(counts_size);
  for (uint64_t i = 0; i < counts_size; ++i) {
    const auto delta = deltas[i];
    const uint64_t max_K = counts_size - i;
    for (uint64_t K = 1; K <= max_K; ++K) {
      const uint64_t n = max_K / K;
      results[static_cast<size_t>(K - 1)] += delta * n;
    }
  }

  // 結果発表
  for (const auto result : results) {
    std::cout << result << '\n';
  }

  return 0;
}

int main() {
  return solve_F();
}

