Int calc(map<Int, Int> M, Int K, Int N){
  //prArr(M);
  Int cnt = 0;
  if(K == 1) return N;

  while(1){
    vector<P> tmp;
    {
      Int sum = 0;
      while(sum < K){
        if(M.empty()) return cnt;
        auto it = --M.end();
        auto t = *it; M.erase(it);
        if(t.first == 0) continue;
        sum += t.second;
        tmp.push_back(t);
      }
    }

    Int sum = 0;
    for(auto p:tmp){
      if(sum + p.second <= K){
        if(p.first - 1 > 0) M[p.first - 1] += p.second;
      }
      else{
        if(p.first - 1 > 0) M[p.first - 1] += (K - sum);
        M[p.first] += p.second - (K - sum);
        //pr(p.first, M[p.first - 1], M[p.first]);
      }
      sum += p.second;
    }
    cnt++;
  }
}

