using std::map;
using std::priority_queue;

const int MAXN=3e5+5;

map<int,int> mp;

inline int calc(int K){
	static int tmp[MAXN];
	priority_queue<int> pq;
	for(auto &i:mp)
		pq.push(i.second);
	int ret=0;
	while(true){
		int k=1;
		for(;pq.size() && k<=K;++k){
			tmp[k]=pq.top();
			pq.pop();
		}
		if(k<=K) break;
		++ret;
		for(int i=1;i<=K;++i){
			if(tmp[i]>1) pq.push(tmp[i]-1);
		}
	}
	return ret;
}

int main(){
	int n;
	scanf("%d",&n);
	for(int i=1,x;i<=n;++i){
		scanf("%d",&x);
		++mp[x];
	}
	for(int i=1;i<=n;){
		int ans=calc(i);
		int l=i,r=n;
		while(l<=r){
			int mid=l+r>>1;
			if(calc(mid)==ans) l=mid+1;
			else r=mid-1;
		}
		for(;i<=r;++i)
			printf("%d\n",ans);
	}
	return 0;
}

