            if(x2<x+add/y){
                p[x2]+=y;
                add-=y*(x2-x);
            }else{
                p[x+add/y+1]+=add%y;
                p[x+add/y]+=y-add%y;
                break;
            }
        }
    }
    ans[0]=(*p.begin()).first;
    rep(i,n){
        cout<<ans[i]<<endl;
    }
}

