	for (const auto card : cards) {
		card_count[card - 1]++;
	}
	std::sort(card_count.begin(), card_count.end());
	std::vector<int> sum_of_card_count{ 0 }; sum_of_card_count.reserve(n + 1);
	for (auto c: card_count) sum_of_card_count.push_back(c + sum_of_card_count.back());
	for (auto t = 1; t <= n; ++t) {
		auto small = sum_of_card_count[n - t];
		auto min = 0;
		auto max = n / t;
		while (min < max) {
			auto mid = (min + max + 1) / 2;
			if (card_count[n - t] >= mid) min = mid;
			else {
				auto idx = std::distance(card_count.begin(), std::lower_bound(card_count.begin(), card_count.end(), mid));
				auto middle = sum_of_card_count[idx] - small;
				auto middle_count = t - (n - idx);
				if (middle + small >= middle_count * mid) {
					min = mid;
				}
				else {
					max = mid - 1;
				}
			}
		}
		std::cout << min << '\n';
	}
}

