    msb = leftmostBit(heapSize);

    heaps.emplace_back(std::numeric_limits<int>::max());

    std::sort(heaps.rbegin(), heaps.rend());

    for(int k=1;k<=N;++k){
        int res = 0;

        if(k <= heapSize){
            res = simulate(k);
        }

        printf("%d\n", res);
    }
}

