int n, a[N], res, tot;
priority_queue <int, vector <int>, less<int> > pq; 
bool ok(int k) {
	while (!pq.empty()) {
		int top = pq.top(); pq.pop();
		if (top > res) {
			pq.push(top - 1);
			--tot;
		} else {
			pq.push(top);
			break;
		}
	}
	return tot / k >= res;
}
void run() {
	memset(a, 0, sizeof a);
	while (!pq.empty()) pq.pop();
	for (int i = 1; i <= n; ++i) ++a[rd()];
