#define MAX 310000
int N, A[MAX];

vector<int> convert() {
  map<int,int> mp;
  rep(i,N) ++mp[A[i]];
  vector<int> C;
  for(auto v : mp) C.push_back(v.second);
  sort(ALL(C));
