signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	V<int> base;
	{
		std::map<int, int> map;
		std::map<int, int> mp;
		REP(i, n) ++mp[a[i]];
		for (auto& p : mp) ++map[p.second];
		base.resize(map.rbegin()->first + 1, 0);
		for (auto& p : map) base[p.first] += p.second;
	}

	V<int> ans(n, 0);
	std::deque<PAIR> Y;
	FOR(k, 1, n + 1) {
		auto X(base);
		int ma = base.size();
		Y.clear();
		while (true) {
			int now = 0;
			RFOR(i, 1, ma) {
				if (X[i] == 0) continue;
				if (now + X[i] >= k) {
					int t = k - now;
					Y.emplace_back(i, t);
					now += t;
					break;
				}
				Y.emplace_back(i, X[i]);
				now += X[i];
			}
			if (now < k) break;
			while (!Y.empty()) {
				PAIR p = Y.front(); Y.pop_front();
				X[p.first] -= p.second;
				if(p.first > 1) X[p.first - 1] += p.second;
			}
			while (ma >= 1 && X[ma - 1] == 0) --ma;
			++ans[k - 1];
		}
		if (ans[k - 1] == 0) break;
	}
	REP(i, n) {
		OUT(ans[i])BR;
	}

	return 0;
}

