int solve(int k) {
	int ret = 0;
	int pre = 0;
	rep(i,0,sz(B)) {
		int here = B[i];
		if(here > pre) {
			ret += (here - pre) * ((sz(B)-i)/k);
			pre = here;
		}
	}
	return ret;
}

