    if (xnum[i]<t){
      for(int j=xnum[i];j<t;j++){
        ynum[j]=i;
      }
      t=xnum[i];
    }
  }

  if (0<t){
    for(int j=0;j<t;j++){
      ynum[j]=n;
    }
  }


  vector<int> ans(n);
  int leftuse=0;//穴埋めに自由に使える面積
