  int s=0;//顕さんに使う面積
  for (int i = n-1; i >=0; i--)
  {
    for(;;){
      if (h==n){
        break;
      }

      if ( (i+1)*h <= s+leftuse ){
        s+=min(ynum[h],i+1);
        h++;
      }else{
        break;
      }
    }

    ans[i]=h-1;

    s-=min(xnum[i],h);
    leftuse+=xnum[i];
  }
  ans[0]=n;
  REP(i,n){
    cout<<ans[i]<<endl;
  }
  return 0;
}

