typedef struct node{
  int key;
  int freq; 
  int priority;
  struct node *left;
  struct node *right;
}node;


node *Delete(node **,int);
node *_delete(node **,int);

int find(node *p,int x){
  while(p!=NULL){
    if(p->key == x)return 1;
    else if(p->key > x)p=p->left;
    else p=p->right;
  }

  return 0;  
}

void inorder(node *p){

  if(p->left!=NULL)inorder(p->left);

  printf(" %d(%d)",p->key,p->freq);

  if(p->right!=NULL)inorder(p->right);

  return;

}

int freq_postorder(node *p, int *A, int point){
  if(p->left!=NULL) point = freq_postorder(p->left,A,point);
  if(p->right!=NULL) point = freq_postorder(p->right,A,point);
  A[point]=p->freq;
  point++;	  
  return point;
}

node *makenode(int x, int y){
  node *newnode=(node *)malloc(sizeof(node));
  newnode->key = x;
  newnode->freq = 1;
  newnode->priority = y;
  newnode->left = NULL;
  newnode->right = NULL;
  return newnode;
}

node *rightRotate(node *p){
  node *q=p->left;
  p->left=q->right;
  q->right=p;

  return q;
}

node *leftRotate(node *p){
  node *q=p->right;
  p->right=q->left;
  q->left=p;
  return q;
}


node* insert(node **t,int key, int priority){
  node *newnode;

  if((*t)==NULL)
    return newnode=makenode(key,priority);
  if ((*t)->key==key)
    return *t;

  if(key < (*t)->key){
    (*t)->left=insert(&(*t)->left,key,priority);
    if((*t)->priority < (*t)->left->priority)
      (*t)=rightRotate((*t));
  }
  else if(key > (*t)->key){
    (*t)->right=insert(&(*t)->right,key,priority);
    if((*t)->priority < (*t)->right->priority)
      (*t)=leftRotate((*t));
  }else{
    (*t)->freq++;
  }

  return *t;
}


node *Delete(node **t,int key){
  if((*t)==NULL)
    return NULL;

  if(key < (*t)->key)
    (*t)->left=Delete(&((*t)->left),key);

  else if(key > (*t)->key)
    (*t)->right=Delete(&((*t)->right),key);

  else return _delete(t,key);

  return *t;
}

node *_delete(node **t,int key){
  if((*t)->left==NULL && (*t)->right==NULL)
    return NULL;
  else if((*t)->left==NULL)
    (*t)=leftRotate(*t);
  else if((*t)->right==NULL)
    (*t)=rightRotate(*t);
  else {
    if((*t)->left->priority > (*t)->right->priority)
      (*t)=rightRotate(*t);
    else
      (*t)=leftRotate(*t);
  }
  return Delete(t,key);
}


