struct Scanner {
    FILE* fp = nullptr;
    char line[1<<15];
    size_t st = 0, ed = 0;
    void reread() {
        memmove(line, line + st, ed - st);
        ed -= st;
        st = 0;            
        ed += fread(line + ed, 1, (1<<15) - ed, fp);
    }
    // read token (only use for small token <= 50 bytes)
    pair<char*, size_t> token() {
        while (st != ed && isspace(line[st])) st++;
        if (ed - st <= 50) reread();
        size_t sz = 1;
        while (st + sz < ed && !isspace(line[st + sz])) sz++;
        assert(st + sz < ed);
        pair<char*, size_t> res = {line + st, sz};
        st += sz;
        return res;
    }
    template <class T, enable_if_t<is_integral<T>::value, int> = 0>
    bool read_single(T& ref) {
        char* ptr;
        size_t sz;
        tie(ptr, sz) = token();
        bool neg = false;
        if (ptr[0] == '-') {
            neg = true;
            ptr++; sz--;
        }
        ref = T(0);
        for (size_t i = 0; i < sz; i++) {
            ref = 10 * ref + (ptr[i] - '0');
        }
        if (neg) ref = -ref;
        return true;
    }
    Scanner(FILE* _fp) : fp(_fp) {}
};

