    for (int k = 1; k <= n; k++) {
        int lw = 0, up = n + 1;
        while (up - lw > 1) {
            int md = (lw + up) / 2;
            int idx = lower_bound(freq.begin(), freq.end(), md) - freq.begin();
            int u = fsm[idx] + (n - idx) * md;
            if (u >= ll(md) * k) lw = md;
