class fenwick {
	vector<int> t;

	public:

		fenwick(int n) {
			t.resize(n + 1);
		}

		void add(int p, int d) {
			for(; p < (int)t.size(); p += p & -p) {
				t[p] += d;
			}
		}

		int query(int p) {
			int ret = 0;

			for(; p; p -= p & -p) {
				ret += t[p];
			}

			return ret;
		}
};

int main() {
