	for(int i = 0; i < n; ++i) {
		int x;
		cin >> x;
		--x;

		++cnt[x];
	}

	fenwick fenwick(n);

	for(int i = 0; i < n; ++i) {
		if(cnt[i] > 0) {
			fenwick.add(cnt[i], 1);
		}
	}

	for(int i = 1; i <= n; ++i) {
		int ans = 0;
		int lim = n / i + 1;

		for(int j = 1; j * lim <= n; ++j) {
			ans += j * (fenwick.query(min((j + 1) * lim - 1, n)) - fenwick.query(j * lim - 1));
		}

		cout << n / i - max(0, ans - n % i) << '\n';

	}
	return 0;

}

