int main(){
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    vector<int> cnt(n + 2, 0);
    int now = - 1;
    int tmp = 0;
    for (int i = 0; i < n; i++){
        if (a[i] != now){
            now = a[i];
            tmp = 1;
        }
        else tmp++;
        cnt[tmp]++;
    }
    int ans, x, y, z, s, t;
    for (int i = 1; i <= n; i++){
        ans = 0; tmp = 0;
        x = 0; y = 0; z = 0;
        s = 0; t = 0;
        for (int j = 1; j <= n; j++){
            //独立なもの + cnt[j]がi未満だったら終わり
            if (x + cnt[j] < i) break;
            //まず、独立なものを使う
            s = (x + cnt[j]) / i;
            ans += s;
            //使ったもののうち、cnt[j]をめいいっぱい使ったと仮定してxとcnt(tmp)を更新
            x = min(x, (x + cnt[j]) % i);
            tmp = max(0, cnt[j] - s * i);
            //このとき使えるyはさっきの計算で減った分まで
            t = (tmp + min(cnt[j] - tmp, y) + x) / i;
            ans += t;
            //xとcnt(tmp)を更新
            x = min(x, (tmp + min(cnt[j] - tmp, y) + x) % i);
            tmp = max(0, tmp + min(cnt[j] - tmp, y) - t * i);
            //独立なもの
            z = x;
            x = min(tmp, cnt[j] - cnt[j + 1]);
            //独立でないもの
            y = tmp - x;
            x += z;
        }
        cout << ans << endl;
    }
}

