            //c.clear();
            break;
        }else{
            //count++;
            for (int i = 0; i < k; ++i){
                pop_heap(c.begin(), c.end());
                v[i] = c.back();
                c.pop_back();
            }
            int diff = 1;
            if (v.back() > c.front()){
                diff = v.back() - c.front()+1;
            }
            for (int i = 0; i < k; ++i){
                v[i] -= diff;
                if (v[i] > 0){
                    c.push_back(v[i]);
                    push_heap(c.begin(), c.end());
                }
            }
            count += diff;
        }
    }
    return count;
