    return a ? 32 - __builtin_clz(a) : 0;
  }

  void push(uint key) {
    ++size;
    v[getbit(key ^ last)].emplace_back(key);
  }

  uint pop() {
    if(v[0].empty()) {
      int idx = 1;
      while(v[idx].empty()) ++idx;
      last = *min_element(begin(v[idx]), end(v[idx]));
      for(auto &p : v[idx]) v[getbit(p ^ last)].emplace_back(p);
      v[idx].clear();
    }
    --size;
    auto ret = v[0].back();
    v[0].pop_back();
    return ret;
  }
};


int main() {
  int N;
  cin >> N;
  vector< int > A(N);
  cin >> A;

  map< int, int > mp;
  for(auto &a : A) mp[a]++;

  const int S = 1010101;

  auto beet = [&](int sz) {


    RadixHeap< int > que;
    for(auto &p : mp) que.push(-p.second + S);
    int ret = 0;
    while(que.size >= sz) {
      ++ret;
      vector< int > nxt(sz);
      for(int i = 0; i < sz; i++) {
        int p = -(int) que.pop() + S;
        --p;
        nxt[i] = p;
      }
      for(int i = 0; i < sz; i++) {
        if(nxt[i] > 0) que.push(-nxt[i] + S);
      }
    }
    return ret;
  };

  vector< int > ans(N + 1);
  ans[1] = beet(1);
  ans[N] = beet(N);
  auto rec = MFP([&](auto rec, int l, int r) -> void {
    while(l < r && ans[l] == ans[r]) ans[++l] = ans[r];
    if(r - l <= 1) return;
    int mid = (l + r) >> 1;
    ans[mid] = beet(mid);
    rec(l, mid);
    rec(mid, r);
  });
  rec(1, N);
  for(int i = 1; i <= N; i++) cout << ans[i] << "\n";
}

