ll f(ll x) {
  ll pos = lower_bound(freq, freq + n, x) - freq;
  ll sum = x * (n - pos);
  if (0 <= pos - 1 and pos - 1 < n) {
    sum += ac[pos - 1];
  }
  return sum;
}

bool predicate(ll med, ll y) {
  return !(med * y <= f(med));
}

ll bs(ll lo, ll hi, ll y, ll back = 0) {
  if ( predicate(lo, y)) return lo - back;
  if (!predicate(hi, y)) return hi + 1 - back;
  while (hi - lo > 1) {
    ll med = lo + (hi - lo) / 2;
    if (predicate(med, y)) hi = med;
    else lo = med;
  }
  return hi - back;
}

