    vector<int> B(N, 0);
    B[0] = gb[0].second;
    REP(i, N) B[i + 1] = gb[i + 1].second - gb[i].second;

    CumulativeSum<ll> acc(N);
    REP(i, N) acc.add(i, B[i]);
    acc.build();

    // debug(A);
    // debug(B);

    for (int k = 1; k <= NN; ++k) {
        ll res = 0;
        for (int i = N / k; i > 0; --i) {
            int until = N - k * i;
            res += acc.query(until);
        }
        cout << res << endl;
    }

}

