void go (int l, int r, int L, int R) {
	if (l > r) return ;
	if (L == R) {
		for (int i = l; i <= r; i ++)
			ans[i] = L;
		return ;
	}

	int m = (l + r) >> 1;
	ans[m] = get(m);
	go (l, m - 1, m, R);
	go (m + 1, r, L, m);
}

