const int MAXN = 300000;

struct BIT
{
	vector<int> tree;

	BIT() : tree(MAXN + 1) {}

	void upd(int idx, int delta)
	{
		for (int i = idx; i <= MAXN; i += LSB(i))
			tree[i] += delta;
	}

	int qry(int idx)
	{
		int ret = 0;

		for (int i = idx; i != 0; i -= LSB(i))
			ret += tree[i];

		return ret;
	}
} fw1, fw2;

int get_ans(int k, int l, int r)
{
	while (r - l != 1)
	{
		int m = l + r >> 1;

		int tmp = fw2.qry(m) + m * (fw1.qry(MAXN) - fw1.qry(m));

		if (k * m <= tmp)
			l = m;
		else
			r = m;
	}

	return l;
}

