        break;
      }
      ret++;
      for(auto &p : nxt) {
        p.first--;
        if(v.first < p.first && v.second) {
          que.emplace(v);
          v.second = 0;
        }
        if(p.first > 0) {
          que.emplace(p.first, p.second);
        }
      }
      if(v.second) {
        que.emplace(v);
      }
    }
    return ret;
  };


