ll solve(int k, map<int,int> freq) {
    ll res = 0;
    priority_queue<int> pq;
    for (auto p: freq) {
	pq.push(p.second);
    }

    while ((int)pq.size() >= k) {
	res++;
	vector<int> w;
	for (int i=0; i<k; i++) {
	    w.push_back(pq.top()); pq.pop();
	}
	for (int x: w) {
	    if (x>1) {
		pq.push(x-1);
	    }
	}
    }
    return res;
}


