    for (int i = 1; i <= N; i++) {
        if (A[i])
            C.push_back(A[i]);
    }
    sort(C.begin(), C.end());

    vector<pair<int,int>> group;
    for (auto x : C) {
        if (group.empty() || group.back().first != x)
            group.emplace_back(x, 1);
        else
            ++group.back().second;          
    }
    sort(group.begin(), group.end());

    cout << N << '\n';
    for (int K = 2; K <= N; K++) {
        int ans = 0;

        int start = 0;
        int leftN = 0;
        vector<pair<int, int>> Q;

        for (int i = 0; i < int(group.size()); ) {
            while (i < int(group.size()) && leftN < K) {
                Q.push_back(group[i]);
                leftN += group[i++].second;
            }
            if (leftN < K)
                break;

            while (!Q[start].first)
                start++;
            int x = Q[start].first;

            int size = 0;
            for (int j = start; size < K; j++) {
                int t = min(Q[j].second, K - size); 
                size += t;

                if (Q[j].second == t) {
                    Q[j].first -= x;
                } else {
                    int val = Q[j].first;
                    int cnt = Q[j].second;
                    Q.emplace_back(val - x, t);
                    Q.emplace_back(val, cnt - t);
                }
            }
            leftN -= size;
            ans += x;
        }
        cout << ans << '\n';
    }

    return 0;
}

