const int MAXN = (int)3e5 + 77;
int cnt[MAXN], n;
int a[MAXN], head = 0;

int check(int l, int r) {
	set<int> setik;

	for(int i = l; i <= r; ++i) {
		if(setik.count(a[i])) {
			return 0;
		}

		setik.insert(a[i]);
	}

	return 1;
}

void solve() {
	cin >> n;

	for(int i = 0; i < n; ++i) {
		int v = fetch<int>();
		++cnt[v];
	}

	deque<pii> Q;

	for(int i = 0; i < MAXN; ++i) {
		Q.emplace_back(i, cnt[i]);
	}

	while(!Q.empty()) {
		auto cur = Q.front(); Q.pop_front();

		if(cur.second) {
			--cur.second;
			a[head++] = cur.first;
			Q.push_back(cur);
		}
	}

#ifdef __LOCAL
	cout << "@a: ";

