template <typename T, typename Container=vector<T>> vector<pair<T,int64_t>> run_length_encode(const Container &v){
  vector<pair<T,int64_t>> ret;

  for(auto &x : v){
    if(ret.empty()) ret.push_back({x,1});
    else if(ret.back().fst == x) ++ret.back().snd;
    else ret.push_back({x,1});
  }

  return ret;
}



