void solve(const V<ll> &cntlist, const V<ll> &acum, ll csize, ll k)
{
    ll bottom = csize - k;
    ll resource = acum[bottom];

    debug_printf("---------- k=%lld\n", k);

    if (bottom < 0LL) {
        cout << 0 << endl;
        return;
    }

    ll left = bottom;
    ll right = csize - 1LL;
    ll now = (left + right) / 2LL;
    ll found = -1LL;

    for ( ; left <= right; now = (left + right) / 2LL) {
        ll sum = acum[now+2] - acum[bottom];
        ll sq = (now + 2 - bottom) * cntlist[now+1];
        ll capa = sq - sum;
        debug_printf("now+2=%lld  bottom=%lld sum=%lld sq=%lld "
                     "capa=%lld resource=%lld\n",
                     now+2, bottom, sum, sq, capa, resource);
        if (resource < capa) {
            found = now;
            right = now - 1LL;
        }
        else {
            left = now + 1LL;
        }
    }

    debug_printf("k=%lld found=%lld\n", k, found);
    assert(found >= 0LL);

    cout << 0 << endl;
#if 0
    debug_printf("---- ans %lld %lld\n", acum[found+1], found - bottom + 1LL);
    cout << acum[found+1] / (found - bottom + 1LL) << endl;
#endif
}

int _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);

    static ll cnt[300005];
    memset(cnt, 0, sizeof(cnt));
    for (auto a : alist) cnt[a]++;

    V<ll> cntlist;
    rep (i, 300005) if (cnt[i]) cntlist.pb(cnt[i]);
    sort(cntlist);
    cntlist.pb(1e13);

    V<ll> acum; acum.pb(0LL);
    ll sum = 0LL;
    for (auto cnt : cntlist) {
        sum += cnt;
        acum.pb(sum);
    }
    debug_printf("---- acum\n");
    debug_print(acum);

    ll csize = cntlist.size() - 1LL;

    srep (k, 1LL, n+1LL) solve(cntlist, acum, csize, k);

    return 0;
}

