			occ.push_back(c[i]);
		}
	}
	sort(occ.begin(), occ.end());
	int len = occ.size();
	for(int i = 1; i <= 2 * n; i++){
		pos[i] = lower_bound(occ.begin(), occ.end(), i) - occ.begin();
		if(pos[i] == len) pos[i] = 2 * len;
	}
	for(int k = 1; k <= n; k++){
		int ans = 0;
		int full_sets = 0, p = len - 1;
		while(p >= 0){
			if(p - k >= 0){
				p -= k;
				ans++;
			} else if(p - k == -1){
				full_sets++;
				p = len - pos[full_sets + 1] - 1;
				ans++;
			} else {
				int np = len - pos[full_sets + 2] - 1;
				int can = p + 1;
				int miss = k - can;
				int to = np - miss + 1;
				int lena = len - pos[full_sets + 1];
				lena -= np + 1;
				if(p < to + lena && np + 1 >= miss){
					ans++;
					full_sets++;
					if(to == 0){
						full_sets++;
						p = len - pos[full_sets + 1] - 1;
					} else {
						p = to - 1;
					}
