/*
・1次元累積和
    >     build O(N)
    > add,query O(1)
[応用例] 加減算をそれぞれXORにすると, 累積XOR
[使用例]
CumulativeSum<int> acc(N);  // 要素数Nの累積和用の配列
acc.add(k, x);              // 要素kに値xを加える
acc.build();                // 累積和を取る
acc.query(k);               // 閉区間[0, k]の和
acc.query(l, r);            // 半開区間[l, r)の和
acc[k];                     // 要素kを取得
*/

template<typename T = int_fast64_t> struct CumulativeSum {
    vector< T > data;
    CumulativeSum(int sz, T init = 0) : data(sz, init) {}
    void add(int k, T x) {
        data[k] += x;
        // data[k] ^= x;
    }
    void build() {
        for (int i = 1; i < (int)data.size(); ++i) {
            data[i] += data[i - 1];
            // data[i] ^= data[i - 1];
        }
    }
    T query(int k) {
        if (k < 0) return 0;
        return data[min(k, (int)data.size() - 1)];
    }
    T query(int l, int r) {
        T ret = (data[min(r - 1, (int)data.size() - 1)]);
        if (l > 0) ret -= (data[min(l - 1, (int)data.size() - 1)]);
        // if (l > 0) ret ^= (data[min(l - 1, (int)data.size() - 1)]);
        return ret;
    }
    T operator[](const int &k) {
        return data[k];
    }
    void debug() {
        for (int i = 0; i < (int)data.size(); ++i) cerr << data[i] << ' ';
        cerr << endl;
    }
};

/*
・ランレングス圧縮
[備考] stringについて用いる場合は, vector<char>に以下のようにして一旦移し替える.
      string str;
      vector<char> vec(str.begin(), str.end());
[使用例]
vector<int> vec = {1, 5, 5, 7, 7, 7, 7};
auto gb = groupby(vec);     // {{1, 1}, {5, 2}, {7, 4}}
[蛇足] 命名はPythonに準拠
*/

template<typename T> vector< pair< T, int > > groupby(const vector< T > &vec) {
    vector< pair< T, int > > ret;
    int piv = -1;
    for (auto &e: vec) {
        if (piv == -1 or ret[piv].first != e) ++piv, ret.emplace_back(make_pair(e, 1));
        else ++(ret[piv].second);
    }
    return ret;
}

signed main() {

    SS(int, NN);
    SV(int, A, NN);
    SORT(A);

    auto gb = groupby(A);
    int N = gb.size();

    vector<int> C(N, 0);
    REP(i, N) C[i] = gb[i].second;
    SORT(C);

    vector<int> B(N, 0);
    B[0] = C[0];
    REP(i, N - 1) B[i + 1] = C[i + 1] - C[i];

    CumulativeSum<ll> acc(N);
    REP(i, N) acc.add(i, B[i]);
    acc.build();

    // debug(A);
    // debug(B);

    for (int k = 1; k <= NN; ++k) {
        ll res = 0;
        for (int i = N / k; i > 0; --i) {
            int until = N - k * i;
            res += acc.query(until);
        }
        cout << res << endl;
    }

}

