int main() {
    int n;
    scanf("%d", &n);

    vector<int> a(n);

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    sort(a.begin(), a.end());

    vector<int> count_vector;

    int count = 1;
    int prev_num = -1;
    int cur_num;


    for (int i = 0; i < n; i++) {
        cur_num = a[i];
        if (prev_num == cur_num) {
            count++;
        } else {
            if (i != 0) {
                count_vector.push_back(count);
                count = 1;
            }
        }
        prev_num = cur_num;
    }
    count_vector.push_back(count);

    priority_queue<int> q;
    for (int i = 0; i < count_vector.size(); i++) {
        q.push(count_vector[i]);
    }

    vector<int> out;

    for (int i = 1; i <= n; i++) {
        if (i==1) {
            out.push_back(n);
            continue;
        }
        priority_queue<int> q_cp = q;
        vector<int> shelter;

        int eat_count = 0;
        while (q_cp.size() >= i) {
            for (int j = 0; j < i; j++) {
                int top = q_cp.top();
                if (top != 1) {
                    shelter.push_back(top-1);
                }
                q_cp.pop();
            }
            int shelter_size = shelter.size();
            for (int j = 0; j < shelter_size; j++) {
                q_cp.push(shelter.back());
                shelter.pop_back();
            }
            eat_count++;
        }
        out.push_back(eat_count);

    }

    for (int i = 0; i < n; i++) {
        printf("%d\n", out[i]);
    }

}

