const int N = 3e5 + 5;

int n, k, a[N], c[N], cnt[N];
std::vector<std::pair<int, int>> f, g;

int solve(int k) {
    int res = 0;
    f = g;
    while (true) {
        int p = -1, now = k;
        for (int i = (int) f.size() - 1; i >= 0; i--) {
            if (now - f[i].second <= 0) {
                p = i; break;
            } else {
                now -= f[i].second;
            }
        }
        if (p == -1) { break; }
        res++;
        for (int i = p + 1; i < f.size(); i++) {
            f[i].first--;
        }
        if (f[p].first == 1) {
            f[p].second -= now;
        } else if (p > 0 && f[p].first - 1 == f[p - 1].first) {
            f[p - 1].second += now; f[p].second -= now;
        } else {
            f[p].second -= now;
            f.insert(f.begin() + p, {f[p].first - 1, now});
        }
    }
    return res;
}

