    n = read();
    for (int i = 0; i < n; i++) { a[i] = read(); c[a[i]]++; }
    for (int i = 1; i <= n; i++) { cnt[c[i]]++; }
    for (int i = 1; i <= n; i++) {
        if (cnt[i] >= 1) { g.push_back({i, cnt[i]}); }
    }
    for (int i = 1; i <= n; i++) {
        printf("%d\n", solve(i));
    }
    return 0;
}

