#define SZ(x) ((int)(x).size())
#define ALL(x) (x).begin(),(x).end()

#define FOR(i,a,b) for(int i=(int)(a);i<(int)(b);i++)
#define REP(i,x) for(int i=0;i<(int)(x);i++)
#define REPS(i,x) for(int i=1;i<=(int)(x);i++)
#define RREP(i,x) for(int i=((int)(x)-1);i>=0;i--)
#define RREPS(i,x) for(int i=((int)(x));i>0;i--)

typedef pair<int, int> pint;

#define mp make_pair
#define mt make_tuple
#define pb push_back
#define pf push_front

#define MOD (1000 * 1000 * 1000 + 7)

int solve(vector<int> m, int N, int K, int MAX) {
    if (K == 1) return N;

    int ans = 0;

    while (true) {
        int cnt = 0;
        vector<pair<int, int>> a;
        int MIN;
        int NOW_MAX = 0;

        int use_count = 0;
        // cerr << "MAX = " << MAX << endl;
        RREPS(i, MAX) {
            int l = m[i];
            if (l == 0) continue;

            a.pb(mp(i, l));
            cnt += l;
            MIN = i;
            NOW_MAX = max(NOW_MAX, i);

            if (cnt >= K) {
                int CCC = cnt / K;

                use_count = i;

                ans += use_count * CCC;

                int remain = cnt - K * CCC;
                int M = SZ(a);
                RREP(j, M) {
                    int n = a[j].second - remain;
                    m[a[j].first] -= n;
                    m[a[j].first - use_count] += n;

                    remain = 0;
                }

                break;
            }
        }

        MAX = max(MIN, NOW_MAX - use_count);

        if (N - (m[0]) < K) break;
    }

    return ans;
}

signed main() {
    int N;
    cin >> N;

    vector<int> A(N);
    REP(i, N) {
        cin >> A[i];
        A[i]--;
    }

    vector<int> cnt(N, 0);
    REP(i, N) {
        cnt[A[i]]++;
    }

    int MAX = 0;
    REP(i, N) {
        MAX = max(MAX, cnt[i]);
    }

    vector<int> m(MAX+1, 0);
    int kind = 0;
    REP(i, N) {
        m[cnt[i]]++;
        if (cnt[i] > 0) kind++;
    }

    REP(i, N) {
        int ans = 0;

        if (i <= kind) {
            ans = solve(m, N, i+1, MAX);
        }

        cout << ans << endl;
    }

    return 0;
}

