{
    int m = prec.size();

    int l = 0;
    int r = n/k;
    int mid;
    int req;
    int idx;
    int tot, rem;
    while(l!=r)
    {
        mid = l+r+1;
        mid/=2;

        req = mid*k;
        idx = upper_bound(coun.begin(),coun.end(),mid)-coun.begin();
        idx--;
