int solve(){
    // vector<int> C(N+1,0);
    map<int,int> Cnt;
    vector<int> C,D,kD,sumD;
    for (int i = 0; i < N; i++) Cnt[A[i]]++;
    for(auto cnt:Cnt) C.push_back(cnt.second);
    sort(C.begin(),C.end());
    D.assign(N,0);
    for (int i = 0; i < N; i++) D[C[i]]++;
    sumD.assign(N+1,0),kD.assign(N+1,0);
    for (int i = 0; i < N; i++) {
        sumD[i+1] = sumD[i]+D[i];
        kD[i+1] = kD[i]+i*D[i];
    }
    auto f = [&](int x){
        return (kD[x]+x*(sumD[N]-sumD[x]))/x;
    };
    // DBG(C)
    // DBG(D)
    // DBG(kD)
    // DBG(sumD)
    int L = C.size();
    for (int k = 1; k <= N; k++)
    {
        if(k==1) {cout << N << "\n"; continue;}
        if(k>L) {cout << 0 << "\n"; continue;}

        int ok=0,ng=N+1;
        while(ng-ok>1){
            int mid=(ok+ng)/2;
            if(f(mid)>=k) ok=mid;
            else ng=mid;
        }        
        cout << ok << "\n";
    }

    return 0;
}

