    for (int i = 0; i < N; i++) {
      sum[i + 1] = sum[i] + g[i];
      mx[i + 1] = max(mx[i], g[i]);
    }
    vector<int> id(N);
    iota(id.begin(), id.end(), 1);
    sort(id.begin(), id.end(), [&](int a, int b) {
      double ra = 1.0 * sum[a] / mx[a];
