    for (int k = 1; k <= n; ++k) {
        int l = 0, r = n / k + 1; // l:OK, r:NG
        while (l + 1 < r) {
            int c = (l + r) / 2;
            bool ok = [&](int c) {
                int i = lower_bound(ALL(a), c) - a.begin();
                int sum = c * (n - i) + s[i];
                return (sum >= c * k);
            }(c);
            if (ok) l = c; else r = c;
        }
        cout << l << endl;
    }
}

