const int maxn = 600300;
int c[maxn], pos[maxn];
int main(){
	int n; cin >> n;
	for(int i = 0; i < n; i++){
		int x; cin >> x;
		c[x]++;
	}
	vector<int> occ;
	for(int i = 0; i < maxn; i++){
		if(c[i]){
			occ.push_back(c[i]);
		}
	}
	sort(occ.begin(), occ.end());
	for(int i = 1; i <= 2 * n; i++){
		pos[i] = lower_bound(occ.begin(), occ.end(), i) - occ.begin();
	}
	int len = occ.size();
	for(int k = 1; k <= n; k++){
		int ans = 0;
		int full_sets = 0, p = 0;
		while(p < len){
			if(p + k < len){
				p += k;
				ans++;
			} else if(p + k == len){
				full_sets++;
				p = pos[full_sets + 1];
				ans++;
			} else {
				int np = pos[full_sets + 2];
				int can = len - p;
				int miss = k - can;
				int to = np + miss - 1;
				if(to < p){
					p = to + 1;
					ans++;
					full_sets++;
				} else {
					break;
				}
			}
		}
		cout << ans << "\n";
	}
	return 0;
}

