void floyd(int n, int li){

    for (int k = 0; k < n; k++){
        for (int i = 0; i < n; i++){
            for (int j = 0; j < n; j++){
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }

    for (int i=0; i<n; i++){
        for (int j=0; j<n;j++){
            if (dist[i][j] <= li) fuel[i][j] = 1;
        }
    }

    for (int k = 0; k < n; k++){
        for (int i = 0; i < n; i++){
            for (int j = 0; j < n; j++){
                fuel[i][j] = min(fuel[i][j], fuel[i][k] + fuel[k][j]);
            }
        }
    }
}

void init(int n){
    for (int i=0; i<n; i++){
        for (int j=0; j<n; j++){
            fuel[i][j] = dist[i][j] = oo;
        }
        fuel[i][i] = dist[i][i] = 0;
    }
}

