typedef pair<int, int> P;

struct CompareF {
constexpr bool operator()(const P& x, const P& y) const noexcept
{ return x.first > y.first; }
};

void Main() {
	int N; cin >> N;
	vector<int> A(N);
	map<int, int> mp;
	REP(i,N) {
		cin >> A[i];
		mp[A[i]]++;
	}
	priority_queue<P, vector<P>, CompareF> que;
	FOR(i, 1, N + 1) {
		for (auto p : mp) {
			que.push(make_pair(p.second, p.first));
		}
		int res = 0;
		while(!que.empty()) {
			bool flg = false;
			vector<P> tmp_v;
			REP(j, i) {
				if (que.empty()) {
					flg = true;
					break;
				}
				P p = que.top(); que.pop();
				tmp_v.push_back(p);
			}
			if (flg) break;
			++res;
			for (P _p : tmp_v) {
				if (_p.first <= 1) continue;
				que.push(make_pair(_p.first - 1, _p.second));
			}
			tmp_v.clear();
		}
		cout << res << endl;
	}
}

