auto quatients(int n) {
  std::vector< std::pair< int, int > > ret;
  auto i = 1;
  while (true) {
    auto j = n / i;
    ret.emplace_back(i, j);
    if (j == 1) break;
    i = n / (n / (i + 1));
  }
  return ret;
}

