    int nodef(const int& lhs,const int& rhs)const{return std::min(lhs,rhs);}
public:
    RMiQ(int size, const int& def = 0) :kaageSegTree<int>(size, def, inf) {}
    RMiQ(const std::vector<int>& initvec) :kaageSegTree<int>(initvec, inf) {}
};
