{
	int sum=0;
	for(int i=1;i<=u;++i)
	{
		if(b[i]>=x)
		{
			sum+=x;
		}
		else
		{
			sum+=b[i];
		}
	}
	if(sum>=k*x) return 1;
	else return 0;
