  for (int i = c_size - 2; 0 <= i; i--)
  {
    LEN[i] = (C[i] == C[i + 1] ? LEN[i + 1] + 1 : 1);
  }

  cout << N << endl;
  for (int K = 2; K <= N; K++)
  {
    int remain = N;
    int k = K;
    int count = N / K;
    for (int c = 0; c < c_size;)
    {
      if (k == 1)
      {
        break;
      }
      if (C[c] <= count)
      {
        break;
      }
      if (c_size - c < k)
      {
        count = 0;
        break;
      }

      remain -= C[c] * LEN[c];
      k -= LEN[c];
      count = min(count, remain / k);
      if (count <= 1)
      {
        break;
      }
      c += LEN[c];
    }
    cout << count << endl;
  }
  return 0;
}

