  sort(begin(uku), end(uku));

  auto beet = [&](int sz) {
    queue< int > in;
    int ret = 0;
    for(int i : uku) {
      in.emplace(ret + i);
      while(in.size() && in.front() == ret) in.pop();
      if(in.size() == sz) ret += in.front() - ret;
    }
    return ret;
  };

