    a--;
    cnt[a]++;
  }
  // s[x] = \sum_{i=0}^{n-1} min(cnt[i],x)
  vector<ll> s(n + 1, 0);
  // s[x+1] = s[x] + (x<cnt[p]を満たすpの個数)
  sort(ALL(cnt));
  REP(x, n) {
    auto it = lower_bound(ALL(cnt), x + 1);
    ll diff = cnt.end() - it;
    s[x + 1] = s[x] + diff;
  }
  FOR(t, 1, n + 1) {
    ll ok = 0, ng = n + 1;
    while (ok + 1 < ng) {
      ll x = (ok + ng) / 2;
      if (t * x <= s[x])
        ok = x;
      else
        ng = x;
    }
    cout << ok << endl;
  }
}

