int calc(int n, int k) {
    int ok = 0, ng = n+1;
    int cnt = 0;
    while(ng-ok > 1) {
        ++cnt;
        if(cnt > 10) break;
        int mid = (ok+ng) / 2;

        int max_length = (k_argcnt[mid] + mid * (argcnt[n] - argcnt[mid])) / mid;
        if(max_length >= k) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    return ok;
}

