int main() {
  int N;
  cin >> N;
  vector< int > A(N);
  cin >> A;


  map< int, int > mp;
  for(auto &a : A) mp[a]++;
  map< int, int > uku;
  for(auto &a : mp) uku[a.second]++;


  auto beet = [&](int sz) {
    stack< pair< int, int > > que;
    for(auto &p : uku) que.emplace(p);
    int ret = 0;

    while(que.size()) {
      vector< pair< int, int > > nxt;
      int add = 0;
      while(que.size() && add < sz) {
        auto p = que.top();
        que.pop();
        add += p.second;
        nxt.emplace_back(p);
      }
      auto v = nxt.back();
      v.second = 0;
      if(add > sz) {
        v.second = add - sz;
        nxt.back().second -= add - sz;
      }
      if(add < sz) {
        break;
      }
      ret++;
      for(auto &p : nxt) {
        p.first--;
        if(v.first < p.first && v.second) {
          que.emplace(v);
          v.second = 0;
        }
        if(p.first > 0) {
          que.emplace(p.first, p.second);
        }
      }
      if(v.second) {
        que.emplace(v);
      }
    }
    return ret;
  };


  vector< int > ans(N + 1);
  ans[1] = beet(1);
  ans[N] = beet(N);
  auto rec = MFP([&](auto rec, int l, int r) -> void {
    //while(l < r && ans[l] == ans[r]) ans[++l] = ans[r];
    if(r - l <= 1) return;
    int mid = (l + r) >> 1;
    ans[mid] = beet(mid);
    rec(l, mid);
    rec(mid, r);
  });
  rec(1, N);
  for(int i = 1; i <= N; i++) cout << ans[i] << "\n";
}

