int main() {
    // 貪欲法では間に合わないので使い回す、
    // segtree、累積和を使えばsegtreeいらない
    int N;
    cin >> N;
    vector<int> A(N);
    rep(i, N) {
        int x;
        cin >> x;
        A[--x]++;
    }
    vector<int> B;
    for (int a : A) {
        B.push_back(a);
    }
    sort(B.begin(), B.end());
    B.erase(remove(B.begin(), B.end(), 0), B.end());
    vector<int> Bcum(sz(B)+1);
    int length = sz(B);
    for (int i = 0; i < length; i++) {
        Bcum[i+1] = B[i] + Bcum[i];
    }
    for (int i = 1; i <= N; i++) {
        // 最大の回数
        int time = N / i;
        if (i > length) {
            cout << 0 << '\n';
            continue;
        }
        int ind = (lower_bound(B.begin(), B.end(), time+1) - B.begin()); // time以下の一番右のindex+1
        int ans = Bcum[ind];
        ans += time * (length - ind);
        ans /= i;
        cout << ans << '\n';
    }
    return 0;
}

