template <typename T, class Operator, class Substitute>
struct SegTree
{
	vector<T> tree;
	Operator op;
	Substitute sub;
	int s;
	T def;
	SegTree(int size,T d)
	{
		def=d;
		s=size;
		tree.resize(4*size,def);
	}

	void add(int pos, T value)
	{
		add(pos,value,0,s,0);
	}

	// [low, hi) は全体の範囲
	void add(int pos, T value, int low, int hi, int i)
	{
		if(low+1==hi){
			tree[i]=sub(tree[i],value);
		}
		else if(low+1<hi){
			int mid=(low+hi)/2;
			if(pos<mid){
				add(pos,value,low,mid,2*i+1);
			}
			else{
				add(pos,value,mid,hi,2*i+2);
			}
			tree[i]=op(tree[2*i+1],tree[2*i+2]);
		}
	}

	// [a,b) を取得
	T get(int a, int b)
	{
		return get(a,b,0,s,0);
	}

	T get(int a, int b, int low, int hi, int i)
	{
		if(hi<=a||b<=low||hi<=low){
			return def;
		}
		if(a<=low&&hi<=b){
			return tree[i];
		}
		int mid=(low+hi)/2;
		return op(get(a,b,low,mid,2*i+1),get(a,b,mid,hi,2*i+2));
	}
