void solve() {
  int n; cin >> n;
  vi arr(n);
  rep(i,n) cin >> arr[i];
  unordered_map<int, int> cards;
  rep(i,n) ++cards[arr[i]];
  map<int, int> numbers;
  for (auto &p : cards) ++numbers[p.second];
  int Kmax = cards.size();
  int Kmin = n / (*numbers.rbegin()).first;
  for (int i=1; i<=Kmin; ++i) {
    cout << n / i << "\n";
  }
  vi ans(Kmax-Kmin);
  int res = 0;
  for (int i=Kmax; i>Kmin; --i) {
    int num, cnt;
    auto itr = numbers.begin();
    tie(num, cnt) = *itr;
    int tmp = res;
    while (++itr != numbers.end()) {
      int newnum, newcnt;
      tie(newnum, newcnt) = *itr;
      if ((newnum-num)*cnt >= tmp) {
        num += tmp / cnt;
        break;
      }
      tmp -= (newnum-num)*cnt;
      num = newnum;
      cnt += newcnt;
    }
    ans[i-1-Kmin] = num;
    num = (*numbers.begin()).first;
    res += num;
    if (--numbers[num] == 0) numbers.erase(num);
  }
  for (auto v : ans) cout << v << "\n";
  for (int i=Kmax+1; i<=n; ++i) {
    cout << 0 << "\n";
  }
}


