LL Big_Mod (int b, int p, int M)
{
    if (p==0) return 1LL;
    if (p%2==0) {
        LL x=Big_Mod(b, p/2, M);
        return (x*x)%M;
    }
    else return (b%M * Big_Mod(b, p-1, M))%M;
}

