		int l=1,r=n;
		//cout << i << endl;
		while (l<=r)
		{
			int mid=(l+r)>>1;
			if (chk(i,mid)) {ans[i]=mid;l=mid+1;}
			else r=mid-1;
		}
	}
	rep(i,1,n) printf("%d\n",ans[i]);
	return 0;
}

