        m[v[i]]++;
    }
    vector<int> occ;
    for (auto u : m) {
        occ.push_back(u.second);
    }
    sort(all(occ));
    reverse(all(occ));
    priority_queue<pair<pair<int, int>, int>> pq;
    for (int i = 0; i < (int) occ.size(); ++i) {
        pq.emplace(make_pair(n, occ[i]), i);
    }
    vector<int> lol;
    vector<int> k;
    while (!pq.empty()) {
        auto u = pq.top();
        int x = min<int>(lol.size() + u.F.F, n);
        k.push_back(x);
        lol.push_back(u.S);
        pq.pop();
        if (--u.F.S != 0) {
            pq.emplace(make_pair(-(lol.size() - 1), u.F.S), u.S);
        }
    }
    vector<int> fst(n, -1);
    for (int i = 0; i < (int)k.size(); ++i) {
        if (fst[k[i]-  1] == -1) {
            fst[k[i] - 1] = i;
        }
    }
    for (int i = 1; i < n; ++i) {
        if (fst[i] == -1) fst[i] = fst[i - 1];
        else if (fst[i - 1] != -1 && fst[i - 1] < fst[i]) fst[i] = fst[i - 1];
    }
