int main() {
    int n;
    cin >> n;
    map<int, int> ma;
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        ma[a]++;
    }

    vector<int> c_count(n + 1);
    for (auto x:ma)c_count[x.second]++;
    for (int i = 1; i <= n; i++)c_count[i] += c_count[i - 1];

    vector<int> v(n + 1);
    for (auto x:ma)v[x.second] += x.second;
    for (int i = 1; i <= n; i++)v[i] += v[i - 1];

    for (int i = 1; i <= n; i++) {
        int ok = 0;
        int ng = n / i + 1;
        while (abs(ok - ng) > 1) {
            int mid = ng + (ok - ng) / 2;

            int sum = (c_count[n] - c_count[mid]) * mid + v[mid];

            if (sum >= mid * i)ok = mid;
            else ng = mid;
        }

        cout << ok << endl;
    }

    return 0;
}

