constexpr int N = 3e5;
std::array<int, N + 1> A;
std::array<int, N + 1> P;
std::array<int, N + 1> res;

int main(void){
    int n; scanf("%d", &n); REP(i, n) scanf("%d", &A[i]);
    std::sort(A.begin(), A.begin() + n);
    int m = 0;
    {
        int idx = 0;
        while(idx < n){
            int cnt = 1;
            while(idx + cnt < n and A[idx] == A[idx + cnt]) cnt++;
            P[m++] = cnt;
            idx += cnt;
        }
    }
    std::sort(P.begin(), P.begin() + m);
    // k 種類選べなくなる -> その時点で k - 1 種類以下となる
    {
        int ptr = m - 1;
        int val = n;
        for(int x = n; x > 0; --x){
            int t = val / x; if(res[t] == 0) res[t] = x;
            while(ptr >= 0 and P[ptr] == x) ptr--;
            val -= (m - 1 - ptr);
        }
        for(int k = n; k > 0; --k) if(res[k - 1] < res[k]) res[k - 1] = res[k];
    }
    for(int k = 1; k <= n; ++k) printf("%d\n", res[k]);

    return 0;
}

