void for_permutation(size_t n, const std::function<void(const std::vector<size_t>&)> &f)
{
    std::vector<size_t> idx(n); iota(idx.begin(), idx.end(), 0);
    do { f(idx); } while(std::next_permutation(idx.begin(), idx.end()));
}

