void __solve()
{
    i32 n; cin>>n;
    vector<i32> a(n);
    for(i32 i=0; i<n; ++i)
    {
        i32 x; cin>>x; x--;
        a[x]++;
    }
    sort(all(a));
    vector<i32> as(n+1);
    for(i32 i=0; i<n; ++i)
    {
        as[i+1]=as[i]+a[i];
    }
    vector<i32> ii(n+1);
    for(i32 i=0,j=0; i<=n; ++i)
    {
        while(j<n and a[j]<i)
        {
            j++;
        }
        ii[i]=j;
    }
    for(i32 k=1; k<=n; ++k)
    {
