  ckd[0] = 0;
  for (int i = 1; i < N+1; i++) {
    cd[i] = cd[i-1] + ccmap[i];
    ckd[i] = ckd[i-1] + i * ccmap[i];
  }

  auto max_len_div = [&](int div) {
    return floor(float(ckd[div] + div*(cd[N] - cd[div])) / div);
  };
  for (int k = 1; k <= N; k++) {
    int l = 1, r = N;
    int res = 0;
    while (l <= r) {
      int c = (l+r)/2;
      if (max_len_div(c) >= k) {
        l = c+1;
        res = c;
      } else {
        r = c-1;
      }
    }
    cout << res << endl;
  }

  return 0;
}

