  sort(ALL(b));
  V<int> s(n+1,0);
  FOR(i,0,n) s[i+1] = s[i] + b[i];
  auto cal_ = [&](int k, int x){
    int d = b.end() - lower_bound(ALL(b), x);
    ll ret = x * d;
    ret += s[n-d];
    ret /= k;
    return ret;
  };
  auto cal = [&](int k){
    int l = 0, r = n/k + 1, m;
    while(r-l>1){
      m = (l+r)>>1;
      bool flg = ( cal_(k,m) >= m);
      if(flg) l = m;
      else r = m;
    }
    return l;
  };
  FOR(i,1,n+1){
    cout << cal(i) << '\n';
  }
}

