std::vector<int> A;
std::vector<int> P;
std::vector<int> res;

int main(void){
    int n; scanf("%d", &n);
    A.resize(n); REP(i, n) scanf("%d", &A[i]);
    std::sort(A.begin(), A.end());
    {
        int idx = 0;
        while(idx < n){
            int cnt = 1;
            while(idx + cnt < n and A[idx] == A[idx + cnt]) cnt++;
            P.push_back(cnt);
            idx += cnt;
        }
    }
    std::sort(P.begin(), P.end());
    // k 種類選べなくなる -> その時点で k - 1 種類以下となる
    const int m = P.size();
    res.assign(n + 1, 0);
    {
        int ptr = m - 1;
        int val = n;
        for(int x = n; x > 0; --x){
            int t = val / x; if(res[t] == 0) res[t] = x;
            while(ptr >= 0 and P[ptr] == x) ptr--;
            val -= (m - 1 - ptr);
        }
        for(int k = n; k > 0; --k) if(res[k - 1] < res[k]) res[k - 1] = res[k];
    }
    for(int k = 1; k <= n; ++k) printf("%d\n", res[k]);




    return 0;
}

