SINT64 ok (SINT64 num, SINT64 k) {
	SINT64 posi;
	posi = upper_bound(rdata.begin(),rdata.end(), num) - rdata.begin();
	posi = 300005-posi;

	SINT64 buf;
	if (posi != 0) {
		buf = sum[posi-1];
	} else {
		buf = 0;
	}
	if ( sum[k-1]- buf + (N - sum[k-1]) >= (k-posi)*num) {
		return 1;
	} else {
		return 0;
	}

}

