vector<int> line;

int func(int n){
	if(line.size()<n)return 0;
	int sum = 0;
	map<int, int> m;
	rep(i, n)++m[line[i]];
	for(int i=n;i<line.size();++i)sum+=line[i];
	while(sum){
		if(m.size()==1)
			return sum/(m.begin()->second)+m.begin()->first;
		pii d = *m.begin();
		m.erase(d.first);
		int add = m.begin()->first - d.first;
		add = min(sum/d.second, add);
		m[d.first+add]+=d.second;
		sum -= add * d.second;
	}
	return m.begin()->first;
}


