#include<bits/stdc++.h>
#include <array>
using namespace std;

#define rep(i, n) for(int i = 0; i < (n); i++)
using LL = long long;
using ULL = unsigned long long;

struct dist {
	unsigned n;
	vector<unsigned> d;
	bool operator<(const dist &r)const { return n > r.n; }
};

void solve() {
	unsigned n; cin >> n;
	priority_queue<dist> q;
	{
		vector<unsigned> an(n + 1);
		rep(i, n) { unsigned a; cin >> a; an[a]++; }
		rep(i, n + 1) {
			if (an[i] != 0)
				q.push({ an[i] , { an[i] } });
		}
	}

	vector<unsigned> ans(n);
	for (unsigned t = n; t > 0; t--) {
		if (q.size() < t) { ans[t - 1] = 0; continue; }
		if (q.size() == t) { ans[t - 1] = q.top().n; continue; }
		auto p = q.top(); q.pop();
		rep(i, p.d.size()) {
			auto pp = q.top(); q.pop();
			pp.d.push_back(p.d[i]); pp.n += p.d[i];
			q.push(pp);
		}
		ans[t - 1] = q.top().n;
	}
	rep(i, n) cout << ans[i] << endl;
}

int main() {

	solve();

	return 0;
}

