void solve(const V<ll> &clist, const V<ll> &sumlist, ll ceil, ll k)
{
    ll n = clist.size();

    if (k > n) {
        cout << 0<< endl;
        return;
    }

    ll resource = sumlist[n-k];

    ll left = clist[n-k];
    ll right = ceil;
    ll now = (left + right) / 2LL;
    ll ans = left;

    for ( ; left <= right; now = (left + right) / 2LL) {
        auto iter = lower_bound(ALL(clist), now);
        ll cnt = iter - (clist.begin() + n - k);
        ll idx = iter - clist.begin();
        ll nowsum = sumlist[idx] - resource;
        ll aimsum = cnt * now;
        ll need = aimsum - nowsum;
        if (need <= resource) {
            ans = max(ans, now);
            left = now + 1LL;
        }
        else {
            right = now - 1LL;
        }
    }

    cout << ans << endl;
}

