			int mab = ma;
			int ans = 0;
			bool flag;
			while (mab) {
				flag = false;
				if (s[mab] > i) {
					int plus = s[mab] / i;
					s[mab - 1] += plus * i;
					s[mab] -= plus * i;
					ans += plus;
					flag = true;
				}
				else {
					int cnt = 0;
					int memo = 0;
					for (int j = mab; j > 0; j--) {
						if (cnt + s[j] >= i) {
							s[j] += memo;
							s[j] -= i - cnt;
							s[j - 1] += i - cnt;
							mab--;
							ans++;
							flag = true;
							break;
						}
						int memo2 = s[j];
						s[j] = 0;
						s[j] += memo;
						memo = memo2;
						cnt += memo2;
					}
				}
				if (!flag)break;
			}
			cout << ans << endl;
		}
	}
}

