typedef pair<int, vector<int>> P;

struct Order
{
    bool operator()(P const& a, P const& b) const
    {
        return a.first > b.first;
    }
};

int main() {
    int N; scanf("%d", &N);
    vector<int> As(N);
    for(int i = 0; i < N; i++) {
        int a; scanf("%d", &a);
        As[i] = a;
    }
    vector<int> kazu(N, -1);
    sort(As.begin(), As.end());
    int c = 1;
    int prev = As[0];
    int p = 0;

    for(int i = 1; i < N; i++) {
        if(prev == As[i]) {
            c++;
        } else {
            kazu[p] = c;
            p++;
            c = 1;
            prev = As[i];
        }
    }
    kazu[p] = c;

    priority_queue< P, vector<P>, Order> q;
    for(int i = 0; i < N; i++) {
        if (kazu[i] == -1) {
            break;
        } else {
            P hoge; hoge.first = kazu[i]; hoge.second = {kazu[i]};
            q.push(hoge);
        }
    }
    vector<int> ans(N, 0);
    int size = q.size();
    for(int i = size-1; 0 < i; i--) {
        ans[i] = q.top().first;
        vector<int> temp = q.top().second;
        q.pop();
        for(int a: temp) {
            P hoge = q.top();
            q.pop();
            hoge.first += a;
            hoge.second.push_back(a);
            q.push(hoge);
        }
    }

    ans[0] = N;
    for(int i = 0; i < N; i++) {
        printf("%d\n", ans[i]);
    }
}

