int operations(vector<int> cards, int k) {
    int sum = 0;
    int ind = 0;
    while (true) {
        int i = ind;
        int cur = 0;
        while (true) {
            if (cards[i] == 0) i++;
            else {
                cards[i]--;
                cur++;
                if (cur == k) {
                    sum++;
                    i++;
                    if (i == cards.size()) i = 0;
                    ind = i;
                    break;
                } else i++;
            }

            if (i == cards.size()) i = 0;
            if (i == ind) break;
        }
        if (cur != k) return sum;
    }
}

