    }
  }
  int calc_bound(int l, int bound_prev) {
    int ub = n + 1;
    int lb = bound_prev;
    while (ub - lb > 1) {
      int mid = (ub + lb) / 2;
      if (calc(mid) >= l)
        lb = mid;
      else
        ub = mid;
    }
    return lb;
  }
  int calc(int k) {
    multiset<int> T = S;
    int ret = 0;
    while (1) {
      auto it = T.lower_bound(k);
      if (it == T.end()) break;
      ret++;
      int tmp = *it - k + *prev(it);
      T.erase(it);
      T.insert(tmp);
    }
    return ret;
  }
};

