// 処理内容
int main() {

    // インタラクティブ問題では除去した方がいいかも
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n; cin >> n;
    vector<ll> a(n);
    REP(i, n) cin >> a[i];

    sort(ALL_OF(a));
    auto rl = run_length(ALL_OF(a));
    sort(ALL_OF(rl), greater<ll>());
    ll rsz = rl.size();

    // REP(i, n) rl.push_back(0);


    segtree_rmq rminq(rl);
    vector<ll> rlimos(rsz+1, 0);
    REP(i, n) rlimos[i+1] = rlimos[i] + rl[i];

    vector<ll> qans(n);
    RANGE(k, 1, n) {

        ll blk = (rsz+k-1)/k;
        vector<ll> rmin(blk);
        vector<ll> yojo(blk);
        REP(i, blk) {
            ll jb = i * k;
            ll je = min(rsz, jb + k);
            ll bsum = rlimos[je] - rlimos[jb];
            rmin[i] = rminq.fetch(jb, je);
            yojo[i] = bsum - rmin[i] * k;
            if (je - jb == k) {
                qans[k-1] += max(0LL, rmin[i]);
            }
        }

        if (k == 1) continue;

        ll csz = blk;
        while (csz >= k) {

            sort(ALL_OF(yojo));

            vector<ll> crlimos(csz+1, 0);
            REP(i, csz) {
                crlimos[i+1] = crlimos[i] + yojo[i];
            }

            segtree_rmq crminq(yojo);

            ll cblk = (csz+k-1) / k;
            vector<ll> crmin(cblk);
            vector<ll> cyojo(cblk);
            REP(i, cblk) {
                ll jb = i * k;
                ll je = min(csz, jb + k);
                ll bsum = crlimos[je] - crlimos[jb];
                crmin[i] = crminq.fetch(jb, je);
                cyojo[i] = bsum - crmin[i] * k;
                if (je - jb == k) {
                    qans[k-1] += max(0LL, crmin[i]);
                }
            }

            yojo = cyojo;
            csz = cblk;
        }

    }

    REP(i, n) cout << qans[i] << "\n";

}

