// index が条件を満たすかどうか
bool isOK(ll index, ll key) { //index:食べることができるか判定する回数 key:同時に食べる枚数k
	ll maxEat = 0;
	ll indexLB = lower_bound(card_count.begin(), card_count.end(), index) - card_count.begin();

	if (indexLB > 0) {
		maxEat += total[indexLB - 1];
	}

	maxEat += ((ll)card_count.size() - indexLB) * index;

	eprintf("index: %lld, key: %lld, indexLB: %lld, maxEat:%lld, >= %lld, %s\n", index, key, indexLB, maxEat, key * index, maxEat >= key * index ? "ok" : "ng");

	if (maxEat >= key * index) {
		return true;
	}
	else {
		return false;
	}
}

// 汎用的な二分探索のテンプレ
ll binary_search(ll key) { //k(同時に食べる枚数) = keyとしたとき、食べることができる回数を返す
	ll ng = N + 1; //「index = 0」が条件を満たすこともあるので、初期値は -1
	ll ok = -1; // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

	// ok と ng のどちらが大きいかわからないことを考慮
	while (abs(ok - ng) > 1) {
		ll mid = (ok + ng) / 2;
		if (isOK(mid, key)) ok = mid;
		else ng = mid;
	}
	return ok;
}

