int ri() {
	int n;
	scanf("%d", &n);
	return n;
}

int main() {
	int n = ri();
	std::map<int, int> ma;
	for (int i = 0; i < n; i++) ma[ri()]++;
	std::vector<int> a;
	for (auto i : ma) a.push_back(i.second);
	std::sort(a.begin(), a.end(), std::greater<>());
	for (int i = (int) a.size() - 1; i; i--) a[i - 1] += a[i];

	std::vector<int> cur = a;
	int m = a.size();
	std::vector<int> div(m);
	std::vector<int> change[n + 1];
	change[1].push_back(0);
	int min = 1000000000;
	for (int i = 1; i <= n; i++) {
		if (i > m) {
			std::cout << 0 << std::endl;
			continue;
		}
		for (auto j : change[i]) {
			div[j] = i - j;
			cur[j] = a[j] / div[j];
			min = std::min(min, cur[j]);
			if (cur[j]) {
				// a[j] / div[j] = cur[j] - 1(min div[j])
				// a[j] / cur[j] < div[j]
				int next = a[j] / cur[j] + 1 + j;
				assert(next > div[j]);
				if (next <= n) change[next].push_back(j);
			}
		}
		std::cout << min << std::endl;
		if (i < n) change[i + 1].push_back(i);
	}

	return 0;
}

