template<typename T>
struct dualsegtree{
	function<T(T,T)>lazycalcfn,updatefn;
	int n;
	T lazydefvalue;
	vector<T>dat,lazy;
	vector<bool>lazyflag;
	dualsegtree(int n_=0,T defvalue=0,
		function<T(T,T)>lazycalcfn_=[](T a,T b){return a+b;},
		function<T(T,T)>updatefn_=[](T a,T b){return a+b;},
		T lazydefvalue_=0
	):lazydefvalue(lazydefvalue_),
		lazycalcfn(lazycalcfn_),updatefn(updatefn_)
	{
		n=1;
		while(n<n_)n<<=1;
		dat.assign(n,defvalue);
		lazy.assign(n-1,lazydefvalue);
		lazyflag.assign(n-1,false);
	}
	void copy(const vector<T>&v)
	{
		for(int i=0;i<v.size();i++)dat[i]=v[i];
		lazy.assign(n-1,lazydefvalue);
		lazyflag.assign(n-1,false);
	}
	void update(int a,int b,T x,int k=0,int l=0,int r=-1)//[a,b)
	{
		if(r<0)r=n;
		if(b<=l||r<=a)return;
		else if(a<=l&&r<=b)
		{
			if(k<n-1)
			{
				lazy[k]=lazycalcfn(lazy[k],x);
				lazyflag[k]=true;
			}
			else dat[k-n+1]=updatefn(dat[k-n+1],x);
		}
		else
		{
			if(lazyflag[k])
			{
				update(0,n,lazy[k],k*2+1,l,(l+r)/2);
				update(0,n,lazy[k],k*2+2,(l+r)/2,r);
				lazy[k]=lazydefvalue;
				lazyflag[k]=false;
			}
			update(a,b,x,k*2+1,l,(l+r)/2);
			update(a,b,x,k*2+2,(l+r)/2,r);
		}
	}
	T query(int i)
	{
		T ret=dat[i];
		i+=n-1;
		while(i>0)
		{
			i=(i-1)/2;
			if(lazyflag[i])ret=updatefn(ret,lazy[i]);
		}
		return ret;
	}
};
int N,cnt[3<<17];
main()
{
	cin>>N;
	for(int i=0;i<N;i++)
	{
		int a;cin>>a;cnt[a-1]++;
	}
	vector<int>A;
	for(int i=0;i<N;i++)
	{
		if(cnt[i]>0)A.push_back(cnt[i]);
	}
	sort(A.begin(),A.end());
	if(A.size()==N)
	{
		for(int i=1;i<=N;i++)cout<<N/i<<endl;
		return 0;
	}
	int sum=0;
	dualsegtree<int>P(N+1,1e9,[](int a,int b){return a<b?a:b;},[](int a,int b){return a<b?a:b;},1e9);
	for(int i=0;i<A.size();i++)
	{
		int off=(int)A.size()-i-1;
		sum+=A[i];
		int k=1;
		for(;k*k<=sum;k++)
		{
			P.update(off+k,off+k+1,sum/k);
		}
		int l=sum/k;
		int R=sum+1;
		for(int j=1;j<=l;j++)
		{
			int L=sum/(j+1)+1;
			P.update(off+L,off+R,j);
			R=L;
		}
	}
	P.update(A.size()+1,N+1,0);
	for(int i=1;i<=N;i++)cout<<P.query(i)<<endl;
}

