  vector<long> asdf(N + 1, 0);
  asdf[0] = MOD;
  for (long i = 1; i <= N; i++) {
    long tmp = 0;
    tmp += accumFoo[i];
    if (i + 1 <= N) tmp += accumBar[i+1];
    tmp /= i;
    asdf[i] = tmp;
  }

  reverse(asdf.begin(), asdf.end());
  for (long i = 1; i <= N; i++) {
    auto it = lower_bound(asdf.begin(), asdf.end(), i);
    long ans = it - asdf.begin();
    ans = N - ans;
    cout << ans << endl;
  }
}

