class Solution {
public:
	void solve() {
		int n;
		cin >> n;
		vector<int> a(n, 0);
		for(int i=0; i<n; i++)cin >> a[i];
		vector<int> c(n, 0);
		for(int i=0; i < n; i++)c[a[i]-1]++;
		sort(c.begin(), c.end(), greater<int>());
		while(c.back()==0)c.pop_back();
		reverse(c.begin(), c.end());
		int k = c.size();
		vector<int> s(k+1, 0);
		for(int i=0; i < k; i++){
			s[i+1] = s[i] + c[i];
		}
		for(int t=1; t <= n; t++){
			int ok = 0, ng = n/t+1;
			while(abs(ok-ng)>1){
				int mid = (ok+ng)/2;
				bool flag = false;
				int ac = n;
				auto id = distance(c.begin(), lower_bound(c.begin(), c.end(), mid));
				ac = s[id] + (k-id)*mid;
				flag = (mid*t <= ac);
				if(flag)ok=mid;
				else ng=mid;
			}
			cout << ok << "\n";
		}
		return;
	};
};

