vii nex(300000 + 1);
vi ans(300000 + 1, -1);

void solve(set<pii, greater<pii>> st, int k, int al) {
  while (st.size() >= k) {
    vector<pii> temp;
    al++;
    rep (i, k) {
      auto itr = st.begin();
      pii x = *itr;
      st.erase(itr);
      x.first--;
      if (x.first > 0) temp.push_back(x);
    }
    rep (i, temp.size()) st.insert(temp[i]);
  }
  ans[k] = al;
  rep (i, nex[k].size()) {
    int kk = nex[k][i];
    if (ans[kk] == -1) {
      solve(st, kk, al * (k / kk));
    }
  }
}

int main() {
  int n;
  cin >> n;
  vi a(n);
  rep (i, n) cin >> a[i];
  sort(all(a));
  set<pii, greater<pii>> st;
  int cnt = 1, pre = a[0];
  rep1 (i, n - 1) {
    if (pre == a[i]) cnt++;
    else {
      st.insert(pii(cnt, pre));
      pre = a[i];
      cnt = 1;
    }
  }
  st.insert(pii(cnt, pre));

  vector<bool> isprime(n + 1, true);
  vi primes = prime(isprime);

  for (int i = 1; i <= n; i++) {
    rep (j, primes.size()) {
      int p = primes[j];
      if (i * p > n) break;
      nex[i * p].push_back(i);
      break;
    }
  }

  rrep1 (i, n) {
    if (ans[i] == -1) {
      solve(st, i, 0);
    }
  }

  rep1 (i, n) {
    cout << ans[i] << endl;
  }
}

