inline int check (int k, int i)
{
	if (i > n) return false;
	while (Q.size() && Q.top() < i)
	{
		if (Q.size () < 2) return false;
		int x = Q.top(); Q.pop();
		int y = Q.top(); Q.pop();
		Q.push (x + y);
	}
	if (!Q.size ()) return false;
	if (Q.top() >= i && (signed)Q.size () >= k) return true;
	return false;
}

