    int ok = 0, ng = n+1;
    int cnt = 0;
    while(ng-ok > 1) {
        ++cnt;
        if(cnt > 10) break;
        int mid = (ok+ng) / 2;

        int max_length = (k_argcnt[mid] + mid * (argcnt[n] - argcnt[mid])) / mid;
        if(max_length >= k) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    return ok;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n;
    cin >> n;
    int a;
    vector<int> cnt(n+1, 0);
    for(int i=0;i<n;++i){
        cin >> a;
        ++cnt[a];
    }

    for(int i=1;i<=n;++i) {
        ++argcnt[cnt[i]];
    }
    for(int i=1;i<=n;++i) {
        k_argcnt[i] = i * argcnt[i] + k_argcnt[i-1];
        argcnt[i] += argcnt[i-1];
    }

    for(int k=1;k<=n;++k) {
        cout << calc(n, k) << endl;
    }
}

