int solve(vector<int> mp, int k) {
    if(mp.size() < k) return 0;

    int cnt = 0;
    bool flg = true;
    while(1) {
        sort(mp.begin(), mp.end(), greater<int>());

        for(int i=0; i<k; i++) {
            if(mp[i] == 0) flg = false;
            mp[i]--;
        }

        if(!flg) break;
        cnt++;
    }

    return cnt;
}

