		mm[x]++;
	}
	for (auto& p : mm)
	{
		mc[p.second]++;
	}
	for (auto& p : mc)
		v.push_back(p);
	MEM(ans, -1);
	ans[1] = n;
	for (int i = 2; i <= n; i++)
	{
		solve(i);
		int l = i, r = n;
		int key = l;
		while (l <= r)
		{
			int mid = (l + r) / 2;
			solve(mid);
			if (ans[mid] == ans[i]) key = mid, l = mid + 1;
			else r = mid - 1;
		}
		for (int j = i; j <= key; j++) ans[j] = ans[i];
		i = key;
	}
	for (int i = 1; i <= n; i++) printf("%d\n", ans[i]);
	return 0;
}

