template<class M> struct seglmin {
    int n;
    vector<M> seg;
    vi lazy;//全体に足された数を持つ 3333なら3
    M e = MAX(M);
    vi arch;//遅延評価を行うやつ

    M f(M a, M b) { return a < b ? a : b; }

    seglmin(vector<M> a) {
        n = 1;
        int asz = a.size();
        while (n <= asz)n <<= 1;
        seg.resize((n << 1), e);
        lazy.resize((n << 1), 0);
        rep(i, asz) seg[i + n - 1] = a[i];
        rer(i, n - 2)seg[i] = f(seg[(i << 1) + 1], seg[(i << 1) + 2]);
        int l = 1, v = n;
    }
    void eval() {
        rer(j, sz(arch) - 1) {
            int i = arch[j];            /*iは1index*/            /*lazyは0index*/            int v = lazy[i - 1];
            if (!v)continue;
            lazy[(i << 1) - 1] += v;
            lazy[(i << 1)] += v;
            seg[(i << 1) - 1] += v;
            seg[i << 1] += v;
            lazy[i - 1] = 0;
        }
    }
    void gindex(int l, int r) {
        arch.clear();
        l += n;
        r += n;
        int lm = (l / (l & -l)) >> 1;
        int rm = (r / (r & -r)) >> 1;
        while (l < r) {
            if (r <= rm)arch.push_back(r);
            if (l <= lm)arch.push_back(l);
            l >>= 1;
            r >>= 1;
        }
        while (l) {
            arch.push_back(l);
            l >>= 1;
        }
    }
    void add(int l, int r, int x) {
        int L = l + n;
        int R = r + n;
        while (L < R) {
            if (R & 1) {
                R--;
                lazy[R - 1] += x;
                seg[R - 1] += x;
            }
            if (L & 1) {
                lazy[L - 1] += x;
                seg[L - 1] += x;
                L++;
            }
            L >>= 1;
            R >>= 1;
        }
        l += n;
        r += n;
        int lm = (l / (l & -l)) >> 1;
        int rm = (r / (r & -r)) >> 1;
        while (l < r) {
            if (r <= rm) {
                seg[r - 1] = f(seg[(r << 1) - 1], seg[(r << 1)]);
                seg[r - 1] += lazy[r - 1];
            }
            if (l <= lm) {
                seg[l - 1] = f(seg[(l << 1) - 1], seg[l << 1]);
                seg[l - 1] += lazy[l - 1];
            }
            l >>= 1;
            r >>= 1;
        }
        while (l) {
            seg[l - 1] = f(seg[(l << 1) - 1], seg[l << 1]);
            seg[l - 1] += lazy[l - 1];
            l >>= 1;
        }
    }
    M get(int l, int r) { return get2(l, min(r, n - 1)); }
    M get(int r = inf) { return get2(0, min(r, n - 1)); }
    M getr(int l) { return get2(l, n - 1); }
    M operator[](int i) { return get(i, i + 1); }
#ifdef _DEBUG
    void debu(int len = 10) {
        rep(i, min(n, min(len, n))) {
            int v = get(i, i + 1);
            if (v == e) { cerr << "e "; } else { cerr << v << " "; }
        }
        cerr << "" << endl;
    }
#else
    inline void debu(){;}
#endif
private :
    M get2(int l, int r) {
        gindex(l, r);
        eval();
        int L = l + n;
        int R = r + n;
        M retl = e, retr = e;
        while (L < R) {
            if (R & 1) {
                R--;
                retr = f(seg[R - 1], retr);
            }
            if (L & 1) {
                retl = f(retl, seg[L - 1]);
                L++;
            }
            L >>= 1;
            R >>= 1;
        }
        return f(retl, retr);
    }
};
