struct BITl {
    int n;
    vi a, b;
    BITl(int n) : n(n), a(vi(n + 1)), b(vi(n + 1)) {}
    void add(int s, int t, int value) {        s++;        int x = value;        int x2 = x * (s - 1);        {            int i = s;            while (0 < i && i <= n) {                a[i] += x;                b[i] -= x2;                i += (i & -i);            }        }        x2 += x * (t - s + 1);        {            int i = t;            while (0 < i && i <= n) {                a[i] -= x;                b[i] += x2;                i += (i & -i);            }        }    }
    int sum(int s, int t) {        int res = 0;        {            int res1 = 0;            int i = t;            while (0 < i) {                res1 += a[i];                res += b[i];                i -= (i & -i);            }            res += res1 * t;        }        {            int res1 = 0;            int i = s;            while (0 < i) {                res1 += a[i];                res -= b[i];                i -= (i & -i);            }            res -= res1 * s;        }        return res;    }
    int sum(int r){return sum(0,r);}
    #define get sum
};
