int n;
int a[300005], cnt[300005], sum[300005];

bool solve(int s, int t) {
	int tot = 0;
	auto itr = lower_bound(a, a + n, s);

	if (itr == a + n) tot = sum[n - 1];
	else {
		int id = itr - a;
		if (id) tot += sum[id - 1];
		tot += (n - id) * s;
	}

	return tot >= 1LL * s * t;
}

