int get (int k) {
	if (k > st.size()) return 0;
	if (k == st.size()) {
		return st[0];
	}
	priority_queue < int > q;
	for (auto it : st) q.push(it);
	int ans = 0;
  	while (q.size() > k) {
  		ans ++;
  		int cur = 0;
  		for (int j = 0; j < k; j ++) {
  			pk[cur ++] = q.top() - 1;
  			q.pop();
  		}
  		while (cur --) {
  			if (pk[cur] == 0) continue;
  			q.push(pk[cur]);
  		}
  	}
  	//cout << k << ' ' << ans << '\n';
  	return ans;
}

void go (int l, int r, int L, int R) {
	if (l > r) return ;
	if (L == R) {
		for (int i = l; i <= r; i ++)
			ans[i] = L;
		return ;
	}

	int m = (l + r) >> 1;
	ans[m] = get(m);
	go (l, m - 1, m, R);
	go (m + 1, r, L, m);
}

