int main() {
    int n;
    cin >> n;
    map<int, int> ma;
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        ma[a]++;
    }

    map<int, int> count;
    for (auto x:ma)count[x.second]++;

    for (int i = 1; i <= n; i++) {
        int ok = 0;
        int ng = n / i + 1;
        while (abs(ok - ng) > 1) {
            int mid = ng + (ok - ng) / 2;

            int sum = 0;
            for (auto x:count)sum += min(mid, x.first) * x.second;

            if (sum >= mid * i)ok = mid;
            else ng = mid;
        }

        cout << ok << endl;
    }

    return 0;
}

