    a.push_back(cnt[i]);
  }
  sort(ALL(a));

  int m = a.size();
  int s[m];
  REP(i,m){
    if(i==0){
      s[i] = a[i];
    }else{
      s[i] = s[i-1] + a[i];
    }
  }
  REPP(k,n){
    //[l,r)上での二分探索
    int l = 0;
    int r = n+(k-1)/k;
    while(r-l>1){
      int t = (l+r)/2;
      int num = lower_bound(ALL(a), t) - a.begin();//t未満の値を持つaの要素の個数
      int temp;
      if(num == 0){
        temp = t*m;
      }else{
        temp = s[num-1] + t*(num-1);
      }
      if(temp >= t*k){
        l = t;
      }else{
        r = t;
      }
    }
    cout<<l<<endl;
  }
  return 0; 
}

