int bit[MAXN];
void add (int x, int val) {
    for (;x<MAXN; x+=-x&x) {
        bit[x] += val;
    }
}

int qry (int x) {
    int ret = 0;
    for (;x>0; x-=-x&x) {
        ret += bit[x];
    }
    return ret;
}

int lbd (int x) {
    int res = 0, sum = 0;
    for (int h=18; h>=0; h--) {
        if (sum + bit[res+(1<<h)] < x) {
            sum += bit[res + (1<<h)];
            res += 1<<h;
        }
    }
    return res+1;
}
