int main(){
    ll N = read<ll>();
    map<ll, ll> A;
    REP(i, N){
        ll a = read<ll>();
        ++A[a];
    }
    map<ll, ll> B;
    for(auto &v : A){
        B[v.second]++;
    }

    const ll Asize = A.size();
    for(ll i = 1; i <= N; ++i)
    {
        if(i == 1){ write(N); }
        else if(i > Asize){ write(0); }
        else{
            auto Bcopy = B;
            ll ans = 0;
            while(true){
                ll res = i;
                map<ll, ll> sub;
                for(auto it = Bcopy.rbegin(); it != Bcopy.rend(); ++it)
                {
                    ll s = min(res, it->second);
                    sub[it->first] = s;
                    res -= s;
                    if(res == 0) break;
                } 
                if(res > 0) break;

                ++ans;
                for(auto &v : sub){
                    Bcopy[v.first] -= v.second;
                    if(v.first > 1){
                        Bcopy[v.first - 1] += v.second;
                    }
                }
            }
            write(ans);
        }
    }
