using namespace std;

int solve(int* num, int k,int l, int N){
    int c=0;
    for(int i = 0;i<N;i++){
        if(num[i]>0){c++;
        }
    }
    if(c<k)return l;

    sort(num,num+N);
    for(int i = 0;i<k;i++){
        num[N-i-1]--;
    }

    return solve(num, k, l+1, N);
}


