	map<int,int> mope;
	for(int i=0;i<n;i++){
		int x;
		cin>>x;
		a.pb(x);
		u.pb(x);
		mope[x]++;
	}
	sort(u.begin(),u.end());
	u.erase( unique( u.begin(),u.end() ), u.end() );
	vector<int> cnt;
	cnt.pb(0);
	for(int i=0;i<u.size();i++){
		cnt.pb( mope[ u[i] ] );
	}
	sort(cnt.begin(),cnt.end());
	for(int i=1;i<=cnt.size();i++){
		sum[i] = sum[i-1] + cnt[i];
	}
	int cur = 0;
	for(int i=n;i>=1;i--){
		if( i >= cnt.size() ) ans[i] = 0;
		else{
			int start = cnt.size() - i;
			int ng = cnt.size(), ok = start; // start ~ ok can be same
			while( ng - ok > 1 ){
				int mid = ( ok + ng ) / 2;
				int num = mid - start + 1;
				int tmp = cnt[mid] * num - ( sum[mid] - sum[start-1] );
				if( tmp > cur ){
					ng = mid;
				}
				else{
					ok = mid;
				}
			}
			int amari = cur - cnt[ok] * (ok-start+1) + ( sum[ok] - sum[start-1] );
			ans[i] = cnt[ok] + amari/(ok-start+1);
			cur += cnt[start];
		}
	}
	for(int i=1;i<=n;i++){
		cout<<ans[i]<<endl;
	}
	return 0;
}

