#include <algorithm>
#include <cinttypes>
#include <cstdio>
#include <vector>

int solve_F() {
  uint64_t N;
  scanf("%" SCNu64, &N);

  // 各値の個数を数える
  std::vector<uint64_t> counts(static_cast<size_t>(N));
  for (size_t i = 0; i < N; ++i) {
    uint64_t A;
    scanf("%" SCNu64, &A);
    counts[static_cast<size_t>(A - 1)]++;
  }

  // 0個の値を取り除く
  counts.erase(std::remove(counts.begin(), counts.end(), 0), counts.end());

  // K=1
  printf("%" PRIu64 "\n", N);

  // 1. 実際に差し引いてみる方法
  auto solver1 = [&]() {
    for (size_t K = 2; K <= counts.size(); ++K) {
      auto vec = counts;
      uint64_t result = 0;
      while (vec.size() >= K) {
        uint64_t m = vec[0];
        for (size_t i = 1; i < K; ++i) {
          m = std::min(m, vec[i]);
        }

        // mで差し引きつつ、0となった値を取り除く
        auto iter = vec.begin();
        auto end_iter = vec.begin() + K;  // 終端
        auto head_iter = vec.end();  // 除去される値の先頭
        while (iter < end_iter) {
          *iter -= m;
          if (*iter == 0) {
            std::swap(*iter, *--head_iter);
            if (head_iter < end_iter) {
              --end_iter;
            } else {
              ++iter;
            }
          }
        }
        vec.erase(head_iter, vec.end());

        result += m;
      }

      printf("%" PRIu64 "\n", result);
    }
  };

  // 2. 詰めたブロックの総面積を計算する方法
  auto solver2 = [&]() {
    std::sort(counts.begin(), counts.end());

    std::vector<uint64_t> deltas(counts.size());
    deltas[0] = counts[0];
    for (size_t i = 1; i < counts.size(); ++i) {
      deltas[i] = counts[i] - counts[i - 1];
    }

    for (uint64_t K = 2; K <= counts.size(); ++K) {
      uint64_t result = 0;
      for (uint64_t i = 0; i <= counts.size() - K; ++i) {
        const uint64_t n = (counts.size() - i) / K;
        result += deltas[static_cast<size_t>(i)] * n;
      }
      printf("%" PRIu64 "\n", result);
    }

    return 0;
  };

  solver1();

  // その他
  for (uint64_t K = counts.size() + 1; K <= N; ++K) {
    printf("0\n");
  }

  return 0;
}

int main() { return solve_F(); }

