inline void insertToSet(int val, int cnt, set<pair<int, int> > &S){
    if(S.empty() or (*S.begin()).ff > val) S.insert({val, cnt});//, debug("inserting", val, cnt);
    else {
        auto now = *S.begin();
        S.erase(S.begin());
        S.insert({val, now.ss + cnt});
        // debug("inserting", val, now.ss + cnt);
    }
}

inline void addToSet(int add, set<pair<int, int> > &S){
    // debug("adding", add);
    while(add){
        auto now = *S.begin();
        S.erase(S.begin());
        // debug("now", add, now.ff, now.ss);
        if(now.ss <= add){
            insertToSet(now.ff + 1, now.ss, S);
            add -= now.ss;
        }
        else{
            insertToSet(now.ff + 1, add, S);
            insertToSet(now.ff, now.ss - add, S);
            add = 0;
        }
    }
}

