  map<int, int> cnt;
  for (int i = 0; i < n; ++i) {
    int x; cin >> x; cnt[x] += 1;
  }
  vector<int> v;
  for (auto p : cnt)
    v.push_back(p.second);

  vector<int> buff;
  auto eval = [&](int k) {
    priority_queue<int> pq;
    for (auto x : v)
      pq.push(x);

    int ans = 0;
    while (pq.size() >= k) {
      buff.clear();
      for (int i = 0; i < k; ++i) {
        buff.push_back(pq.top());
        pq.pop();
      }
      for (auto x : buff) {
        if (x > 1)
          pq.push(x - 1);
      }
      ++ans;
    }
    return ans;
  };

  vector<int> ans(n);
  ConstantIntervals(1, n + 1, eval, [&](int b, int e, int x) {
    for (int i = b; i < e; ++i)
      ans[i - 1] = x;
  });

  for (int i = 0; i < n; ++i)
    cout << ans[i] << '\n';

  return 0;
}

