	for (int i = 1; i <= n; i++) { // eat i-times
		int l = -1;
		int r = n;
		while (r - l > 1) {
			int m = l + (r - l) / 2;
			if (check(a, m, i)) l = m;
			else r = m;
		}
		upper[i] = l;
	}
	int head = n;
	for (int i = 1; i <= n; i++) {
