int fn(int X,vector<int> & D,vector<int> &kD)
{
  if(X == 0) return I64_MAX;
  return (kD[X] + X*(D[D.size()-1] - D[X]))/X;
}

void solve()
{
  int N;
  cin>>N;
  vector<int> vec(N+1,0);
  vector<int> D(N+1,0);
