  }


  for (int i = 0; i < N+1; i++)
  {
    D[vec[i]]++;
  }


  for (int i = 0; i <= N; i++)
  {
    kD[i] = i *D[i];
  }

  for (int i = 0; i <= N-1; i++)
  {
    D[i+1] += D[i];
    kD[i+1] += kD[i];
  }

  for (int i = 1; i < N+1; i++)
  {
    X_1[i] = (kD[i] + i*(D[N] - D[i]))/i;
  }

  for (int k = 1; k <= N/2; k++)
  {
    int X = N;
    int ANS;
     while(X&&(k > X_1[X]))X--;
    ANS = X;
    cout<<ANS<<endl;
  }

  return;
}

