					a = cc.top().first;
					b = cc.top().second - x;
					cc.pop();
					cc.push({ a, b });
				}
				else cc.pop();
			}

			for (j = 0; j < top; j++) {
				a = plist[j].first;
				b = plist[j].second;

				if (a > 1) cc.push({ a - 1, b });
				else vv -= b;
			}

			ans[i]++;
		}
	}


	for (i = 1; i <= n; i++) cout << ans[i] << "\n";


	return 0;
}

