struct Segtree {
  vector<int> d;
  int n, h;
  Segtree(int sz) {
    h = 32 - __builtin_clz(sz);
    n = 1<<h;
    d = vector<int>(n<<1);
  }
  void add(int l, int r, int x) {
    for (l+=n, r+=n; l<r; l/=2, r/=2) {
      if (l%2) {
        d[l++] += x;
      }
      if (r%2) {
        d[--r] += x;
      }
    }
  }
  int query(int x) const {
    int ans = 0;
    for (x+=n; x; x/=2) {
      ans += d[x];
    }
    return ans;
  }
};

int find_top(const Segtree& st, int lo, int n) {
  int hi = n-1;
  int lv = st.query(lo);
  while (lo<hi) {
    int mid = (lo+hi+1)/2;
    if (st.query(mid) < lv) {
      hi = mid-1;
    } else {
      lo = mid;
    }
  }
  return hi;
}

int find_bot(const Segtree& st, int hi) {
  int lo = 0;
  int hv = st.query(hi);
  while (lo<hi) {
    int mid = (lo+hi)/2;
    if (st.query(mid) > hv) {
      lo = mid+1;
    } else {
      hi = mid;
    }
  }
  return lo;
}
