int SanFen(int l,int r,int k) //找凸点  
{  
    while(l < r-1)  
    {  
        int mid  = (l+r)/2;  
        int mmid = (mid+r)/2;  
        if( f(mid,k) > f(mmid,k) )  
            l = mid;  
        else  
            r = mmid;  
    }  
    return f(l,k) > f(r,k) ? l : r;  
}  

