vector<long> vec(300010);

void foo (long k) {
  if (k == 1) {
    cout << N << endl;
    return;
  }
  if (k > mp.size()) {
    cout << 0 << endl;
    return;
  }
  priority_queue<long> pq;
  for (auto it = mp.begin(); it != mp.end(); it++) {
    pq.push(it->second);
  }
  long ans = 0;
  while (true) {
    if (pq.size() < k) break;
    rep (i, k) {
      vec[i] = pq.top();
      pq.pop();
    }
    rep (i, k) {
      if (vec[i] > 1) pq.push(vec[i] - 1);
    }
    ans++;
  }
  cout << ans << endl;
  return;
}

