bool check(long long k, long long t) {
    if (t * k > pr[n])
        return false;
    long long i = lower_bound(f.begin(), f.end(), t) - f.begin();
    if (pr[i] >= (i - (n - k)) * t)
        return true;
    else
        return false;
}

int bin_search(long long k) {
    int l = 0; int r = 3 * N;
    while(l < r) {
        int med = (l + r) / 2;
        if (check(k, med))
            l = med + 1;
        else
            r = med;
    }
    return l - 1;
}
