using namespace std;

int numberOfCards; // number of cards;
int numberOfDifferentCards;

vector<int> cards;

void readData(){
    scanf("%d", &numberOfCards);
    /*
    vector<int> c(300000 + 1, 0); // 300000 is the maximum number of value

    */
    unordered_map<int, int> c;
    for (int i = 0; i < numberOfCards; i++){
        int v;
        scanf("%d", &v);
        if(c.count(v)==0){
            c[v] = 0;
        }
        c[v]++;
    }
    for (auto v : c){
        if (v.second > 0){
            cards.push_back(v.second);
        }
    }
//    make_heap(cards.begin(), cards.end());
    sort(cards.begin(), cards.end());
    numberOfDifferentCards = cards.size();
}

int countHowMany(int k){
    if(k==1){
        return numberOfCards;
    }else if(k > numberOfDifferentCards){
        return 0;
    }
    vector<int> c(cards.cbegin(), cards.cend());
    int count = 0;
    while(c.size() >= k){
        if(c.size() == k){
            count += *min_element(c.cbegin(), c.cend());
            break;
        }
        for (auto head = c.begin(); head + k-1< c.end();head += k){
            int reduce = *(head + k - 1);
            for (auto it = head; it < head + k;it++){
                *it -= reduce;
            }
            count += reduce;
        }
        //erase_if(c, [](int x) { return x == 0; });
        c.erase(remove_if(c.begin(), c.end(), [](int x) { return x == 0; }), c.end());
        sort(c.begin(), c.end());
    }
    return count;
}

int countHowMany0(int k){
    if (k == 1){
        return numberOfCards;
    }else if(k > numberOfDifferentCards){
        return 0;
    }
    vector<int> c(cards.begin(), cards.end());
    int count = 0;
    vector<int> v(k);
    while (c.size() >= k){
        if(c.size() == k){
            count += *min_element(c.cbegin(), c.cend());
            //c.clear();
            break;
        }else{
            //count++;
            for (int i = 0; i < k; ++i){
                pop_heap(c.begin(), c.end());
                v[i] = c.back();
                c.pop_back();
            }
            int diff = 1;
            if (v.back() > c.front()){
                diff = v.back() - c.front()+1;
            }
            for (int i = 0; i < k; ++i){
                v[i] -= diff;
                if (v[i] > 0){
                    c.push_back(v[i]);
                    push_heap(c.begin(), c.end());
                }
            }
            count += diff;
        }
    }
    return count;
}

int main(){
    readData();
    for (int k = 1; k <= numberOfCards; ++k)
    {
        printf("%d\n", countHowMany(k));
    }
    return 0;
}

