int tot = 0;
int ans[N];
ll pre[N], e[N];
inline bool gao(int k, int x) {
	int pos = upper_bound(e + 1, e + tot + 1, x) - e;
	return pre[pos-1] + 1ll*(tot-pos+1)*x >= 1ll*k*x;
}
int main() {
