    sort(e + 1,e + tot + 1);
    rep(i, 1, tot + 1) pre[i] = pre[i-1] + e[i];
    int cur = 0;
    repd(k, tot, 1) {
        while(cur < n&&gao(k, cur+1)) ++cur;
        ans[k] = cur;
