std::vector<int64_t> V, Vac;

bool check(int64_t K, int64_t X) {
    auto cs = binary_search(0, V.size()-1, [&](int64_t i){
        return V[i] < X;
    });
    int64_t num = 0;
    if (cs.valid) {
        num = Vac[cs.end] + X * (V.size() - cs.size());
    } else {
        num = X * V.size();
    }
    return K*X <= num;
}

