void solve(){
  ll N;
  cin >> N;
  vector<ll> A(N, 0);
  rep(i, N){
    ll a;
    cin >> a;
    A[a-1]++;
  }
  sort(A.begin(), A.end());
  reverse(A.begin(), A.end());
  ll canuse = N, erased_num = 0;
  ll s = 0;
  vector<ll> ok(N+1, 0);
  for(ll ans = N; ans >= 1; ans--){
    while(ans < A[s]){
      canuse -= (A[s] - ans);
      erased_num++;
      s++;
    }
    chmax(ok[canuse / ans], ans);
    canuse -= erased_num;
  }

  revrep(i, N){
    if(ok[i] == 0) ok[i] = ok[i+1];
  }
  rep(i, N){
    cout << ok[i+1] << endl;
  }
}

