bool is_possible(int i,int m)
{
	int cnt=0;
	auto p=q;
	while(p.size() >= i)
	{
		vector<int>v;
		for(int j=0;j<i;j++)
		{
			v.push_back(p.top());
			p.pop();
		}
		int c=v.back();
		cnt+=c;
		for(int j=0;j<i;j++)
		{
			if(v[j]==c)break;
			p.push(v[j]-c);
		}
	}
	return cnt >= m;
}
