const Int N = 300010;
vector<P> tmp(N);
vector<Int> Sum(N);
const Int S = 300010;
P M[S];
Int front = 0;
Int back = 0;

inline void pop_front(){front = front+1 == S? 0:front+1;}
inline void push_front(const P x){
  front --;
  if(front < 0) front = S - 1;
  M[front] = x;
}

Int calc(deque<P> A, Int K, Int N){
  front = 0;
  back = N-1;
  for(Int i=0;i<(Int)A.size();i++) M[i] = A[i];

  Int cnt = 0;
  if(K == 1) return N;

  while(1){
    Int idx = 0;
    {
      Int sum = 0;
      while(sum < K){
        if(front == back) return cnt;
        auto t = M[front]; pop_front();
        if(t.first == 0) continue;
        Sum[idx] = sum;
        sum += t.second;
        tmp[idx] = t;
        idx++;
      }
    }

    while(--idx >=0 ){
      auto p = tmp[idx];
      Int sum = Sum[idx];
      if(sum + p.second <= K){
        if(p.first - 1 > 0) {
          if(front!= back && M[front].first == p.first - 1) M[front].second += p.second;
          else if(p.first - 1 > 0) push_front(P(p.first - 1, p.second));
        }
      }
      else{
        if(front != back && M[front].first == p.first - 1) M[front].second += K - sum;
        else if(p.first - 1 > 0) push_front(P(p.first - 1, K - sum));
        push_front(P(p.first, p.second - (K - sum)));
      }
    }
    cnt++;
  }
}

