void dij(int s) {

	d[s] = 0;
	priority_queue<vector<ll>, vector<vector<ll>>, greater<vector<ll>>> q;
	q.push({0,0,s});
	while (!q.empty())
	{
		auto p = q.top();
		q.pop();
		int cou = p[0];
		int cur = p[2];
		int dis = p[1];
		if (cou > d[cur]) continue;
		for (auto v : es[cur])
		{
			int val = v.cap != dis;
			if (cou + val < d[v.to]) {
				d[v.to] = cou + val;
				q.push({ d[v.to],v.cap,v.to });
			}
		}
	}
}
