#include <stdio.h>
void dec(int* num, int N){
    int m = 0;
    for(int i = 0;i<N;i++){
        if(num[i]>num[m])m=i;
    }
    num[m]--;
}


int solve(int* num, int k,int l, int N){
    int c=0;
    for(int i = 0;i<N;i++){
        if(num[i]>0)c++;
    }
    if(c<k)return l;

for(int i = 0;i<k;i++){
    dec(num, N);
}
    return solve(num, k, l+1, N);
}


