// 指定された要素以上の値が現れる最初の位置のイテレータ
// [l,r)
typedef int lb;
int lower_bound(lb* a, lb val, int l, int r)
{
    if(l==r) return l;
    int m = (l+r)/2;
    if(a[m]<val) return lower_bound(a,val,m+1,r);
    else return lower_bound(a,val,l,m);
}

