int TMP;

void swap(int i, int j) {
    int TMP;
    TMP        = M_ARRAY[i];
    M_ARRAY[i] = M_ARRAY[j];
    M_ARRAY[j] = TMP;
#ifdef SLAVE
    TMP        = S_ARRAY[i];
    S_ARRAY[i] = S_ARRAY[j];
    S_ARRAY[j] = TMP;
#endif
}

void heap(int k, int r) {
    int j;
    while (1) {
        j = 2 * k + 1;
        if (j > r) break;
        if (j != r) {
#ifdef UP
            if (M_ARRAY[j + 1] > M_ARRAY[j]) {
#else
            if (M_ARRAY[j + 1] < M_ARRAY[j]) {
#endif
                j = j + 1;
            }
        }
#ifdef UP
        if (M_ARRAY[k] >= M_ARRAY[j]) break;
#else
        if (M_ARRAY[k] <= M_ARRAY[j]) break;
#endif
        swap(k, j);
        k = j;
    }
}

void sort(int length) {
    int i;
    for (i = (length - 2) / 2; i >= 0; i--) {
        heap(i, length - 1);
    }
    for (i = length - 1; i > 0; i--) {
        swap(0, i);
        heap(0, i - 1);
    }
}

