// 指定された要素以上の値が現れる最初の位置のイテレータ
typedef int lb;
int lower_bound(lb* a, lb val, int len)
{
    int l = 0;
    int r = len;
    while(l!=r)
    {
        int m = (l+r)/2;
        if(a[m]<val) l = m+1;
        else r = m;
    }
    return l;
}

