fun count(list: List<Int>, x: Int): Int {
    if (x == 1) {
        return list.sum()
    }

    val q = PriorityQueue<Int>(Comparator<Int> { a, b -> b.compareTo(a) })
    q.addAll(list)

    var r = 0
    while (q.size >= x) {
        val k = ArrayList<Int>()
        repeat(x) {
            k.add(q.poll())
        }
        val last = k.last()
        r += last

        k.map { it - last }.filter { it > 0 }.forEach {
            q.add(it)
        }
    }
    return r
}

