    var mList = list.toMutableList();
    var count = 0;
    while (true) {
        if (mList.size < k) {
            println(count)
            break
        }
        val last = mList.size
        val sage = mList[last - k]
        ((last - k) until last).forEach {
            mList[(it)] = mList[it] - sage
        }
        mList = mList.filter { it != 0 }.sorted().toMutableList()
        count + sage
    }
}

