    public static int eatCards(int k, int[] list){
        int counter = 0;
        for (int j = 0; j < list.length; j++) {
            int num = k;
            if(list[j]!=-1){
                int first = list[j];
                list[j] = -1;
                num--;
                for(int i= j + 1; i < list.length; i++) {
                    if (first != list[i] && list[i] != -1) {
                        num--;
                        first = list[i];
                        list[i] = -1;
                        if(num == 0){
                            counter++;
                            break;
                        }
                    }
                }
               if(num != 0) break;
            }
        }
        return  counter;
    }
}

