import java.util.*;
import java.util.stream.Collectors;

class Main {
	public static void main(String[] args) {
      Scanner sc = new Scanner(System.in);
      int N = Integer.parseInt(sc.next());
      List<Integer> list = new ArrayList<>();

      for (int i = 0; i < N; ++i) {
        list.add(Integer.parseInt(sc.next()));
      }

      Map<Integer, List<Integer>> tempMap = list.stream().collect(Collectors.groupingBy(Integer::intValue));
      List<Integer> tempList = tempMap.values().stream().map(List::size).collect(Collectors.toList());
      tempList.sort(Comparator.comparingInt(Integer::intValue).reversed());
      Integer[] arr = tempList.toArray(new Integer[0]);

      for (int i = 1; i <= N; ++i) {
        Integer[] temparr = arr.clone();
        // 最終的な回数
        int result = 0;
        int counter = 0;
        boolean isFinished = false;
        // 明らかに不可能な場合はループを回さない
        if (temparr.length < i) isFinished = true;
        else if (temparr.length == i) {
          result = 1;
          isFinished = true;
        }

        // 食べられる間ループする
        while (!isFinished) {
          isFinished = true;
          // 先頭から辿っていって数の多いものからたべていく
          for (int j = 0; j < temparr.length; ++j) {
            if (temparr[j] > 0) {
              // 食べられる場合は1減らしてカウンタをインクリメント
              temparr[j]--;
              counter++;
            }
            if (counter == i) {
              // カウンタがKに達した場合は食べられた回数をインクリメントし、カウンタを初期化して次のループへ
              result++;
              counter = 0;
              isFinished = false;
              break;
            }
          }

        }

        System.out.println(result);
      }
    }
}

import java.util.Scanner;

public class Solution {
    static Scanner sc;
    public static void main(String[] args) {
        sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] A = new int[N];
        int[] C = new int[N+1];
        int[] D = new int[N+1];

        for(int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
            C[A[i]] += 1;
        }

        for(int i = 0; i <= N; i++) {
            D[C[i]] += 1;
        }

        int[] Dk_cumsum = new int[N+1];
        int[] D_cumsum = new int[N+1];

        D_cumsum[N] = D[N];
        for(int k = 1; k <= N; k++) {
            Dk_cumsum[k] = Dk_cumsum[k-1] + k*D[k];
            D_cumsum[N-k] = D_cumsum[N-k+1] + D[N-k];
        }

        int[] f = new int[N+1];
        for(int X = 1; X <= N; X++) {
            if(X == N) {
                f[X] = Dk_cumsum[X] / X;
            } else {
                f[X] = (Dk_cumsum[X] + X * D_cumsum[X+1]) / X;
            }
        }

        for(int K = 1; K <= N; K++) {
            //find X maximal, with K <= f(X)
            int x = 0;
            if(f[1] >= K) {
                if(K <= f[N]) {
                    System.out.println(N);
                } else {
                    for (int b = N; b >= 1; b /=2) {
                        while(K <= f[x+b]) x += b;
                    }
                    System.out.println(x);
                }
            } else {
                System.out.println("0");
            }
        }
    }
}

