			int v = t ;
			while ( v >= k ) {
				for ( int i = n-1, cc = k ; i >=0 ; --i ) {
					if ( w[i] > 0 ) {
						if ( --w[i] == 0 ) {
							--v;
						}
						if ( --cc == 0 ) {
