		int N = sc.nextInt();
		int A[] = new int[300001];
		for(int i = 0 ; i < N ; ++i){
			int ai = sc.nextInt();
			A[ai]++;
		}
		Arrays.sort(A);
		int freq[] = new int[300001];
		for(int a : A){
			if(a == 0){
				continue;
			}
			freq[a]++;
		}
		long C[] = new long[N + 1];
		long D[] = new long[N + 1];
		for(int f = 1 ; f <= N ; ++f){
			C[f] = C[f - 1] + f * freq[f];
			D[f] = D[f - 1] + freq[f];
		}
		int X[] = new int[N  + 1];
		for(int x = 1 ; x <= N ; ++x){
			long f = C[x] + x * (D[N] - D[x]);
			f = f / x;
			X[x] = (int)f;
		}
		int res[] = new int[N + 1];
		res[1] = N;
		for(int i = N - 1 ; i >= 1 ; --i){
			if(X[i + 1] != X[i]){
				for(int j = X[i + 1] + 1; j <= X[i] ; ++j){
					res[j] = i;
				}
			}
		}
		for(int k = 1 ; k <= N ; ++k){
