        for (int i = 1; i <= n; i++) {
            sum += a[i];
        }
        long[] ans = new long[n];
        for (int i = 1; i <= n; i++) {
            if (i <= sum) {
                int u = sum - a[1];
                if (i <= u) {
                    int p = (n - sum) / i;
