import java.io.*;
import java.util.*;

class Node implements Comparable<Node> {
  final int uniq;
  final int count;

  Node(int uniq, int count) {
    this.uniq = uniq;
    this.count = count;
  }

  // Large first
  public int compareTo(Node node) {
    return node.count - this.count;
  }
}

class Solver {
  final int n;
  final int[] as;
  List<Node> nodes;

  Solver(int n, int[] as) {
    this.n = n;
    this.as = as;
  }

  private void addPendingQueue(Deque<Node> pendingQueue, Node node) {
    if (node.count <= 0) {
      return;
    }
    if (!pendingQueue.isEmpty() && pendingQueue.peekLast().count == node.count) {
      pendingQueue.add(new Node(node.uniq + pendingQueue.pollLast().uniq, node.count));
    } else {
      pendingQueue.add(node);
    }
  }

  private int solve(int k) {
    PriorityQueue<Node> queue = new PriorityQueue<>();
    queue.addAll(nodes);
    int answer = 0;
    while (true) {
      Deque<Node> pendingQueue = new ArrayDeque<>();
      int count = 0;
      while (!queue.isEmpty()) {
        Node node = queue.poll();
//        System.err.printf("%d %d\n", node.uniq, node.count);
        if (count + node.uniq < k) {
          addPendingQueue(pendingQueue, new Node(node.uniq, node.count - 1));
          count += node.uniq;
        } else {
          addPendingQueue(pendingQueue, new Node(k - count, node.count - 1));
          if (node.uniq - k + count > 0) {
            queue.add(new Node(node.uniq - k + count, node.count));
          }
          count = k;
          break;
        }
      }
      if (count < k) {
        break;
      }
      queue.addAll(pendingQueue);
      answer++;
    }
    return answer;
  }

  public int[] solve() {
    int[] count = new int[n + 1];
    for (int a : as) {
      count[a]++;
    }

    int[] countCount = new int[n + 1];
    for (int i = 1; i <= n; i++) {
      countCount[count[i]]++;
    }

    nodes = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
      if (countCount[i] > 0) {
        nodes.add(new Node(countCount[i], i));
      }
    }

    int[] answers = new int[n];
    answers[0] = n;
    for (int k = 2; k <= n; k++) {
      answers[k - 1] = solve(k);
    }
    return answers;
  }
}

