import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {
    public static void main(String[] args) {
        FastScanner fsc = new FastScanner();
        int n = fsc.nextInt();
        int[] cnt = new int[n];
        for (int i = 0; i < n; i++) {
            int ai = fsc.nextInt() - 1;
            cnt[ai]++;
        }
        int[] a = new int[n + 1];
        for (int c : cnt) {
            a[c]++;
        }
        int sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += a[i];
        }
        long[] ans = new long[n];
        for (int i = 1; i <= n; i++) {
            if (i <= sum) {
                int u = sum - a[1];
                if (i <= u) {
                    int p = (n - sum) / i;
                    int q = (n - sum) % i;
                    ans[i - 1] = p + 1 + (sum - i + q) / i;
                } else {
                    if (u == 0) {
                        ans[i - 1] = sum / i;
                    } else {
                        int x = a[1] / (i - u);
                        int p = (n - sum) / u;
                        int q = (n - sum) % u;
                        int s = a[1] - p * (i - u) - i + 2 * q;
                        int y = s >= 0 ? p + 1 + s / i: p;
                        ans[i - 1] = Math.min(x, y);
                    }
                }
            } else {
                ans[i - 1] = 0;
            }
        }
        ArrayUtil.println(ans);
    }
}


