import java.util.Arrays;
import java.util.Scanner;
import java.util.function.Function;

public class Main {
    public static void main(String[] args) {
        Scanner std = new Scanner(System.in);
        int n = std.nextInt();
        Integer[] a = new Integer[n];
        for (int i = 0; i < n; i++) {
            a[i] = 0;
        }
        for (int i = 0; i < n; i++) {
            int x = std.nextInt() - 1;
            a[x]++;
        }

        Integer[] sorted = Arrays.stream(a).sorted().toArray(Integer[]::new);
        int[] s = new int[n + 1];
        for (int i = 0; i < n; i++) {
            s[i + 1] = s[i] + sorted[i];
        }

        // 1 ~ n takes
        for (int k = 1; k <= n; k++) {
            final int kIndex = k;
            int l = 0, r = n/k + 1;
            while (l + 1 < r) {
                int c = (l + r) / 2;
                Function<Integer, Boolean> f = integer -> {
                    int i = ~Arrays.binarySearch(sorted, integer, (l1, r1) -> l1.compareTo(r1) >= 0 ? 1 : -1);
                    int sum = integer * (n - i) + s[i];
                    return (sum >= integer * kIndex);
                };

                if (f.apply(c)) {
                    l = c;
                } else {
                    r = c;
                }
            }

            System.out.println(l);
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	static int N;
	static int[] A;

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		N = Integer.parseInt(br.readLine());
		A = new int[N];
		String str = br.readLine();
		String[] word = str.split("\\s+");
		for (int i = 0; i < N; i++) {
			A[i] = Integer.parseInt(word[i ]);
		}
		Arrays.sort(A);
		for (int i = 1; i <= N; i++) {
			compute(i);
		}

	}

	/**
	 * N=3*100000;
	 * 任取k个不同，remove  (N/k);
	 * 
	 * 
	 * 
	 * @param k
	 */

	private static void compute(int k){
		int res = 0 ;

		int i = 0;
		while( i < N ){
			int diff  = 0;
			int j = i;
			for(j=i;j<N;j++){
				if( j  == i ){
					diff++;
				}
				else if( A[j] != A[j-1]){
					diff++;
				}
				else{
					diff = diff +  0;
				}

				if( diff == k){
					res++;
					break;
				}
			}
			i  =  j + 1;
		}
		System.out.println(res);

}

}

