                Set<Entry<Integer, Integer>> s=new HashSet<>();
                In:while(true){
                    Entry<Integer, Integer> e=now.pollFirstEntry();
                    if(isNull(e)) break Out;
                    int key=e.getKey();
                    int val=e.getValue()-pre;
                    if(val==0){
                        s.add(e);
                        pre=0;
                        continue;
                    }
                    if(val<k){
                        k-=val;
                        if(pre>0) now.put(key, pre);
                        if(key>1){
                            Integer v=now.putIfAbsent(key-1, val);
                            if(nonNull(v)) now.put(key-1, v+val);
                            pre=val;
                        }
                    } else{
                        if(val+pre>k) now.put(key, val+pre-k);
                        if(key>1){
                            Integer v=now.putIfAbsent(key-1, k);
                            if(nonNull(v)) now.put(key-1, v+k);
                        }
                        break In;
                    }
                }
                for(Entry<Integer, Integer> e: s) now.put(e.getKey(), e.getValue());
                pre=0;
                k=m;
                cnt++;
            }
            // System.out.println();
            sb.append(cnt).append('\n');
        }
        System.out.print(sb);
   }
