public class Main implements Runnable{

	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * ABC143 F問題
		 * 考察メモ
		 * えーと、まず同じ整数の個数だけで纏められる(multiset?)
		 * その状態で考えると、最大の整数にのみ着目すれば良いことも分かる
		 * 常に最大の要素を持つ整数を選ぶように操作を行うことを前提とすると、
		 * まず操作回数がN/K回なことから、max(A_i)≦N/KならN/K回操作できる
		 * そうでないなら先頭は必ず取る、ということは先頭を除いたところについてK-1の問題と同値
		 * ……ところでこれは単調性を持たないかな
		 * つまり、K=1から順に考えるとO(N)になりそう
		 *
		 *
		 */
		int N = io.nextInt();
		int[] count = new int[N + 1];
		for (@SuppressWarnings("unused") final int i : IntRange.open(N)) count[io.nextInt()]++;
		Arrays.sort(count);
		for (int i = 0;i < count.length / 2;++ i) {
			int tmp = count[i];
			count[i] = count[N - i];
			count[N - i] = tmp;
		}

		int check = 0, sum = N;
		for (int i = 1;i <= N;++ i) {
			try {
				while (count[check] > sum / (i - check)) { // 取れないので1個減らした問題に帰着
					sum -= count[check];
					++ check;
				}
				io.println(sum / (i - check));
			} catch (ArithmeticException e) {
				io.println(0);
			}
		}

	}

