class Solver {
  final int n;
  final int[] as;

  Solver(int n, int[] as) {
    this.n = n;
    this.as = as;
  }

  public int[] solve() {
    int[] cs = new int[n + 1];
    for (int a : as) {
      cs[a]++;
    }

    int[] ds = new int[n + 1];
    for (int c : cs) {
      if (c > 0) {
        ds[c]++;
      }
    }

    int[] dSums = new int[n + 1];
    int[] dKSums = new int[n + 1];
    for (int i = 1; i <= n; i++) {
      dSums[i] = dSums[i - 1] + ds[i];
      dKSums[i] = dKSums[i - 1] + i * ds[i];
    }

    int[] fs = new int[n + 1];
    for (int x = 1; x <= n; x++) {
      fs[x] = (dKSums[x] / x) + dSums[n] - dSums[x];
    }

    int[] answers = new int[n];
    int k = 1;
    int x = n;
    while (k <= n) {
      while (x >= 0 && fs[x] < k) {
        x--;
      }
      if (x <= 0) {
        break;
      }
      answers[k - 1] = x;
      k++;
    }
    return answers;
  }
}

