	public class Pair<K, V> {

		/**
		 * Key of this <code>Pair</code>.
		 */
		private K key;

		/**
		 * Gets the key for this pair.
		 * 
		 * @return key for this pair
		 */
		public K getKey() {
			return key;
		}

		/**
		 * Value of this this <code>Pair</code>.
		 */
		private V value;

		/**
		 * Gets the value for this pair.
		 * 
		 * @return value for this pair
		 */
		public V getValue() {
			return value;
		}

		/**
		 * Creates a new pair
		 * 
		 * @param key   The key for this pair
		 * @param value The value to use for this pair
		 */
		public Pair(K key, V value) {
			this.key = key;
			this.value = value;
		}

		/**
		 * <p>
		 * <code>String</code> representation of this <code>Pair</code>.
		 * </p>
		 *
		 * <p>
		 * The default name/value delimiter '=' is always used.
		 * </p>
		 *
		 * @return <code>String</code> representation of this <code>Pair</code>
		 */
		@Override
		public String toString() {
			return key + "=" + value;
		}

		/**
		 * <p>
		 * Generate a hash code for this <code>Pair</code>.
		 * </p>
		 *
		 * <p>
		 * The hash code is calculated using both the name and the value of the
		 * <code>Pair</code>.
		 * </p>
		 *
		 * @return hash code for this <code>Pair</code>
		 */
		@Override
		public int hashCode() {
			// name's hashCode is multiplied by an arbitrary prime number (13)
			// in order to make sure there is a difference in the hashCode between
			// these two parameters:
			// name: a value: aa
			// name: aa value: a
			return key.hashCode() * 13 + (value == null ? 0 : value.hashCode());
		}

		/**
		 * <p>
		 * Test this <code>Pair</code> for equality with another <code>Object</code>.
		 * </p>
		 *
		 * <p>
		 * If the <code>Object</code> to be tested is not a <code>Pair</code> or is
		 * <code>null</code>, then this method returns <code>false</code>.
		 * </p>
		 *
		 * <p>
		 * Two <code>Pair</code>s are considered equal if and only if both the names and
		 * values are equal.
		 * </p>
		 *
		 * @param o the <code>Object</code> to test for equality with this
		 *          <code>Pair</code>
		 * @return <code>true</code> if the given <code>Object</code> is equal to this
		 *         <code>Pair</code> else <code>false</code>
		 */
		@Override
		public boolean equals(Object o) {
			if (this == o)
				return true;
			if (o instanceof Pair) {
				Pair pair = (Pair) o;
				if (key != null ? !key.equals(pair.key) : pair.key != null)
					return false;
				if (value != null ? !value.equals(pair.value) : pair.value != null)
					return false;
				return true;
			}
			return false;
		}
	}

}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		List<Integer> list = new ArrayList<>();
		for(int i = 0; i < n; i++) {
			list.add(sc.nextInt());
		}
		Collections.sort(list);
		int num = list.get(0);
		int pos = 0;
		int[] change = new int[n];
		for(int i = 0; i < list.size(); i++) {
			if(list.get(i) == num) {
				change[pos]++;
			} else {
				num = list.get(i);
				pos++;
				change[pos]++;
			}
		}
		list.clear();
		for(int i = 0; i < n; i++) {
			if(change[i] != 0) {
				list.add(change[i]);
			} else
				break;
		}
		Collections.sort(list);
		Collections.reverse(list);
		for(int i = 1; i < n + 1; i++) {
			List<Integer> copy = new ArrayList<>(list);
			if(copy.size() < i) {
				System.out.println(0);
			} else {
				List<Integer> min = new ArrayList<>();
				for(int j = 0; j < i; j++) {
					min.add(copy.get(j));
				}
				Collections.sort(min);
				for(int j = i; j < copy.size(); j++) {
					min.add(min.get(0) + copy.get(j));
					min.remove(0);
					Collections.sort(min);
				}
				System.out.println(min.get(0));
			}
		}
	}

}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int[] A = new int[N];
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < N; i++) {
            A[i] = scanner.nextInt();
            if (map.containsKey(A[i])) {
                map.put(A[i], map.get(A[i]) + 1);
            } else {
                map.put(A[i], 1);
            }
        }
        Integer[] B = new Integer[map.size()];
        int index = 0;
        for (Integer i : map.keySet()) {
            B[index] = map.get(i);
            index++;
        }
        Arrays.sort(B, Collections.reverseOrder());

        System.out.println(N);

        for (int i = 1; i < N; i++) {
            Integer[] c = Arrays.copyOf(B, B.length);
            System.out.println(doSomething(i, c));
        }
    }

    private int doSomething(int i, Integer[] c) {
        int ans = 0;
        if(c.length <= i) return 0;
        while(true){
            int min = c[i];
            ans += min;
            for (int j = 0; j < i + 1; j++) {
                if (c[j] == 0) return ans;
                c[j] -= min;
            }
            Arrays.sort(c, Collections.reverseOrder());
        }
    }
}

