public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int A[] = new int[30001];
		for(int i = 0 ; i < N ; ++i){
			int ai = sc.nextInt();
			A[ai]++;
		}
		Arrays.sort(A);
		int freq[] = new int[30001];
		for(int a : A){
			if(a == 0){
				continue;
			}
			freq[a]++;
		}
		long C[] = new long[N + 1];
		long D[] = new long[N + 1];
		for(int f = 1 ; f <= N ; ++f){
			C[f] = C[f - 1] + f * freq[f];
			D[f] = D[f - 1] + freq[f];
		}
		int X[] = new int[N  + 1];
		for(int x = 1 ; x <= N ; ++x){
			long f = C[x] + x * (D[N] - D[x]);
			f = f / x;
			X[x] = (int)f;
		}
		int res[] = new int[N + 1];
		res[1] = N;
		for(int i = N - 1 ; i >= 1 ; --i){
			if(X[i + 1] != X[i]){
				for(int j = X[i + 1] + 1; j <= X[i] ; ++j){
					res[j] = i;
				}
			}
		}
		for(int k = 1 ; k <= N ; ++k){
			System.out.println(res[k]);
		}
	}
}

import java.util.HashMap;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scn = new Scanner(System.in);
		int N = scn.nextInt();
		int[] A = new int[N];
		HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();
		for (int i = 0; i < N; i++) {
			int a = scn.nextInt();
			A[a - 1]++;
		}

		for (int i = 0; i < N; i++) {
			if (A[i] == 0)
				continue;
			map.put(i, A[i]);
		}

		int shurui = map.size();
		for (int i = 1; i <= N; i++) {
			if (i > shurui) {
				System.out.println(0);
				continue;
			}
			if(i == 1) {
				System.out.println(N);
				continue;
			}

			int ans = 0;
			PriorityQueue<Integer> PQ = new PriorityQueue<Integer>();// (数, 数値)
			setPQ(PQ, A);

			while (PQ.size() >= i) {
				int[] P = new int[i];
				for (int j = 0; j < i; j++) {
					P[j] = PQ.poll();
				}
				ans += P[i - 1];
				for (int j = 0; j < i; j++) {
					P[j] -= P[i - 1];
				}
				for(int j = 0;j < i;j++) {
					if(P[j]!=0) {
						PQ.add(P[j]);
					}
				}
			}
			System.out.println(ans);
		}

	}

	public static void setPQ(PriorityQueue<Integer> PQ, int[] A) {
		for (int i = 0; i < A.length; i++) {
			if (A[i] == 0)
				continue;
			PQ.add(A[i]);
		}

	}
}

