    static class FDistinctNumbers {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = in.readIntArray(n);
            int[] count = new int[n];

            for (int x : a) {
                count[x - 1]++;
            }

            int max = 0;
            for (int x : count) {
                max = Math.max(x, max);
            }

            int remain = n - max;
            // remain >= answer * (k-1)
            // answer <= remain / (k-1)

            out.println(n); // k=1
            for (int k = 2; k <= n; k++) {
                out.println(Math.min(n / k, remain / (k - 1)));
            }
        }

    }

