		}
		int pre = 0;
		int preCnt = 0;
		int uniq = 0;
		List<Integer> uniqList = new ArrayList<>();
		PARENT: while(true) {
			Iterator<Integer> ite = list.iterator();
			while(ite.hasNext()) {
				int i = ite.next();
				if(i != pre) {
					pre = i;
					preCnt = 0;
					uniq++;
					ite.remove();
				} else if(i == pre) {
					preCnt++;
				}
				if(list.size() == 0) {
					uniqList.add(uniq);
