		int A[] = new int[300001];
		for(int i = 0 ; i < N ; ++i){
			int ai = sc.nextInt();
			A[ai]++;
		}
		int freq[] = new int[300001];
		for(int a : A){
			if(a == 0){
				continue;
			}
			freq[a]++;
		}
		long C[] = new long[N + 1];
		long D[] = new long[N + 1];
		for(int f = 1 ; f <= N ; ++f){
			C[f] = C[f - 1] + f * freq[f];
			D[f] = D[f - 1] + freq[f];
		}
		int X[] = new int[N  + 1];
		for(int x = 1 ; x <= N ; ++x){
			long f = C[x] + x * (D[N] - D[x]);
			f = f / x;
			X[x] = (int)f;
		}
