  private static long f(int k, long[] b, long[] bs) {
    long ok = 0;
    long ng = Long.MAX_VALUE / 100000;

    int n = b.length - 1;
    while (ng - ok > 1) {
      long x = (ok + ng) / 2;


      int i = Arrays.binarySearch(b, x);
      if (i < 0) {
        i = -i - 1;
      }

      long sum = (n - i + 1) * x + bs[i - 1];

      if (sum / k >= x) {
        ok = x;
      } else {
        ng = x;
      }
    }
    return ok;
  }

