public class Main {

  private static void solve() {
    int n = ni();

    int[] a = na(n);
    int max = Arrays.stream(a).max().getAsInt();
    int[] b = new int[max + 1];
    for (int v : a) {
      b[v]++;
    }
    int[] cnt = new int[max + 1];
    for (int v : b) {
      cnt[v]++;
    }
    int[][] c = new int[max + 1][2];
    int ptr = 0;
    for (int i = max; i > 0; i--) {
      if (cnt[i] > 0) {
        c[ptr][0] = cnt[i];
        c[ptr][1] = i;
        ptr++;
      }
    }
    c = Arrays.copyOf(c, ptr);

    int[][] d = new int[ptr][2];
    for (int k = 1; k <= n; k++) {

      for (int i = 0; i < ptr; i++) {
        d[i][0] = c[i][0];
        d[i][1] = c[i][1];
      }
      int ret = 0;
      for (int i = 0; i < ptr; i++) {
        ret += d[i][0] / k * d[i][1];
        if (i + 1 < ptr) {
          d[i + 1][0] += d[i][0] % k;
