                In:while(true){
                    Entry<Integer, Integer> e=pre.pollFirstEntry();
                    if(isNull(e)) break Out;
                    int key=e.getKey();
                    int val=e.getValue();
                    if(val<k){
                        k-=val;
                        if(now.get(key)>val) now.put(key, now.get(key)-val);
                        else now.remove(key);
                        if(key>1){
                            Integer v=now.putIfAbsent(key-1, val);
                            if(nonNull(v)) now.put(key-1, v+val);
