                        if(key>1){
                            Integer v=now.putIfAbsent(key-1, k);
                            if(nonNull(v)) now.put(key-1, v+k);
                        }
                        k=m;
                        break In;
                    }
                }
                pre=(TreeMap<Integer, Integer>) now.clone();
            }
            // System.out.println();
            ans[m-1]=cnt;
        }
