public class Program
{
    private int N;
    private int[] A;
    private List<int> Ar;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        var map = new HashMap<int, int>();
        foreach (int i in A)
        {
            map[i]++;
        }

        Ar = new List<int>();
        foreach (var i in map)
        {
            Ar.Add(i.Value);
        }

        var sb = new StringBuilder();
        for (int i = 1; i <=N ; i++)
        {
            sb.AppendLine(Query(i).ToString());
        }
        Console.Write(sb.ToString());
    }

    private int Query(int k)
    {
        var pq = new PriorityQueue<int>((a, b) => -a.CompareTo(b));
        foreach (int i in Ar)
        {
            pq.Enqueue(i);
        }

        int cnt = 0;
        while (pq.Count >= k)
        {
            List<int>l = new List<int>();
            for (int i = 0; i < k; i++)
            {
                l.Add(pq.Dequeue());
            }

            int min = l[k - 1];
            //Console.WriteLine(string.Join(" ",l));
            cnt += min;
            foreach (int i in l)
            {
                if (i - min <= 0) continue;
                pq.Enqueue(i-min);
            }
        }

        return cnt;
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

