class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var a = sc.IntArr;
        var cnt = new int[n];
        for (int i = 0; i < n; i++)
        {
            ++cnt[a[i] - 1];
        }
        Array.Sort(cnt);
        var ans = new long[n+ 1];
        int j = 0;
        int sum = 0;
        ans[0] = n;
        for (int i = 1; i <= n; i++)
        {
            while (j < n && cnt[j] < i) {
                sum += cnt[j];
                ++j;
            }
            ans[i] = n - j + sum / i;
        }
        // DBG(ans);
        j = n;
        for (int i = 0; i < n; i++)
        {
            while (j > 0 && i >= ans[j]) --j;
            Prt(j);
        }

    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
