public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc());

    #endregion
    public object Calc()
    {
        var N = cr.Int;
        var counts = cr.Split.Int.GroupCount().Values.ToArray().Sort();
        var cur = counts.Length;
        var ci = -1;

        // overx[i] : i以上が何個あるか
        var overx = new int[N + 1];
        for (int i = 0; i < overx.Length; i++)
        {
            while (ci + 1 < counts.Length && counts[ci + 1] < i)
            {
                cur--; ++ci;
            }
            overx[i] = cur;
        }

        // sums[i] : i個取り出したときに有効な個数
        var sums = new int[N + 1];
        for (int i = 1; i < sums.Length; i++)
            sums[i] = overx[i] + sums[i - 1];


        // cols[i] : i個取り出したときに何列まで行けるか
        var cols = new int[N + 1];
        for (int i = 1; i < cols.Length; i++)
            cols[i] = sums[i] / i;
        cols[0] = int.MaxValue;

        var res = new int[N];
        ci = N;
        for (int i = 0; i < N; i++)
        {
            var k = i + 1;
            while (cols[ci] < k) ci--;
            res[i] = ci;
        }
        return AllLines(res);
    }
}

