using System;
using System.Collections.Generic;
using System.Linq;
using CompLib.Collections;
using CompLib.Util;

public class Program
{
    private int N;
    private int[] A;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        int[] cnt = new int[N];
        for (int i = 0; i < N; i++)
        {
            cnt[A[i] - 1]++;
        }

        Array.Sort(cnt, (l, r) => r.CompareTo(l));

        int k = 0;
        var q = new Queue<(int n, int c)>();
        for (int i = 0; i < N; i++)
        {
            if (cnt[i] > 0)
            {
                k++;
                q.Enqueue((i, cnt[i]));
            }
        }

        var sorted = new int[N];
        for (int i = 0; i < N; i++)
        {
            var d = q.Dequeue();
            sorted[i] = d.n;
            if (d.c - 1 > 0) q.Enqueue((d.n, d.c - 1));
        }

        int[] last = new int[k];
        for (int i = 0; i < k; i++)
        {
            last[i] = N;
        }

        int[] next = new int[N];
        for (int i = N - 1; i >= 0; i--)
        {
            next[i] = last[sorted[i]];
            last[sorted[i]] = i;
        }

        var ft = new FenwickTree(N);
        for (int i = 0; i < k; i++)
        {
            ft.Add(next[last[i]], 1);
        }

        int[] ans = new int[N + 1];
        bool[] f = new bool[N + 1];
        for (int i = 1; i <= N; i++)
        {
            if (ft.Sum(i) == 0) ans[i]++;
            else f[i] = true;
        }

        for (int i = 1; i < N; i++)
        {
            ft.Add(next[i - 1], -1);
            if (next[i - 1] < N) ft.Add(next[next[i - 1]], 1);
            for (int j = 1; j * j <= i; j++)
            {
                if (i % j != 0) continue;
                if (!f[j] && i + j <= N && ft.Sum(i, i + j) == 0) ans[j]++;
                else f[j] = true;

                int l = i / j;
                if (j == l) continue;
                if (!f[l] && i + l <= N && ft.Sum(i, i + l) == 0) ans[l]++;
                else f[l] = true;
            }
        }

        Console.WriteLine(string.Join("\n", ans.Skip(1)));
    }

    public static void Main(string[] args) => new Program().Solve();
}

namespace CompLib.Collections
{
    using Num = Int32;

    public class FenwickTree
    {
        private readonly Num[] _array;
        public readonly int Count;

        public FenwickTree(int size)
        {
            _array = new Num[size + 1];
            Count = size;
        }

        /// <summary>
        /// A[i]にnを加算
        /// </summary>
        /// <param name="i"></param>
        /// <param name="n"></param>
        public void Add(int i, Num n)
        {
            i++;
            for (; i <= Count; i += i & -i)
            {
                _array[i] += n;
            }
        }

        /// <summary>
        /// [0,r)の和を求める
        /// </summary>
        /// <param name="r"></param>
        /// <returns></returns>
        public Num Sum(int r)
        {
            Num result = 0;
            for (; r > 0; r -= r & -r)
            {
                result += _array[r];
            }

            return result;
        }

        /// <summary>
        /// [0,i)の和がw以上になるi
        /// </summary>
        /// <param name="w"></param>
        /// <returns></returns>
        public int LowerBound(int w)
        {
            if (w <= 0) return 0;
            int x = 0;
            int k = 1;
            while (k * 2 < Count) k *= 2;
            for (; k > 0; k /= 2)
            {
                if (x + k < Count && _array[x + k] < w)
                {
                    w -= _array[x + k];
                    x += k;
                }
            }

            return x + 1;
        }

        // [l,r)の和を求める
        public Num Sum(int l, int r) => Sum(r) - Sum(l);
    }
}

