  var N int
  NextInt(&N)
  var A []int
  NextIntVec(&A)
  M := make(map[int]int)
  for _, a := range A {
    _, ok := M[a]
    if !ok { M[a] = 0 }
    M[a]++
  }
  L := make([]int, N + 1)
  for _, v := range M {
    L[v]++
    L[1]--
  }
  for i := N; 0 < i; i-- {
    L[i - 1] += L[i]
  }
  for i := N; 0 < i; i-- {
    L[i - 1] += L[i]
  }
  for i, l := range L {
    L[i] = N - l
  }
  for k := 1; k <= N; k++ {
    Write(L[N / k] / k)
  }
  return
}

