func toIntAll(ss []string) []int {
	ii := make([]int, len(ss))
	for i, s := range ss {
		ii[i] = toInt(s)
	}
	return ii
}

type Number struct {
	I int
	N int
}

type Numbers []Number

func (ns Numbers) Len() int {
	return len(ns)
}

func (ns Numbers) Swap(i, j int) {
	ns[i], ns[j] = ns[j], ns[i]
}

func (ns Numbers) Less(i, j int) bool {
	return ns[i].N > ns[j].N
}

func try(ns []Number, k int) int {
	n := 0

	for {
		for i := range ns[:k] {
			ns[i].N--
			if ns[i].N < 0 {
				return n
			}
		}
		n++
		sort.Sort(Numbers(ns))
	}
}

func main() {
	s := bufio.NewScanner(os.Stdin)
	s.Scan()
	n := toInt(s.Text())
	s.Scan()
	as := toIntAll(strings.Split(s.Text(), " "))

	ns := make([]Number, n)
	for i := 0; i < n; i++ {
		ns[i].I = i
		ns[i].N = 0
	}

	for _, a := range as {
		ns[a-1].N++
	}

	sort.Sort(Numbers(ns))

	for i := 0; i < n; i++ {
		fmt.Println(try(append([]Number{}, ns...), i+1))
	}
}

