func main() {
  io := IO{bufio.NewReaderSize(os.Stdin,100),bufio.NewWriterSize(os.Stdout,10000000)}
  n := io.NextInt()
  x := io.NextIntArray()
  a := make([]int,n)
  s := make([]int,n+1)
  for i:=0;i<n;i++ { a[x[i]-1]++ }
  sort.Ints(a)
  for i:=0;i<n;i++ { s[i+1] = s[i]+a[i] }
  ans := n
  i := n
  for k:=1;k<=n;k++ {
    for {
      for i > 0 && a[i-1] >= ans { i-- }
      if ans*(n-i)+s[i] >= ans*k { break }
      ans--
    }
    io.Println(ans)
  }
  io.Flush()
}
type IO struct {
  reader *bufio.Reader
  writer *bufio.Writer
}
func(io *IO) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := io.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(io *IO) Println(a ...interface{}) (int,error) {
  return fmt.Fprintln(io.writer,a...)
}
func(io *IO) Flush() error {
  return io.writer.Flush()
}
func(io *IO) NextInt() int {
  n,_ := strconv.Atoi(io.NextLine())
  return n
}
func(io *IO) NextIntArray() []int {
  s := strings.Fields(io.NextLine())
  a := make([]int,len(s))
  for i:=0;i<len(s);i++ { a[i],_ = strconv.Atoi(s[i]) }
  return a
}

