		for l+1 < r {
			m := (l + r) >> 1
			ll := -1
			rr++
			for ll+1 < rr {
				mm := (ll + rr) >> 1
				if counter[mm] < m {
					ll = mm
					continue
				}
				rr = mm
			}

			if (n-rr)*m+ss[rr] < m*k {
				r = m
				continue
			}

			l = m
		}
		fmt.Println(l)
	}
	writer.Flush()
}

