var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt(A ...*int) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.Atoi(L[i])
  }
}
func NextIntVec(A *[]int) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]int, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.Atoi(l)
  }
}
func NextFloat(A ...*float64) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.ParseFloat(L[i], 64)
  }
}
func NextFloatVec(A *[]float64) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]float64, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.ParseFloat(l, 64)
  }
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func MaxInt(A ...int) int {
  max := A[0]
  for _, a := range A {
    if max < a { max = a }
  }
  return max
}
func MinInt(A ...int) int {
  min := A[0]
  for _, a := range A {
    if a < min { min = a }
  }
  return min
}
func SumInt(A ...int) int {
  sum := 0
  for _, a := range A {
    sum += a
  }
  return sum
}

func Solve() {
  var N int
  NextInt(&N)
  var A []int
  NextIntVec(&A)
  C := make([]int, N + 1)
  for _, a := range A {
    C[a]++
  }
  D := make([]int, N + 1)
  for _, c := range C {
    D[c]++
  }
  KD := make([]int, N + 1)
  for i, d := range D {
    KD[i] = i * d
  }
  for i := 0; i < N; i++ {
    KD[i + 1] += KD[i]
  }
  XD := make([]int, N + 1)
  for i := N; 0 < i; i-- {
    XD[i - 1] = XD[i] + D[i]
  }
  L := make([]int, N + 1)
  for x := 1; x <= N; x++ {
    L[x] = (KD[x] + x * XD[x]) / x
  }
  for k := 1; k <= N; k++ {
    if L[1] < k {
      Write(0)
      continue
    }
    if k <= L[N] {
      Write(N)
      continue
    }
    succ, fail := 1, N
    for 1 < fail - succ {
      med := (fail + succ) / 2
      if L[med] < k {
        fail = med
      } else {
        succ = med
      }
    }
    Write(succ)
  }
  return
}

func main() {
  Solve()
  Output()
}

