def bruteforce(c, k):
    c = c.tolist()
    n = 0
    while True:
        if len(c) < k:
            return n
        for i in range(k):
            c[i] -= 1
        c = [ci for ci in c if ci != 0]
        n += 1

def diff(x):
    ret = np.zeros_like(x)
    ret[1:] = np.diff(x)
    return ret

def test(c, k):
    if k == 1:
        return np.sum(c)
    if len(c) < k:
        return 0
    f = np.sort(c[:k])
    remain = sum(c[k:])
    d = diff(f)
    cost = np.arange(len(d)) * d
    for i, cos in enumerate(cost):
        if cos <= remain:
            remain -= cos
        else:
            if i == 0:
                return f[0]
            else:
                return f[i - 1]
    return c[0] + remain // k


