import collections
import numpy as np

def reverse_counting_sort(collection, max):
    bucket = [0]*(max+1)
    for c in collection:
        bucket[c] += 1
    arr = []
    for i in range(max,-1,-1):
        if bucket[i] != 0:
            arr.extend([i]*bucket[i])
    return arr


