use std::io::{stdout, BufWriter, Write};

fn main() {
    input! {n, a: [usize1; n]};
    let mut b = vec![0; n];
    for a0 in a {
        b[a0] += 1;
    }
    let mut c = vec![0; n + 1];
    for b0 in b {
        if b0 != 0 {
            c[b0 - 1] += 1;
        }
    }
    let d = c
        .iter()
        .enumerate()
        .scan(0, |acc, (i, &x)| {
            *acc = *acc + (i + 1) * x;
            Some(*acc)
        })
        .collect::<Vec<_>>();
    let e = c
        .iter()
        .rev()
        .scan(0, |acc, &x| {
            *acc = *acc + x;
            Some(*acc)
        })
        .collect::<Vec<_>>();
    let f = d
        .iter()
        .zip(e.iter().rev().skip(1))
        .enumerate()
        .map(|(i, (d0, e0))| (d0 + (i + 1) * e0) / (i + 1))
        .collect::<Vec<_>>();

    let stdout = stdout();
    let mut stdout = BufWriter::new(stdout.lock());
    let mut k = n;
    for i in 1..(n+1) {
        while k > 0 && i > f[k-1] {
            k -= 1;
        }
        if k == 0 {
            writeln!(stdout, "{}", 0).unwrap();
        } else {
            writeln!(stdout, "{}", k).unwrap();
        }
    }
}

use std::cmp;
use std::collections::BTreeMap;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut a: Vec<usize> = sc
        .vec::<usize>(n)
        .into_iter()
        .fold(BTreeMap::new(), |mut map, a| {
            *map.entry(a).or_insert(0) += 1;
            map
        })
        .into_iter()
        .map(|(_, v)| v)
        .collect();
    a.sort();

    let mut bricks = 0;
    let mut sum = a.iter().sum::<usize>();
    let mut ans = vec![0; n + 1];
    for height in (1..(n + 1)).rev() {
        while let Some(b) = a.pop() {
            if b >= height {
                sum -= b;
                bricks += 1;
            } else {
                a.push(b);
                break;
            }
        }
        let k = sum / height + bricks;
        ans[k] = cmp::max(ans[k], height);
    }

    for k in (0..n).rev() {
        ans[k] = cmp::max(ans[k], ans[k + 1]);
    }

    for i in 1..(n + 1) {
        println!("{}", ans[i]);
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

