use std::cmp;
use std::collections::{BTreeMap, BinaryHeap};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut count: Vec<usize> = vec![0; n];
    for _ in 0..n {
        let a = sc.read::<usize>() - 1;
        count[a] += 1;
    }

    let mut nums = vec![0; n + 1];
    let mut rows = vec![];
    for count in count.into_iter() {
        if count > 0 {
            nums[count] += 1;
            rows.push(count);
        }
    }
    rows.sort();

    // num_map[count] = num;
    let num_map = nums
        .into_iter()
        .enumerate()
        .filter(|&(count, num)| count > 0)
        .collect::<BTreeMap<_, _>>();

    let mut ans_map = BTreeMap::new();
    for k in (1..(n + 1)).rev() {
        let round = n / k;
        if ans_map.contains_key(&round) {
            continue;
        }

        let mut remain = n;
        let mut cur_remain = round;
        let mut ans = 0;
        for (&row, &num) in num_map.iter().rev() {
            if row >= round {
                ans += num;
            } else {
                let sum = row * num;
                if sum >= cur_remain {
                    let sum = sum - cur_remain;
                    ans += 1;
                    ans += sum / round;
                    cur_remain = round - (sum % round);
                } else {
                    cur_remain -= sum;
                }
            }
        }

        ans_map.insert(round, ans);
    }

    let mut ans = vec![0; n + 1];
    for (round, c) in ans_map.into_iter() {
        ans[c] = round;
    }
    for i in (1..ans.len()).rev() {
        ans[i - 1] = cmp::max(ans[i], ans[i - 1]);
    }
    for i in 1..(n + 1) {
        println!("{}", ans[i]);
    }
}

fn remove(v: usize, map: &mut BTreeMap<usize, usize>) {
    let cur = *map.get(&v).unwrap();
    if cur == 1 {
        assert_eq!(map.remove(&v).unwrap(), 1);
    } else {
        map.insert(v, cur - 1);
    }
}

