    for b0 in b {
        if b0 != 0 {
            c[b0 - 1] += 1;
        }
    }
    let d = c
        .iter()
        .enumerate()
        .scan(0, |acc, (i, &x)| {
            *acc = *acc + (i + 1) * x;
            Some(*acc)
        })
        .collect::<Vec<_>>();
