/// ans[i] = min{ acc[j - 1] / (i + 1 - j) | 1 <= j <= i }
fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [usize1; n],
    }
    let mut f = vec![0; n];
    for &a in &a {
        f[a] += 1;
    }
    f.sort();
    f.reverse();
    let mut acc = vec![0; n + 1];
    for i in (0..n).rev() {
        acc[i] = acc[i + 1] + f[i];
    }
    let mut ans = vec![n + 1; n];
    let mut pos = 0;
    for i in 0..n {
        while pos < i {
            if acc[pos] / (i - pos + 1) > acc[pos + 1] / (i - pos) {
                pos += 1;
            } else {
                break;
            }
        }
        ans[i] = acc[pos] / (i - pos + 1);
    }
    let mut mi = n + 1;
    for a in ans {
        mi = min(mi, a);
        puts!("{}\n", mi);
    }
}

