use std::io::{self, Write};
use std::str::FromStr;
use std::collections::VecDeque;

struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Self { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
    fn chars(&mut self) -> Vec<char> { self.cin::<String>().chars().collect() }
    fn vec<T: FromStr>(&mut self, n: usize) -> Vec<T> { (0..n).map(|_| self.cin()).collect() }
}

fn solve(aa: Vec<usize>) -> Vec<usize> {
    let n = aa.len();

    let mut cc = vec![0; n + 1];
    for a in aa {
        cc[a] += 1;
    }

    let mut dd = vec![0; n + 1];
    for c in cc {
        dd[c] += 1;
    }

    let mut d_acc = dd.iter().skip(1).fold(0, |sum, i| sum + i);
    let mut kd_sum = 0;
    let mut ff = vec![0; n + 1];
    for i in (1..(n + 1)) {
        d_acc -= dd[i];
        kd_sum += i * dd[i];
        ff[i] = (kd_sum + i * d_acc) / i;
    }

    let mut ans = vec![0; n + 1];
    for (i, f) in ff.iter().enumerate().rev() {
        for j in (0..(f + 1)).rev() {
            if ans[j] > 0 {
                break;
            }
            ans[j] = i;
        }
    }

    ans[1..].to_vec()
}

#[test]
fn test_solve() {
    assert_eq!(solve(vec![2, 1, 2]), vec![3, 1, 0]);
    assert_eq!(solve(vec![1, 2, 3, 4, 5]), vec![5, 2, 1, 1, 1]);
}

