fn main() {
    input! {n, a: [usize1; n]};
    let mut b = vec![0; n];
    for a0 in a {
        b[a0] += 1;
    }
    b.sort_by_key(|&x| -(x as isize));
    let len = b.iter().filter(|&x| x != &0).count();
    let acc = b
        .iter()
        .scan(0, |acc, &x| Some(*acc + x))
        .collect::<Vec<_>>();
    let stdout = stdout();
    let mut stdout = BufWriter::new(stdout.lock());
    writeln!(stdout, "{}", n).unwrap();
    for i in 1..n {
        let d = n / (i + 1);
        let ans = if len < i + 1 {
            0
        } else if n - acc[i - 1] < d {
            n - acc[i - 1]
        } else {
            d
        };
        writeln!(stdout, "{}", ans).unwrap();
    }
}

