    let mut sum = vec![0; a.len() + 1];
    sum[0] = 0;
    for i in 1..a.len() + 1 {
        sum[i] = a[i - 1] + sum[i - 1];
    }

    for k in 1..n + 1 {
        let criterion = |mid: usize| -> bool {
            let idx = a.lower_bound(&mid);
            (a.len() - idx) * mid + sum[idx] >= mid * k
        };
        let (ok, _) = binary_search(0, n + 1, criterion);
        println!("{}", ok);
    }
}

