use std::cmp::{max, min};
use std::collections::BTreeMap;

fn main() {
    input! {
        n: usize,
        a: [i64; n],
    }

    let mut mm = BTreeMap::new();
    for a in a {
        *mm.entry(a).or_insert(0) += 1;
    }

    let mut v: Vec<usize> = mm.values().cloned().collect();
    v.sort();
    v.reverse();

    let mut psum: Vec<usize> = vec![0; v.len() + 1];
    for i in 0..v.len() {
        psum[i + 1] = psum[i] + v[i];
    }

    let mut acc = 0;

    let mut anss = vec![];

    for i in (0..v.len()).rev() {
        let mut l = 0;
        let mut r = i;

        {
            let chk = |m: usize| -> bool {
                let rect = v[m] * (i - m + 1);
                let sub = psum[i + 1] - psum[m];
                rect <= sub + acc
            };

            while r - l > 1 {
                let m = (l + r) / 2;
                if chk(m) {
                    r = m;
                } else {
                    l = m;
                }
            }

            if chk(l) {
                r = l;
            }

            let l = r;

            let w = i - l + 1;
            let area = psum[i + 1] - psum[l] + acc;
            let h = (area + (w - 1)) / w;
            let ans = if l > 0 { min(v[l - 1], h) } else { h };
            let ans = max(ans, v[i]);

            // eprintln!("{}: area={} w={} l={} h={}", i, area, w, l, h);

            anss.push(ans);
        }
        acc += v[i];
    }

    anss.reverse();

    for ans in anss.iter() {
        println!("{}", ans);
    }

    for _ in anss.len()..n {
        println!("0");
    }
}

use std::cmp;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);
    let mut count = vec![0; n + 1];
    for &a in a.iter() {
        count[a] += 1;
    }
    count.sort();
    let mut sum = n;
    let mut carry = 0;
    let mut ans = vec![0; n + 1];
    for turns in (1..(n + 1)).rev() {
        let k = sum / turns + carry;
        ans[k] = cmp::max(ans[k], turns);
        while let Some(c) = count.pop() {
            if c >= turns {
                sum -= c;
                carry += 1;
            } else {
                count.push(c);
                break;
            }
        }
    }

    for k in (0..n).rev() {
        ans[k] = cmp::max(ans[k + 1], ans[k]);
    }

    for i in 1..(n + 1) {
        sc.write(ans[i]);
        sc.write("\n");
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

