    for i in (0..n-1).rev() {
        e += c[i+2];
        d[i] = d[i+1] - e;
    }

    for k in 1..n+1 {
        let ans = bis(0, n+1, |x|
            d[x-1] >= x * k
        );
        writeln!(&mut buf, "{}", ans);
    }

    buf
}
