fn bis<P>(t: usize, f: usize, eval: P) -> usize
where
    P: Fn(usize) -> bool,
{
    if t + 1 == f || f + 1 == t {
        return t;
    }
    let m = (t + f) >> 1;
    if eval(m) {
        bis(m, f, eval)
    } else {
        bis(t, m, eval)
    }
}
