fn runlength<A: Copy + PartialEq>(xs: &Vec<A>) -> Vec<usize> {
    let m = xs.len();
    if m == 0 { return vec![]; }
    let mut count = 1;
    let mut result = vec![];
    for i in 0..m {
        if i > 0 {
            if xs[i - 1] == xs[i] {
                count += 1;
            } else {
                count = 1;
            }
        }
        if i == m - 1 || xs[i] != xs[i + 1] {
            result.push(count);
        }
    }
    result
}

/// Returns: cs.iter().map(|&c| min!(c, mid)).sum::<usize>()
fn min_sum(cs: &Vec<usize>, cs_acc: &Vec<usize>, m: usize, sum: usize) -> usize {
    let n = cs.len();
    if cs[n - 1] <= m { return sum }
    if cs[0] > m { return n * m }
    let mut left = 0; // cs[left] <= m
    let mut right = n - 1; // cs[right] > m
    for _ in 0..20 {
        let mid = (left + right) / 2;
        if cs[mid] <= m {
            left = mid;
        } else {
            right = mid;
        }
    }
    cs_acc[right] + (n - right) * m
}

fn solve(cs: &Vec<usize>, cs_acc: &Vec<usize>, k: usize, sum: usize) -> usize {
    if cs.len() < k { return 0 }
    let mut left = 1; // ok
    let mut right = cs.iter().sum::<usize>() + 100;
    for _ in 0..20 {
        let mid = (left + right) / 2;
        if min_sum(&cs, &cs_acc, mid, sum) >= mid * k {
            left = mid;
        } else {
            right = mid;
        }
    }
    left
}

