fn solve(aa: Vec<usize>) -> Vec<usize> {
    let n = aa.len();

    let mut cc = vec![0; n + 1];
    for a in aa {
        cc[a] += 1;
    }

    let mut dd = vec![0; n + 1];
    for c in cc {
        dd[c] += 1;
    }

    let mut d_acc = dd.iter().skip(1).fold(0, |sum, i| sum + i);
    let mut kd_sum = 0;
    let mut ff = vec![0; n + 1];
    for i in (1..(n + 1)) {
        d_acc -= dd[i];
        kd_sum += i * dd[i];
        ff[i] = (kd_sum + d_acc) / i;
    }

    let mut ans = vec![0; n + 1];
    for (i, f) in ff.iter().enumerate().rev() {
        for j in (0..(f + 1)).rev() {
            if ans[j] > 0 {
                break;
            }
            ans[j] = i;
        }
    }

    ans[1..].to_vec()
}

