use std::cmp::max;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);
    let mut count = vec![0; n + 1];
    for a in a.into_iter() {
        count[a] += 1;
    }

    let mut max_turns = vec![0; n + 1];

    let mut columns = 0;
    count.sort();
    let mut sum = count.iter().sum::<usize>();
    for turn in (1..(n + 1)).rev() {
        while let Some(c) = count.last().cloned() {
            if c >= turn {
                columns += 1;
                sum -= c;
                count.pop().unwrap();
            } else {
                break;
            }
        }
        let k = columns + sum / turn;
        max_turns[k] = max(turn, max_turns[k]);
    }

    for k in (0..n).rev() {
        max_turns[k] = max(max_turns[k], max_turns[k + 1]);
    }

    for i in 1..(n + 1) {
        println!("{}", max_turns[i]);
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
