use std::cmp;
use std::collections::BTreeMap;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut count: Vec<usize> = vec![0; n];
    for _ in 0..n {
        let a = sc.read::<usize>() - 1;
        count[a] += 1;
    }

    let mut nums = vec![0; n + 1];
    for count in count.into_iter() {
        if count > 0 {
            nums[count] += 1;
        }
    }

    // num_map[count] = num;
    let mut nums = nums
        .into_iter()
        .enumerate()
        .filter(|&(count, _)| count > 0)
        .collect::<Vec<_>>();
    nums.sort();
    nums.reverse();

    let mut ans_map = BTreeMap::new();
    for k in (1..(n + 1)).rev() {
        let round = n / k;
        if ans_map.contains_key(&round) {
            continue;
        }

        let mut cur_sum = 0;
        let mut ans = 0;
        for &(row, num) in nums.iter() {
            if row >= round {
                ans += num;
            } else {
                let sum = row * num;
                let sum = sum + cur_sum;
                ans += sum / round;
                cur_sum = sum % round;
            }
        }

        ans_map.insert(round, ans);
    }

    let mut ans = vec![0; n + 1];
    for (round, columns) in ans_map.into_iter() {
        ans[columns] = round;
    }
    for i in (1..ans.len()).rev() {
        ans[i - 1] = cmp::max(ans[i], ans[i - 1]);
    }
    for i in 1..(n + 1) {
        println!("{}", ans[i]);
    }
}

