use std::cmp::max;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let mut a: Vec<usize> = sc.vec(n);
    a.sort();
    let mut count = vec![0; n];
    for a in a.into_iter() {
        count[a - 1] += 1;
    }
    let mut a: Vec<usize> = count.into_iter().filter(|&c| c > 0).collect();
    a.sort();

    let mut sum = a.iter().sum::<usize>();
    let mut upper_count = 0;

    let mut max_k = vec![n; n + 1];
    for h in (1..(n + 1)).rev() {
        while let Some(biggest) = a.pop() {
            if biggest > h {
                sum -= biggest;
                upper_count += 1;
            } else {
                a.push(biggest);
                break;
            }
        }

        let sum = sum + upper_count * h;
        max_k[h] = sum / h;
    }

    let mut ans = vec![0; n + 1];
    for h in 0..(n + 1) {
        ans[max_k[h]] = h;
    }

    for i in (0..n).rev() {
        ans[i] = max(ans[i], ans[i + 1]);
    }

    for i in 1..(n + 1) {
        sc.write(format!("{}\n", ans[i]));
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

