/// ans[i] = min{ acc[j - 1] / (i + 1 - j) | 1 <= j <= i }
fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [usize1; n],
    }
    let mut f = vec![0; n];
    for &a in &a {
        f[a] += 1;
    }
    f.sort();
    f.reverse();
    let mut acc = vec![0; n + 1];
    for i in (0..n).rev() {
        acc[i] = acc[i + 1] + f[i];
    }
    let mut ans = vec![n + 1; n];
    for i in 0..n {
        if i >= 1 && acc[i] == acc[i - 1] { continue; }
        let mut j = 1;
        while j * j <= acc[i] {
            let idx = i + acc[i] / (j + 1);
            if idx >= i && idx < n {
                ans[idx] = min(ans[idx], j);
            }
            let idx = i + j - 1;
            if idx < n {
                ans[idx] = min(ans[idx], acc[i] / j);
            }
            j += 1;
        }
        if i + acc[i] < n {
            ans[i + acc[i]] = 0;
        }
    }
    let mut mi = n + 1;
    for a in ans {
        mi = min(mi, a);
        puts!("{}\n", mi);
    }
}

