use std::io::{Read, Write};

fn calc(m: usize, cnt: &[usize]) -> usize {
    let mut h = std::collections::BinaryHeap::new();
    for c in cnt {
        h.push(*c);
    }
    let mut s = Vec::with_capacity(m);
    let mut ans = 0;
    while h.len() >= m {
        ans += 1;
        for _ in 0..m {
            let v = h.pop().unwrap();
            if v > 1 {
                s.push(v - 1);
            }
        }
        for &v in &s {
            h.push(v);
        }
        s.clear();
    }
    ans
}

fn eval(l: usize, r: usize, x: usize, y: usize, cnt: &[usize], ans: &mut [usize]) {
    if l >= r {
        return;
    }
    if x + 1 == y {
        for i in l..r {
            ans[i] = x;
        }
        return;
    }
    let m = (l + r) / 2;
    ans[m] = calc(m, cnt);
    eval(l, m, ans[m], y, cnt, ans);
    eval(m + 1, r, x, ans[m] + 1, cnt, ans);
}

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut cnt = vec![0; n + 1];
    for _ in 0..n {
        let a: usize = it.next().unwrap().parse().unwrap();
        cnt[a] += 1;
    }
    cnt.sort();
    cnt.reverse();
    while let Some(c) = cnt.pop() {
        if c > 0 {
            cnt.push(c);
            break;
        }
    }
    let mut ans = vec![0; n + 1];
    eval(1, cnt.len() + 1, 0, n + 1, &cnt, &mut ans);
    for a in &ans[1..] {
        writeln!(out, "{}", *a).ok();
    }
}

fn main() {
    run();
}

