    for i in 1..n {
        if b[i]==b[i-1] {
            sum += 1;
        }
        else{
            v.push(sum);
            sum = 1;
        }
    }
    if sum!=0 {v.push(sum);}
    let ma = v.iter().max().unwrap();
    for k in 1..n+1 {
        if *ma <= n/k {
            println!("{}", n/k);
            continue;
        }
        let mut heap = BinaryHeap::new();
        for &i in &v {
            heap.push(i);
        }
        let mut ans = 0;
        while heap.len()>=k {
            ans += 1;
            let mut tmp = vec![];
            for j in 0..k {
                let val = heap.pop().unwrap()-1;
                if val > 0 {tmp.push(val);}
            }
            for &j in &tmp {
                heap.push(j);
            }
        }
        println!("{}", ans);
    }
}

