use std::cmp;
use std::collections::BTreeMap;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut a: Vec<usize> = sc
        .vec::<usize>(n)
        .into_iter()
        .fold(BTreeMap::new(), |mut map, a| {
            *map.entry(a).or_insert(0) += 1;
            map
        })
        .into_iter()
        .map(|(_, v)| v)
        .collect();
    a.sort();

    let mut bricks = 0;
    let mut sum = a.iter().sum::<usize>();
    let mut ans = vec![0; n + 1];
    for height in (1..(n + 1)).rev() {
        while let Some(b) = a.pop() {
            if b >= height {
                sum -= b;
                bricks += 1;
            } else {
                a.push(b);
                break;
            }
        }
        let k = sum / height + bricks;
        ans[k] = cmp::max(ans[k], height);
    }

    for k in (0..n).rev() {
        ans[k] = cmp::max(ans[k], ans[k + 1]);
    }

    for i in 1..(n + 1) {
        println!("{}", ans[i]);
    }
}

pub struct Scanner<R> {
