    cs.sort();
    let mut cs_acc = vec![0; cs.len() + 1];
    {
        for i in 0..cs.len() {
            cs_acc[i + 1] = cs_acc[i] + cs[i];
        }
    } // cs_acc[i] = sum cs[0..i)
    for k in 1..n+1 {
        put!(solve(&cs, &cs_acc, k, n));
    }
}

