use std::cmp::{max, min};
use std::collections::BTreeMap;

fn main() {
    input! {
        n: usize,
        a: [i64; n],
    }

    let mut mm = BTreeMap::new();
    for a in a {
        *mm.entry(a).or_insert(0) += 1;
    }

    let mut v: Vec<usize> = mm.values().cloned().collect();
    v.sort();
    v.reverse();

    let mut psum: Vec<usize> = vec![0; v.len() + 1];
    for i in 0..v.len() {
        psum[i + 1] = psum[i] + v[i];
    }

    let mut acc = 0;

    let mut anss = vec![];

    for i in (0..v.len()).rev() {
        let mut l = 0;
        let mut r = i;

        let chk = |m: usize| -> bool {
            let rect = v[m] * (i - m + 1);
            let sub = psum[i + 1] - psum[m];
            rect <= sub + acc
        };

        while r - l > 1 {
            let m = (l + r) / 2;
            if chk(m) {
                r = m;
            } else {
                l = m;
            }
        }

        if chk(l) {
            r = l;
        }

        let l = r;

        let w = i - l + 1;
        let area = psum[i + 1] - psum[l] + acc;
        let h = (area - (w - 1)) / w;
        let ans = if l > 0 { min(v[l - 1], h) } else { h };
        let ans = max(ans, v[i]);
        anss.push(ans);
        acc += v[i];
    }

    anss.reverse();

    for ans in anss.iter() {
        println!("{}", ans);
    }

    for _ in anss.len()..n {
        println!("0");
    }
}

