fn main() {
    use std::collections::HashMap;
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let mut map = HashMap::new();
    for _ in 0..n {
        let a: usize = scan(tokens);
        *map.entry(a).or_insert(0) += 1;
    }
    let t: Vec<usize> = {
        let mut count = Vec::with_capacity(map.len());
        for (_, c) in map {
            count.push(c);
        }
        count.sort();
        count.reverse();
        let mut t = Vec::with_capacity(count[0] + 1);
        t.push(0);
        let mut j = 0;
        for i in (1..count[0] + 1).rev() {
            while j < count.len() && count[j] >= i {
                j += 1;
            }
            t.push(j);
        }
        t
    };
    println!("{}", n);
    for k in 2..n + 1 {
        let mut i = 0;
        let mut j = t.len();
        while i + 1 < j {
            let c = (i + j) / 2;
            if t[c] < k {
                i = c;
            } else {
                j = c;
            }
        }
        let mut ans = 0;
        let mut tmp = 0;
        while j < t.len() {
            ans += (t[j] + tmp) / k;
            tmp = (t[j] + tmp) % k;
            j += 1;
            while t[i] + tmp >= k {
                ans += 1;
                tmp = (t[i] + tmp) % k;
                i -= 1;
            }
        }
        println!("{}", ans);
    }
}

use std::cmp;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut count: Vec<usize> = vec![0; n];
    for _ in 0..n {
        let a = sc.read::<usize>() - 1;
        count[a] += 1;
    }

    count.sort();
    let mut ans = vec![0; n + 1];
    let mut sum = count.iter().sum::<usize>();
    let mut popped = 0;
    for height in (1..(n + 1)).rev() {
        while let Some(c) = count.pop() {
            if c >= height {
                sum -= c;
                popped += 1;
            } else {
                count.push(c);
                break;
            }
        }

        let columns = sum / height + popped;
        ans[columns] = cmp::max(ans[columns], height);
    }
    for k in (0..n).rev() {
        ans[k] = cmp::max(ans[k], ans[k + 1]);
    }

    for k in 1..(n + 1) {
        println!("{}", ans[k]);
    }
}

