    for k in 1..n+1 {
        let ans = (0..n+1).bsearch_left_max(|op| {
            let end = freqs.bsearch_index_right_min(|f| f >= op).unwrap_or(freqs.len());
            let s = cumsum[end] + op * (freqs.len() - end);
            s >= op * k
        }).unwrap();
        println!("{}", ans);
    }
}

use std::io::*;
use std::cmp::*;


macro_rules! parse {
    ($s:expr, $($r:tt)*) => {
        let mut it = $s.trim().split_whitespace();
        _let!{it, $($r)*}
    };
}


macro_rules! _let {
    ($it:expr, ) => {};
    ($it:expr, $var:ident : $t:tt) => {
        let $var = _parse!($it, $t);
    };
    ($it:expr, $var:ident : $t:tt, $($r:tt)*) => {
        _let!{$it, $var : $t};
        _let!{$it, $($r)*};
    };
}


macro_rules! _parse {
    ($it:expr, ( $($t:tt),* )) => {
        ( $(_parse!($it, $t)),* )
    };
    ($it:expr, [ $t:tt ; $n:expr ]) => {
        (0..$n).map(|_| _parse!($it, $t)).collect::<Vec<_>>()
    };
    ($it:expr, [ $t:tt ; $n:expr, $($r:tt)* ]) => {
        (0..$n).map(|_| _parse!($it, [$t; $($r)*])).collect::<Vec<_>>()
    };
    ($it:expr, chars) => {
        _parse!($it, String).chars().collect::<Vec<char>>()
    };
    ($it:expr, $t:ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}


macro_rules! array {
    ($t:tt ; $n:expr) => {
        vec![ $t ; $n ]
    };
    ($t:tt ; $n:expr, $($r:tt)*) => {
        vec![ array![$t; $($r)*]; $n ]
    };
}


use std::fmt::Write;

fn solve(buf: String) -> String {
    parse!{
        buf,
        n: usize,
        a: [usize; n]
    }

    let mut cnt = vec![0; n];
    for x in a {
        cnt[x-1] += 1;
    }
    cnt.sort();
    cnt.reverse();

    let mut ans = String::new();
    for k in 1..n+1 {
        let mut i = k-1;
        let mut acc = 0;
        while i < n {
            acc += cnt[i];
            i += k;
        }
        write!(ans, "{}\n", acc).unwrap();
    }
    ans
}


fn main() {
    let mut buf = String::new();
    stdin().read_to_string(&mut buf).unwrap();
    print!("{}", solve(buf));
}
